INSERT INTO `ai_prep_question_bank` (`category`, `subject`, `concept`, `difficulty_level`, `scope`, `time_limit_seconds`, `question_text`, `ground_truth`, `is_active`)
VALUES
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How do you ensure responses are personalized for each user within the system?', '{"key_points": [{"id": "KP1", "description": "User Context Retrieval & Profile Assembly: Fetches explicit preferences, historical interactions, and role permissions dynamically from durable datastores.", "required": true, "acceptable_evidence": ["Technical keywords: user_id, context retrieval, domain expertise.", "Retrieves persistent user profile attributes (e.g., communication style, domain expertise, past preferences) from relational or NoSQL stores keyed by user_id.", "Injects user-specific context dynamically into prompt system instructions without hardcoding.", "Applies semantic search over past user interaction logs or vector memories to surface contextually relevant previous choices."]}, {"id": "KP2", "description": "Context Engineering & Dynamic Prompt Grounding: Formulates prompts adapting tone, complexity, and recommendations based on user state while observing token budgets.", "required": true, "acceptable_evidence": ["Technical keywords: context window, top-k, prompt grounding, user state.", "Structures system prompts with clear delimiters separating base model instructions from user-specific personalization variables.", "Controls context window consumption through summarization or top-k retrieval of user memory records.", "Calibrates output schema, terminology depth, and response verbosity to the authenticated user''s persona."]}, {"id": "KP3", "description": "Privacy Boundaries, Data Isolation & Cold Start: Enforces multi-tenant data barriers and handles users lacking historical interaction records.", "required": false, "acceptable_evidence": ["Technical keywords: GDPR, CCPA, data isolation, user isolation.", "Guarantees tenant and user isolation so one user''s personalization data never leaks into another''s prompt context.", "Defines fallback heuristic defaults or onboarding questionnaires to address cold-start scenarios for new users.", "Complies with privacy regulations (GDPR/CCPA) by honoring user preferences to clear personal history or opt out of personalization."]}], "critical_failures": ["Suggests fine-tuning a separate foundation model for each individual user rather than runtime context injection.", "Ignores user isolation or data privacy boundaries, risking cross-user prompt leakage."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How do you ensure robustness and reliability in safety-critical ML systems such as those used in autonomous environments?', '{"key_points": [{"id": "KP1", "description": "Deterministic Safety Envelopes & Redundant Architecture: Decouples probabilistic model outputs from non-negotiable physical or system safety invariants.", "required": true, "acceptable_evidence": ["Technical keywords: ML, redundant architecture, envelopes, redundant.", "Implements code-level deterministic safety interlocks and rule-based physical constraints that override ML inference.", "Employs dual-channel or redundant architectures (e.g., primary neural model paired with verified simple rule-based shadow monitor).", "Guarantees bounded latency and predictable behavior through real-time deterministic execution paths."]}, {"id": "KP2", "description": "Uncertainty Estimation & Out-of-Distribution Detection: Detects distribution shifts, low-confidence predictions, and sensor degradation.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, OOD, statistical drift, passive states.", "Calculates model uncertainty or prediction entropy (e.g., conformal prediction, Bayesian approximations, temperature scaling).", "Deploys statistical drift monitors and OOD classifiers to detect unmodeled edge cases before actuation.", "Triggers graceful degradation to safe passive states or minimum risk maneuvers when confidence falls below safety thresholds."]}, {"id": "KP3", "description": "Rigorous Validation, Simulation & Immutable Auditing: Validates against synthetic edge scenarios and preserves tamper-proof telemetry.", "required": false, "acceptable_evidence": ["Technical keywords: HIL, ISO, IEC, rigorous validation.", "Runs automated hardware-in-the-loop (HIL) and synthetic adversarial edge-case stress simulations.", "Maintains continuous black-box flight recorder telemetry logging sensor inputs, model logits, and actuation decisions.", "Establishes formal verification pipelines conforming to industry safety standards (ISO 26262, IEC 61508)."]}], "critical_failures": ["Permits unconstrained probabilistic model outputs to directly trigger irreversible physical actuations without hard deterministic limits.", "Fails to specify any fallback, failsafe state, or uncertainty detection mechanism when the ML model encounters an unknown environment."]}', 1),
('TECHNICAL', 'DevOps and Cloud', 'Infrastructure as Code & Security', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure secure development practices, particularly in managing secrets and credentials?', '{"key_points": [{"id": "KP1", "description": "Centralized Vault Storage & Ephemeral Secrets: Stores credentials in dedicated KMS/Vault platforms rather than plaintext environment files or repos.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, IAM, KMS, AWS.", "Utilizes dedicated secrets managers (AWS Secrets Manager, HashiCorp Vault, Azure Key Vault).", "Implements short-lived dynamic credentials, IAM instance profiles, or workload identity federation over static long-lived API keys.", "Injects secrets at container runtime via encrypted environment variables or sidecar CSI drivers, never baking them into Docker images."]}, {"id": "KP2", "description": "Automated Secret Detection & CI/CD Guardrails: Prevents accidental secrets commit through pre-commit hooks and pipeline scanning.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, TruffleHog.", "Configures git pre-commit hooks (TruffleHog, Gitleaks, detect-secrets) to block credentials before code push.", "Enforces static analysis in CI/CD pipelines to fail builds containing high-entropy strings or known token patterns.", "Applies strict repository `.gitignore` hygiene for local `.env` and configuration files."]}, {"id": "KP3", "description": "Automated Secret Rotation & Incident Revocation: Manages credential lifecycle, scheduled rotations, and emergency leak remediation.", "required": false, "acceptable_evidence": ["Technical keywords: SIEM, automated, secret, incident.", "Configures automatic rotation lambdas or vault rotation schedules without application downtime.", "Maintains immediate revocation runbooks and blast-radius audits upon detecting a compromised credential.", "Monitors access logs and SIEM alerts for anomalous secret access patterns."]}], "critical_failures": ["Advocates storing secrets directly in git repositories, unencrypted Dockerfiles, or unversioned production servers.", "Fails to identify automated tooling to detect or prevent committed API keys and credentials."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How do you ensure that your user interfaces comply with WCAG accessibility standards?', '{"key_points": [{"id": "KP1", "description": "Semantic HTML & Accessible Tree Structuring: Uses native HTML elements and appropriate WAI-ARIA roles to convey UI structure.", "required": true, "acceptable_evidence": ["Technical keywords: HTML, WAI-ARIA, UI, AI.", "Prioritizes semantic HTML (<main>, <nav>, <button>, <form>) over generic non-semantic <div> tags.", "Implements correct WAI-ARIA roles, states, and properties (aria-expanded, aria-live for streaming AI responses, aria-label) when semantic tags are insufficient.", "Provides descriptive text alternatives (alt text) for non-text content, data visualizations, and charts."]}, {"id": "KP2", "description": "Keyboard Navigability & Visual Accommodations: Ensures operable interfaces via keyboard, proper focus management, and contrast.", "required": true, "acceptable_evidence": ["Technical keywords: WCAG, AA, Tab, Shift+Tab.", "Guarantees complete keyboard navigability (Tab, Shift+Tab, Enter, Escape) and traps focus properly in modals and dialogs.", "Maintains visible, high-contrast focus rings and avoids disabling browser default outlines without custom styling.", "Meets WCAG AA color contrast ratios (at least 4.5:1 for normal text, 3:1 for large text) and avoids conveying info via color alone."]}, {"id": "KP3", "description": "Automated & Assistive Technology Testing: Integrates linting, automated CI audits, and screen reader verification.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, NVDA.", "Integrates automated accessibility audit engines (axe-core, Lighthouse, eslint-plugin-jsx-a11y) into CI/CD pipelines.", "Validates interactive user flows using actual screen reader assistive software (NVDA, VoiceOver, JAWS).", "Tests at high zoom levels (200%-400%) without horizontal scrolling or UI breakage."]}], "critical_failures": ["Relies entirely on generic <div> and <span> click handlers without keyboard event handling or focus management.", "Fails to describe any automated or manual accessibility testing methodology."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'How do you ensure you are proactive and responsive during an interview rather than waiting for instructions?', '{"key_points": [{"id": "KP1", "description": "Clarifying Inquiries & Scope Prototyping: Takes the initiative to disambiguate problem constraints before coding or designing.", "required": true, "acceptable_evidence": ["Technical keywords: clarifying, inquiries, scope, prototyping.", "Proactively asks clarifying questions regarding edge cases, scale requirements, latency bounds, and data volume.", "States assumptions explicitly and validates them with the interviewer before committing to an architecture.", "Frames the problem into clear milestones or stages to structure the discussion."]}, {"id": "KP2", "description": "Transparent Thought Process & Interactive Collaboration: Verbalizes internal trade-offs and checks in with the interviewer regularly.", "required": true, "acceptable_evidence": ["Technical keywords: transparent, thought, interactive, verbalizes.", "Thinks out loud, walking the interviewer through why specific algorithms, models, or data structures are considered.", "Pauses periodically to confirm alignment with interviewer expectations rather than monologuing silently.", "Pivots quickly and receptively when given feedback or hints by the interviewer."]}, {"id": "KP3", "description": "Driving the Problem-Solving Roadmap: Progresses from high-level solution to edge cases and optimization without waiting to be prompted.", "required": false, "acceptable_evidence": ["Technical keywords: driving, problem, solving, roadmap.", "Transitions naturally from high-level design to deep-dive implementation, complexity analysis, and failure recovery.", "Suggests realistic edge-case testing and production operational concerns independently.", "Demonstrates enthusiasm and genuine curiosity about the company''s real-world engineering challenges."]}], "critical_failures": ["Passively waits for the interviewer to dictate every step without asking clarifying questions or offering proposed approaches.", "Codes or designs in extended silence without explaining reasoning or engaging the interviewer."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you incorporate user feedback into iterative improvements of an AI system?', '{"key_points": [{"id": "KP1", "description": "Multi-Modal Feedback Telemetry Collection: Captures explicit ratings, corrections, and implicit interaction telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: feedback telemetry, interaction telemetry, engagement telemetry, feedback payloads.", "Collects explicit feedback mechanisms (thumbs up/down, free-text bug reports, edited response text).", "Monitors implicit engagement telemetry (dwell time, prompt retries, session abandonment, copy-paste actions).", "Correlates user feedback payloads with full request traces, input prompts, retrieved chunks, and model configurations."]}, {"id": "KP2", "description": "Curated Triage & Evaluation Dataset Expansion: Transforms low-scoring interactions into golden test cases to prevent regressions.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, DeepEval, retrieval gap, tone.", "Filters and clusters negative feedback instances using embedding similarity or error taxonomies (hallucination, retrieval gap, tone).", "Involves domain experts or human-in-the-loop reviewers to annotate and construct gold evaluation test pairs.", "Incorporates validated failure cases into automated regression suites (DeepEval, Ragas) to benchmark future builds."]}, {"id": "KP3", "description": "Iterative System Interventions & Safe Deployment: Deploys targeted prompt refinements, reranking adjustments, or DPO/RLHF pipelines safely.", "required": false, "acceptable_evidence": ["Technical keywords: system prompt, fine-tuning, RLHF, DPO.", "Prioritizes low-cost upstream interventions (system prompt few-shot additions, reranker threshold adjustments) before expensive model fine-tuning.", "Applies Direct Preference Optimization (DPO) or supervised fine-tuning when systematic behavioral shifts are required.", "Evaluates updated candidate models against the historical golden suite and releases via canary or shadow deployment."]}], "critical_failures": ["Directly retrains or fine-tunes models on raw, unvalidated user feedback without human triage or guardrails, risking model poisoning.", "Fails to describe any regression testing before deploying feedback-driven updates to production."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you incrementally ramp up in a new system while minimizing risk and ensuring productivity?', '{"key_points": [{"id": "KP1", "description": "System Discovery & Architectural Mapping: Absorbs domain models, CI/CD pipelines, and dependencies systematically.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, API.", "Reviews system architecture documentation, data schemas, API contracts, and runbooks to build a mental map.", "Sets up local development environments and verifies end-to-end test execution independently.", "Maps production telemetry dashboards, alerting thresholds, and error logs to understand system health."]}, {"id": "KP2", "description": "Low-Risk Value Delivery & Incremental Execution: Starts with small, well-bounded tasks to learn development workflows safely.", "required": true, "acceptable_evidence": ["Technical keywords: PR, release pipeline, value, incremental.", "Picks up starter bugs, documentation gaps, or unit test improvements to validate the PR and release pipeline.", "Shadows on-call engineers during incident triage to observe live failure modes and operational cadence.", "Seeks peer code review feedback early to align with team code conventions and testing standards."]}, {"id": "KP3", "description": "Cross-Functional Collaboration & Scaling Impact: Engages stakeholders, pairs with teammates, and expands feature ownership.", "required": false, "acceptable_evidence": ["Technical keywords: cross, scaling, impact, engages.", "Conducts introductory 1-on-1s with product managers, data engineers, and key dependencies to understand priorities.", "Proactively documents onboarding frictions to improve developer guides for future team members.", "Transitions towards owning substantial system components or architectural initiatives with high autonomy."]}], "critical_failures": ["Attempts major uncoordinated architectural refactors immediately upon joining without understanding existing business constraints.", "Remains passive for weeks waiting for explicit micro-management rather than proactively delivering small unblocking wins."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'How do you manage and update character counts efficiently within a sliding window?', '{"key_points": [{"id": "KP1", "description": "O(1) Incremental Frequency Updating: Adjusts character counts by incrementing on window expansion and decrementing on contraction.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), window expansion, window contraction.", "Explains incrementing frequency count for the incoming character at the right pointer (window expansion).", "Explains decrementing frequency count for the outgoing character at the left pointer (window contraction).", "Avoids scanning or recounting characters inside the entire window on every step, maintaining O(1) amortized updates."]}, {"id": "KP2", "description": "Optimal Data Structure Selection: Chooses fixed-size integer arrays or hash tables based on alphabet size.", "required": true, "acceptable_evidence": ["Technical keywords: collections.Counter, ASCII, int[26], int[128] for ASCII.", "Utilizes fixed-size integer arrays (e.g., int[26] or int[128] for ASCII) for zero-overhead index lookups and constant O(1) space.", "Uses hash maps (e.g., Python collections.Counter or dict) when character sets are arbitrary Unicode.", "Removes keys or checks for zero counts when tracking the count of distinct unique characters in the window."]}, {"id": "KP3", "description": "Algorithmic Invariants & Complexity: Discusses overall O(N) linear time complexity and window condition verification.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, O(n), condition state, matching character counter.", "Proves overall O(N) time complexity since each string character enters and exits the window at most once.", "Maintains secondary condition state (e.g., valid unique count or matching character counter) in O(1) time alongside frequency updates.", "Handles edge cases: empty strings, single-character strings, or windows where left exceeds right."]}], "critical_failures": ["Recalculates character counts across the full window from scratch on each iteration, degrading complexity to O(N^2) or O(N*K).", "Fails to decrement counts when the left window pointer advances, corrupting frequency state."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'How do you manage multiple interview processes and keep recruiters updated on your progress?', '{"key_points": [{"id": "KP1", "description": "Structured Pipeline Tracking: Maintains organized records of application stages, interview dates, and action items.", "required": true, "acceptable_evidence": ["Technical keywords: Notion, Trello, pipeline, tracking.", "Uses a spreadsheet, Kanban board (Notion/Trello), or tracking tool to record company stages, interviewers, and follow-ups.", "Prepares domain-specific questions and technical review notes prior to each scheduled round.", "Ensures prompt scheduling and respects interviewers'' calendar availability."]}, {"id": "KP2", "description": "Transparent & Proactive Recruiter Communication: Keeps recruiter partners informed of pending deadlines and offer timelines.", "required": true, "acceptable_evidence": ["Technical keywords: transparent, proactive, recruiter, keeps.", "Notifies recruiters proactively when advancing to final rounds or receiving exploding offer deadlines elsewhere.", "Communicates schedule constraints and availability clearly without ghosting or sudden cancellations.", "Sets realistic expectations regarding decision timelines while maintaining genuine interest in the role."]}, {"id": "KP3", "description": "Ethical Offer Synchronization & Negotiation: Aligns offer stages constructively without using deceptive pressure.", "required": false, "acceptable_evidence": ["Technical keywords: ethical, offer, negotiation, aligns.", "Requests reasonable timeline extensions respectfully to conclude parallel ongoing interviews.", "Demonstrates integrity by promptly declining offers once a final decision is reached rather than holding multiple offers indefinitely.", "Expresses gratitude to hiring teams and recruiters regardless of whether an offer is accepted."]}], "critical_failures": ["Ghosts recruiters, misses scheduled interviews without notice, or acts deceptively regarding timeline status.", "Fails to manage scheduling, causing preventable calendar conflicts across multiple companies."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you measure the impact and adoption of AI tools using quantitative metrics?', '{"key_points": [{"id": "KP1", "description": "Usage & Adoption Telemetry: Measures user engagement, frequency, and suggestion acceptance rates.", "required": true, "acceptable_evidence": ["Technical keywords: DAU, WAU, MAU, AI.", "Tracks Active Users (DAU/WAU/MAU) and tool invocation volume across engineering cohorts.", "Measures direct user acceptance rates (e.g., % of AI code suggestions accepted, % of generated docs merged).", "Analyzes retention and cohort churn to determine if engineers continue using the tool past the initial novelty curve."]}, {"id": "KP2", "description": "Workflow Velocity & Quality Impact: Measures downstream impact on delivery speed, throughput, and error rates.", "required": true, "acceptable_evidence": ["Technical keywords: DORA, MTTR, PR, dora metrics.", "Evaluates DORA metrics: Deployment Frequency, Lead Time for Changes, Mean Time to Recovery (MTTR), and Change Failure Rate.", "Measures cycle time reductions in targeted tasks (e.g., time to author unit tests, time to draft PR summaries).", "Monitors code quality and security metrics (sonar findings, bug escape rate) to verify speed did not degrade software hygiene."]}, {"id": "KP3", "description": "Developer Experience & Financial ROI: Balances qualitative satisfaction (SPACE framework) with infrastructure token costs.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, SPACE, CSAT, LLM.", "Conducts periodic developer satisfaction surveys (CSAT / Net Promoter Score for developer tools).", "Calculates net economic ROI by comparing engineering hours saved against monthly LLM API and tooling seat costs.", "Establishes controlled A/B test groups (teams with tool vs control teams without) to isolate causal productivity gains."]}], "critical_failures": ["Relies purely on subjective anecdotes without measuring any objective adoption, DORA, or engagement metrics.", "Ignores quality or safety regressions, assuming increased lines of AI-generated code automatically equals higher productivity."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How do you persist and manage conversational memory across sessions?', '{"key_points": [{"id": "KP1", "description": "Tiered Persistence Architecture: Decouples low-latency in-memory session state from durable cross-session datastores.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, PostgresSaver, PostgreSQL.", "Stores short-term active session turns in fast memory/cache (Redis, LangGraph StateGraph memory) keyed by session_id.", "Persists durable cross-session user facts, preferences, and interaction summaries in relational databases (PostgreSQL/PostgresSaver) or vector stores.", "Structures persistent records with user_id, conversation_id, timestamp, and message role metadata."]}, {"id": "KP2", "description": "Context Engineering & Memory Compaction: Applies sliding window trimming, recursive summarization, and semantic extraction.", "required": true, "acceptable_evidence": ["Technical keywords: context window, sliding window, top-k, vector search.", "Applies recursive summarization to condense completed conversation threads into succinct persistent user profiles.", "Uses sliding-window truncation with token counters to prevent prompt context window exhaustion.", "Executes semantic vector search over past session summaries to retrieve only top-k relevant historical context for the current turn."]}, {"id": "KP3", "description": "Staleness Control, Eviction & Privacy: Manages conflicting facts, TTL expiration, and regulatory memory deletion.", "required": false, "acceptable_evidence": ["Technical keywords: GDPR, TTL, LRU eviction, LRU.", "Implements conflict resolution or recency weighting when user statements contradict older persisted facts.", "Enforces Time-To-Live (TTL) and LRU eviction policies for inactive sessions to control storage overhead.", "Provides user-facing deletion APIs (right-to-be-forgotten / GDPR) to wipe persistent memory history securely."]}], "critical_failures": ["Dumps unbounded raw chat message history into the system prompt for every session without truncation or summarization.", "Fails to persist memory to durable storage, causing all user context to vanish when a server restarts or session disconnects."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How do you prevent the system from exposing sensitive information when a user explicitly requests PII?', '{"key_points": [{"id": "KP1", "description": "Data Pipeline Ingestion Redaction: Ensures sensitive PII is sanitized at the source before indexing or prompt grounding.", "required": true, "acceptable_evidence": ["Technical keywords: Microsoft Presidio, PII, NER, data pipeline.", "Applies Microsoft Presidio Analyzer or spaCy NER pipelines during data ingestion to redact SSNs, credit cards, emails, and phone numbers.", "Replaces detected PII entities with synthetic surrogates or typed placeholders (<REDACTED_SSN>) before chunking and embedding generation."]}, {"id": "KP2", "description": "Stores original sensitive data in encrypted vaults accessible only via strict RBAC, never in vector search payloads.", "required": true, "acceptable_evidence": ["Technical keywords: encrypted vault, HashiCorp Vault, AWS KMS, RBAC, vector search isolation, PII masking.", "Stores original sensitive data in encrypted vaults accessible only via strict RBAC, never in vector search payloads.", "Stores raw sensitive attributes in an encrypted relational database or secrets vault accessible only via strict RBAC, ensuring vector embeddings and prompt contexts only contain sanitized tokens."]}, {"id": "KP3", "description": "Adversarial Prompt Detection & Input Guardrails: Detects prompt extraction attempts, jailbreaks, and malicious PII queries.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, input guardrails, NeMo, AI.", "Employs input guardrail classifiers (NeMo Guardrails, Llama Guard, Azure AI Content Safety) to detect adversarial extraction intent.", "Applies deterministic regex rules and entity recognizers on user prompts to flag requests probing for sensitive identity data.", "Terminates requests or issues safe standard refusal responses early before invoking downstream models or RAG retrieval."]}, {"id": "KP4", "description": "Output Inspection & Immutable Audit Trails: Inspects generated responses before transmission and logs redaction alerts.", "required": false, "acceptable_evidence": ["Technical keywords: LLM, SIEM, sensitive payloads, Presidio Anonymizer.", "Runs secondary output scanners (Presidio Anonymizer / regex validators) on the LLM output stream to catch accidental model leaks.", "Enforces document-level and chunk-level Access Control Lists (ACLs) so retrieval never returns unauthorized documents.", "Logs security telemetry and triggers SIEM alerts on repeated PII extraction attempts without writing sensitive payloads to logs."]}], "critical_failures": ["Relies exclusively on LLM system prompt instructions (''Please do not reveal PII'') to prevent data leakage.", "Permits raw, unmasked PII into the vector database or knowledge base context without access-control filtering."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'HARD', 'BROAD', 210, 'How do you process and structure large documents, including handling OCR, tables, and metadata extraction, before feeding them into downstream systems?', '{"key_points": [{"id": "KP1", "description": "Layout-Aware Parsing & OCR Pipelines: Employs modern parsers and OCR to preserve reading order across complex multi-column documents.", "required": true, "acceptable_evidence": ["Technical keywords: Unstructured.io, OCR, IBM, AWS.", "Utilizes layout-aware document parsers such as IBM Docling, Unstructured.io, or PyMuPDF to extract structural hierarchies (headers, sections, lists).", "Applies OCR engines (Tesseract, AWS Textract, paddleOCR) for scanned PDFs or embedded image figures."]}, {"id": "KP2", "description": "Preserves logical reading order across multi-column layouts rather than reading across columns horizontally.", "required": true, "acceptable_evidence": ["Technical keywords: IBM Docling, LayoutLM, Unstructured, bounding box segmentation, reading order preservation, multi-column PDF parsing.", "Preserves logical reading order across multi-column layouts rather than reading across columns horizontally.", "Employs layout analysis models (IBM Docling, LayoutLM, or Unstructured) to segment multi-column PDF bounding boxes and sequence text in correct reading order."]}, {"id": "KP3", "description": "Table Structuring & Linearization: Converts tabular data into machine-readable Markdown/HTML while preserving semantic context.", "required": true, "acceptable_evidence": ["Technical keywords: HTML, vector retrieval, table, structuring.", "Extracts table boundaries and serializes rows and headers into structured Markdown tables or HTML tables to preserve cell relationships.", "Prepends section titles and table captions to tabular chunks so isolated rows retain domain meaning during vector retrieval.", "Splits oversized tables across rows while repeating header rows across chunks to prevent context loss."]}, {"id": "KP4", "description": "Semantic Chunking & Metadata Enrichment: Partitions content into sized chunks enriched with retrieval metadata.", "required": false, "acceptable_evidence": ["Technical keywords: semantic chunking, Pinecone, Milvus, document_id.", "Applies semantic or hybrid chunking (e.g., target 512 tokens with 10-20% overlap) bounded at section/paragraph boundaries.", "Attaches rich metadata to each chunk: document_id, page_number, section_header, tenant_id, creation_date, and author.", "Computes content hashes (SHA-256) per chunk for idempotent upserts and deduplication in the vector index (Milvus/Pinecone)."]}], "critical_failures": ["Uses naive character-count chunking that splits tables, words, or multi-column layouts midway without preserving layout or headers.", "Fails to attach metadata (page number, document ID, section headers) to chunks for downstream citation and retrieval filtering."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'How do you stay updated with advancements in AI and software development?', '{"key_points": [{"id": "KP1", "description": "Curated Information Streams: Tracks peer-reviewed research, industry publications, and open-source ecosystems.", "required": true, "acceptable_evidence": ["Technical keywords: ArXiv, ICML, ICLR, AK.", "Follows ArXiv preprints, top conferences (NeurIPS, ICML, ICLR), and paper digests (AK''s Daily Papers, Hugging Face Daily Papers).", "Monitors leading AI engineering communities, engineering blogs (OpenAI, Anthropic, Meta AI, Uber Engineering), and GitHub releases.", "Engages with technical newsletters, podcasts, or local technical meetups."]}, {"id": "KP2", "description": "Hands-On Prototyping & Technical Spikes: Validates new models, frameworks, and tools in sandbox environments.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, MCP, spikes, MCP servers.", "Builds rapid proof-of-concept prototypes (spikes) to test claims of new frameworks (e.g., testing new rerankers, MCP servers, LangGraph features).", "Benchmarks new models on representative domain datasets rather than relying solely on vendor marketing claims.", "Maintains personal coding repositories or open-source contributions to explore new APIs."]}, {"id": "KP3", "description": "Critical Evaluation & Knowledge Sharing: Filters hype and shares learnings with the broader engineering team.", "required": false, "acceptable_evidence": ["Technical keywords: cost trade-offs, critical, knowledge, sharing.", "Distinguishes durable architectural patterns from fleeting wrapper libraries.", "Conducts team tech-talks, lunch-and-learns, or writes internal RFCs recommending framework adoptions.", "Evaluates licensing, latency, and operational cost trade-offs before advocating adoption in production."]}], "critical_failures": ["Shows no proactive learning habits, relying solely on outdated practices without awareness of current AI tooling.", "Adopts every new trending library blindly in production without sandboxing, benchmarking, or understanding trade-offs."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'EASY', 'SPECIFIC', 60, 'How do you track and update the maximum length of a valid substring during iteration?', '{"key_points": [{"id": "KP1", "description": "Window Invariant Verification: Updates length metrics only when current window constraints are valid.", "required": true, "acceptable_evidence": ["Technical keywords: max_len, length metrics, no repeating characters.", "Verifies window constraint validity (e.g., at most k distinct characters, no repeating characters) before updating maximum.", "Contracts the left pointer until the window becomes valid again if an invariant violation occurs.", "Updates the global maximum using `max_len = max(max_len, right - left + 1)`."]}, {"id": "KP2", "description": "Pointer Arithmetic & 1-Indexed Length Calculation: Computes valid window span accurately without off-by-one errors.", "required": true, "acceptable_evidence": ["Technical keywords: best_start, start index, `best_start = left`, max_len = 0.", "Explains why inclusive window length is calculated as `right - left + 1` for 0-indexed arrays.", "Stores optional start index (`best_start = left`) alongside max_len if substring extraction is required.", "Handles edge cases: empty strings (max_len = 0), all identical characters, or strings where no window satisfies constraints."]}, {"id": "KP3", "description": "Amortized Complexity & Monotonic Window Optimization: Discusses linear O(N) runtime and optional non-shrinking window variant.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, O(1), O(n), keeps state.", "Proves overall linear O(N) time complexity as each pointer increments at most N times.", "Discusses optimization technique where window only expands and never shrinks below current max_len.", "Keeps state tracking memory constant O(1) or bounded by alphabet size."]}], "critical_failures": ["Calculates substring length using an off-by-one error (e.g., `right - left` for an inclusive window).", "Updates maximum length while the window is in an invalid state."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How do you use a hypothesis bank to track user rejections and improve future recommendations?', '{"key_points": [{"id": "KP1", "description": "Hypothesis Formulation & Metadata Logging: Associates recommendations with explicit hypotheses or attribute assumptions.", "required": true, "acceptable_evidence": ["Technical keywords: EV, brand, price tier, genre.", "Attaches generative hypotheses to recommendations (e.g., ''User likes price-sensitive EV sedans in zip 94103'').", "Stores active hypothesis IDs alongside recommendations in a durable key-value or relational store.", "Maintains explicit feature tags (brand, price tier, genre, topic) associated with each generated hypothesis."]}, {"id": "KP2", "description": "Rejection Ingestion & Negative Belief Updating: Penalizes refuted hypotheses and updates user preference states.", "required": true, "acceptable_evidence": ["Technical keywords: preference states, negative filtering, suppression rules.", "Captures user rejection signals (dismissals, skips, explicit ''not interested'' feedback, downvotes).", "Applies Bayesian updates, bandit penalty decay, or negative embedding shifts to downweight refuted hypotheses.", "Prevents repetitive recommendations derived from invalidated hypotheses (negative filtering / suppression rules)."]}, {"id": "KP3", "description": "Exploration-Exploitation & Counterfactual Learning: Tests alternative hypotheses without trapping user in echo chambers.", "required": false, "acceptable_evidence": ["Technical keywords: CTR, Thompson Sampling, Upper Confidence Bound.", "Applies multi-armed bandit strategies (Thompson Sampling, Upper Confidence Bound) to explore alternative unrefuted hypotheses.", "Implements hypothesis decay or periodic re-testing to account for changing user tastes over time.", "Evaluates hypothesis bank accuracy using offline counterfactual evaluation and online CTR / conversion lift."]}], "critical_failures": ["Repeatedly recommends identical rejected items or concepts without updating user rejection state.", "Fails to associate user rejections with underlying recommendation attributes or hypotheses."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you validate and sanitize model inputs and outputs to prevent harmful or sensitive responses?', '{"key_points": [{"id": "KP1", "description": "Input Validation & Prompt Injection Defense: Sanitizes untrusted user input before passing it to LLM prompts.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, jailbreak, LLM, NeMo.", "Inspects input strings for prompt injection, delimiter hijacking, and jailbreak patterns using specialized classifiers (Llama Guard, NeMo Guardrails).", "Enforces length limits, character encoding normalization, and strips malicious control tokens.", "Wraps user inputs in strict XML or markdown delimiter tags with instructions warning the model to treat content as untrusted data."]}, {"id": "KP2", "description": "Output Inspection & Content Safety Filtering: Validates generated text for toxicity, hallucination, and sensitive data leakage.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, data leakage, Microsoft Presidio, API.", "Applies toxicity classifiers and moderation APIs (OpenAI Moderation, Perspective API) before returning responses to users.", "Runs automated PII/regex scanners (Microsoft Presidio) to block accidental credential, phone, or SSN emission.", "Verifies response faithfulness against retrieved RAG context using alignment models or cross-encoders to intercept hallucinations."]}, {"id": "KP3", "description": "Structured Output Enforcement & Fallback Circuit Breakers: Guarantees deterministic schemas and graceful refusal behavior.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, JSON, json schemas, toxic payloads.", "Enforces structured JSON schemas via Pydantic or constrained decoding (Instructor, Outlines) for programmatic consumers.", "Implements standardized fallback refusal responses when safety boundaries are triggered.", "Logs sanitized violation events and alerts security teams without writing sensitive or toxic payloads into plaintext logs."]}], "critical_failures": ["Relies solely on system prompt instructions without automated programmatic input/output inspection software.", "Fails to screen generated model output for sensitive data or hallucinations before presenting it to the end user."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'EASY', 'SPECIFIC', 60, 'How do you validate that a password (temporary or newly created) meets system requirements and is entered correctly?', '{"key_points": [{"id": "KP1", "description": "Complexity & Policy Enforcement: Validates length and entropy according to modern security standards (NIST SP 800-63B).", "required": true, "acceptable_evidence": ["Technical keywords: NIST, SP, side validation, NIST SP 800-63B.", "Enforces minimum length (e.g., at least 8-12 characters) and checks against compromised password blocklists (HaveIBeenPwned).", "Validates character diversity requirements or entropy thresholds while avoiding arbitrary truncation limits.", "Provides immediate, clear client-side validation feedback paired with authoritative server-side validation."]}, {"id": "KP2", "description": "Secure Hash Verification & Timing Attack Prevention: Uses adaptive hashing algorithms and constant-time comparisons.", "required": true, "acceptable_evidence": ["Technical keywords: hmac.compare_digest, Argon2id, bcrypt, PBKDF2.", "Hashes passwords using modern salted adaptive key derivation functions (Argon2id, bcrypt, PBKDF2).", "Performs password hash verification using constant-time string comparison (`hmac.compare_digest`) to prevent timing side-channel attacks.", "Never stores or logs passwords in plaintext anywhere in the application lifecycle."]}, {"id": "KP3", "description": "Temporary Password Lifecycle & Forced Reset: Enforces single-use token constraints, TTLs, and mandatory rotation.", "required": false, "acceptable_evidence": ["Technical keywords: rate limiting, temporary tokens, 15 minutes.", "Generates cryptographically random temporary passwords or magic links with short expiration TTLs (e.g., 15 minutes).", "Enforces immediate mandatory password change on first successful login with a temporary credential.", "Invalidates temporary tokens immediately upon use and applies rate limiting against brute-force login attempts."]}], "critical_failures": ["Stores or compares passwords in plaintext or uses obsolete broken hashes like MD5 or SHA1.", "Fails to enforce server-side validation, relying solely on client-side JavaScript checks."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'How does Quantcast approach click conversion optimization beyond just generating clicks?', '{"key_points": [{"id": "KP1", "description": "Down-Funnel Conversion Modeling (pCVR): Decouples click-through probability from post-click conversion probability.", "required": true, "acceptable_evidence": ["Technical keywords: class imbalance, ESMM, pCVR, pCTR.", "Models both Click-Through Rate (pCTR) and Post-Click Conversion Rate (pCVR) as distinct stages in a multi-task network (e.g., ESMM - Entire Space Multi-Task Model).", "Optimizes for true business value (purchases, signups, return on ad spend) rather than cheap click-bait impressions.", "Accounts for extreme class imbalance in conversion labels through negative downsampling and calibration."]}, {"id": "KP2", "description": "Delayed Feedback & Attribution Modeling: Handles delayed conversion windows and multi-touch credit assignment.", "required": true, "acceptable_evidence": ["Technical keywords: engagement telemetry, survival analysis, hazard models, data-driven Shapley values.", "Addresses the delayed feedback problem where conversions occur days or weeks after ad impression (survival analysis, hazard models).", "Implements multi-touch attribution (data-driven Shapley values or markov chains) rather than naive last-click attribution.", "Incorporates post-click on-site engagement telemetry (dwell time, page depth, scroll percentage) as proxy conversion signals."]}, {"id": "KP3", "description": "Real-Time Expected Value Bidding (eCPM): Calculates auction bids by multiplying bid value by predicted conversion probabilities.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, auction latency, eCPM, B geo-experiments.", "Formulates optimal bid price using expected value: `Bid = Value * pCTR * pCVR` under budget and ROI pacing constraints.", "Executes inference within strict real-time auction latency budgets (< 50ms per bid request).", "Applies incrementality testing and causal lift modeling (A/B geo-experiments) to verify advertising caused net new conversions."]}], "critical_failures": ["Conflates high click volume with conversion success, ignoring post-click drop-offs and low-quality traffic.", "Fails to explain how conversion probability (pCVR) is combined with bidding formulas to optimize advertiser ROI."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How does the slow and fast pointer technique help identify a duplicate in the array?', '{"key_points": [{"id": "KP1", "description": "Array as Linked List Graph Mapping: Explains how array values represent next pointers and duplicates create node convergences.", "required": true, "acceptable_evidence": ["Technical keywords: list graph, array index, array, linked.", "Explains that because values range from 1 to n with n+1 elements, every `nums[i]` is a valid array index, forming a functional graph.", "Articulates that a duplicate value means multiple distinct indices point to the same value, creating a cycle with an entrance.", "Recognizes that index 0 is always outside the cycle because array values range from 1 to n (guaranteeing 0 is never pointed to)."]}, {"id": "KP2", "description": "Two-Phase Floyd''s Cycle Detection Mechanics: Details intersection detection followed by finding the cycle entrance.", "required": true, "acceptable_evidence": ["Technical keywords: Intersection, `slow = nums[slow]`, `fast = nums[nums[fast]]`, Cycle Entrance.", "Phase 1 (Intersection): Moves slow by 1 step (`slow = nums[slow]`) and fast by 2 steps (`fast = nums[nums[fast]]`) until they meet inside the cycle.", "Phase 2 (Cycle Entrance): Resets one pointer to the start (`slow = nums[0]`) and advances both pointers 1 step at a time until they meet.", "Proves mathematically why the meeting point in Phase 2 corresponds exactly to the duplicate number (cycle entrance)."]}, {"id": "KP3", "description": "Complexity & Constraints Compliance: Proves O(N) time and O(1) space without array mutation.", "required": false, "acceptable_evidence": ["Technical keywords: binary search, time complexity, O(1), O(n).", "Proves strict O(N) time complexity and O(1) auxiliary space without modifying the input array.", "Contrasts with alternative approaches (sorting O(N log N) / modifies array, hash set O(N) space, binary search O(N log N) time).", "Handles edge cases correctly (minimum array size n=1, duplicates appearing more than twice)."]}], "critical_failures": ["Suggests using a hash set or sorting the array when the problem requires O(1) space and read-only array constraints.", "Cannot explain why the cycle entrance represents the duplicate number or fails to execute Phase 2."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'How does the stack-based approach help in constructing the smallest number from a given pattern?', '{"key_points": [{"id": "KP1", "description": "Greedy Digit Sequencing & LIFO Inversion: Pushes increasing digits to stack and reverses decreasing subsequences via popping.", "required": true, "acceptable_evidence": ["Technical keywords: LIFO, greedy, digit, sequencing.", "Iterates from 1 to N+1, pushing the current integer onto the stack at each step.", "Pops all elements from the stack into the result string whenever an ''I'' (increase) character is encountered or at the end of the pattern.", "Explains that a sequence of ''D''s accumulates numbers on the stack, and popping them reverses their order to produce the smallest valid decreasing sequence."]}, {"id": "KP2", "description": "Lexicographical Minimization Invariants: Justifies why assigning earlier digits smaller values produces the global minimum.", "required": true, "acceptable_evidence": ["Technical keywords: DID, II'' -> ''123, D'' -> ''21, DID'' -> ''2143.", "Explains greedy principle: digits in more significant place values must be as small as possible to minimize the resulting number.", "Shows that delayed popping allows the peak of a decreasing run to be assigned the largest available digit in that run while maintaining minimal prefixes.", "Demonstrates trace on examples (e.g., ''II'' -> ''123'', ''D'' -> ''21'', ''DID'' -> ''2143'')."]}, {"id": "KP3", "description": "Complexity & Boundary Handling: Validates linear O(N) runtime and string builder management.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, O(n), boundary, runtime.", "Proves linear O(N) time complexity as each digit from 1 to N+1 is pushed and popped exactly once.", "Maintains O(N) auxiliary space for the stack and output buffer.", "Handles terminal boundary condition: processing the final pending stack flush after iterating through the pattern length."]}], "critical_failures": ["Attempts exponential recursive backtracking (O(N!)) instead of the linear greedy stack approach.", "Fails to pop pending digits from the stack upon reaching the end of the input pattern."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'How does your system generate test strategies and support different types of testing such as unit, integration, and contract tests?', '{"key_points": [{"id": "KP1", "description": "Test Pyramid Stratification & Scope Boundaries: Defines distinct responsibilities, mocking strategies, and execution speeds for test tiers.", "required": true, "acceptable_evidence": ["Technical keywords: Redis, DB, redis cache, pytest-mock.", "Unit Testing: Tests isolated domain logic, utility algorithms, and edge cases using fast in-memory mocks/stubs (pytest-mock, Jest).", "Integration Testing: Validates cross-component interactions (service to DB, vector store, Redis cache) using disposable fixtures (Testcontainers, ephemeral Postgres)."]}, {"id": "KP2", "description": "Contract Testing: Validates API schemas and consumer-provider agreements (Pact, OpenAPI schema validators) without spinning up end-to-end services.", "required": true, "acceptable_evidence": ["Technical keywords: Pact contract testing, OpenAPI validator, consumer-driven contracts, CI test suite, service virtualization.", "Contract Testing: Validates API schemas and consumer-provider agreements (Pact, OpenAPI schema validators) without spinning up end-to-end services.", "Runs Pact contract tests in CI to verify that backend endpoints meet frontend consumer expectations before deployment without spinning up full microservice clusters."]}, {"id": "KP3", "description": "Automated Test Generation & Test Strategy Formulation: Employs property-based testing and AI-assisted test synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: AI, QuickCheck, LLM, mock payloads.", "Generates combinatorial test cases using property-based testing frameworks (Hypothesis, QuickCheck) to discover unhandled edge cases.", "Leverages LLM agents or static analysis to inspect code diffs and synthesize baseline unit test scaffolds and boundary assertions.", "Generates synthetic mock payloads adhering to OpenAPI or protobuf schema definitions."]}, {"id": "KP4", "description": "CI/CD Pipeline Integration & Quality Gates: Enforces coverage thresholds, flaky test remediation, and fast feedback loops.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, PR.", "Structures CI pipeline stages: fast unit tests run on commit (< 2 min), integration and contract tests run on PR merge gates.", "Enforces quality gates: minimum branch coverage, mutation testing benchmarks, and zero breaking contract changes.", "Implements quarantine mechanisms and automated retries to isolate flaky integration tests from blocking builds."]}], "critical_failures": ["Conflates unit and integration tests, running slow database-dependent tests as unit tests without isolation.", "Omits contract testing principles, requiring full end-to-end multi-service deployments just to verify API message contracts."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How familiar are you with building AI systems that integrate with multiple enterprise data sources?', '{"key_points": [{"id": "KP1", "description": "Heterogeneous Enterprise Connectors & Protocols: Ingests structured, semi-structured, and unstructured data across enterprise stores.", "required": true, "acceptable_evidence": ["Technical keywords: REST, GraphQL, PostgreSQL, Kafka.", "Integrates document repositories (SharePoint, Google Drive, Confluence, AWS S3) via REST APIs or enterprise connectors.", "Ingests structured enterprise data (PostgreSQL, Snowflake, Salesforce, Jira) via relational queries or GraphQL.", "Employs Change Data Capture (CDC via Debezium/Kafka) or webhook listeners to trigger incremental ingestion when records update."]}, {"id": "KP2", "description": "Schema Normalization & Metadata Tagging: Normalizes disparate formats into a unified document representation.", "required": true, "acceptable_evidence": ["Technical keywords: source_url, source_type, candidate_id, ticket_status.", "Transforms diverse source schemas into a unified document abstraction (content, source_url, author, timestamp, source_type).", "Applies domain-specific entity extraction and enrichment (e.g. tagging candidate_id, department, ticket_status).", "Preserves hierarchical document relationships (parent ticket -> comments; folder -> sub-documents)."]}, {"id": "KP3", "description": "Security Governance & ACL Permission Sync: Replicates enterprise access controls to prevent unauthorized vector retrieval.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, VPC, IAM, ACL.", "Synchronizes user and group permissions (Active Directory, Okta IAM) to attach access control lists (ACLs) to document chunks.", "Executes pre-filtering in vector databases (Milvus partition keys / metadata filters) matching the querying user''s authorization tokens.", "Complies with enterprise security boundaries: VPC endpoints, encryption at rest (KMS), and audit logging of cross-source queries."]}], "critical_failures": ["Ignores enterprise permission synchronization, allowing users to query and retrieve documents they do not have access to in the source system.", "Proposes manual full-database re-indexing for every update instead of incremental change capture or webhook pipelines."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'How have you incorporated guardrails or safety mechanisms into AI systems to ensure compliance and prevent data leakage?', '{"key_points": [{"id": "KP1", "description": "Architectural Guardrail Pipelines: Implements input and output guardrails decoupling policy enforcement from the model.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, jailbreak, output guardrails, NeMo.", "Integrates established guardrail frameworks (NeMo Guardrails, Llama Guard, Guardrails AI) into the request processing loop.", "Enforces pre-execution checks: prompt injection detection, topic moderation, jailbreak filtering, and PII anonymization.", "Enforces post-execution checks: response toxicity, hallucination verification against source context, and PII egress inspection."]}, {"id": "KP2", "description": "Deterministic Boundary Enforcement & Data Isolation: Protects sensitive enterprise data via code-level invariants.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, PII redaction, Microsoft Presidio, RBAC.", "Enforces role-based access control (RBAC) and tenant filtering at the database layer (Milvus partition keys, SQL tenant_id predicates).", "Implements deterministic allowlists for model tool calls and API executions, preventing unauthorized system operations.", "Applies automated PII redaction (Microsoft Presidio) prior to model inference and vector database indexing."]}, {"id": "KP3", "description": "Regulatory Compliance & Immutable Audit Logging: Maintains audit trails and monitors policy violation alerts.", "required": false, "acceptable_evidence": ["Technical keywords: Zero Data Retention, GDPR, HIPAA, Prometheus.", "Maintains tamper-proof audit logs recording sanitized prompts, model versions, guardrail trigger events, and timestamps.", "Integrates violation metrics with enterprise SIEM and observability dashboards (Prometheus, Grafana, Datadog).", "Ensures compliance with regulatory standards (SOC2, HIPAA, GDPR Zero Data Retention provider agreements)."]}], "critical_failures": ["Relies entirely on soft system prompt instructions without any programmatic guardrail software or deterministic code enforcement.", "Fails to address data isolation or allows cross-tenant context mixing in shared retrieval pipelines."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'How should a candidate prepare effectively for multiple rounds of technical interviews?', '{"key_points": [{"id": "KP1", "description": "Multi-Faceted Preparation Strategy: Balances algorithmic coding, system design, and specialized domain knowledge.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, rate limiting, two pointers, dynamic programming.", "Practices core data structures and algorithms (trees, graphs, two pointers, dynamic programming) with timed problem solving.", "Studies scalable system design patterns (microservices, caching, rate limiting, RAG, agent workflows, vector stores).", "Reviews fundamental domain concepts and study guides (LLM evaluation, guardrails, embeddings, feature stores)."]}, {"id": "KP2", "description": "Behavioral Structuring & STAR Story Bank: Prepares structured narratives highlighting technical impact and trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: STAR, QPS, Situation, Task.", "Prepares a bank of project stories structured via STAR (Situation, Task, Action, Result) covering leadership, conflict, and failure.", "Quantifies concrete engineering outcomes (e.g. latency reduced by 40%, throughput scaled to 10k QPS, accuracy improved by 15%).", "Articulates specific personal contributions and trade-offs made rather than claiming generic team accomplishments."]}, {"id": "KP3", "description": "Interactive Communication & Mock Simulation: Practicing verbal reasoning and collaborative problem-solving.", "required": false, "acceptable_evidence": ["Technical keywords: IDE, interactive, simulation, practicing.", "Conducts realistic mock interviews with peers to practice thinking aloud and managing whiteboard/IDE pacing.", "Researches target company products, architecture stack, and business challenges to formulate thoughtful reverse-interview questions.", "Practices active listening and clarifying questions to ensure alignment before proposing solutions."]}], "critical_failures": ["Crams leetcode trivia exclusively while ignoring system architecture, communication, and behavioral alignment.", "Unable to articulate personal technical contributions or metrics for past projects listed on the resume."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How was success measured, including any baseline or post-launch metrics?', '{"key_points": [{"id": "KP1", "description": "Pre-Launch Baseline Establishment: Benchmarks legacy workflows or previous models to establish quantifiable starting points.", "required": true, "acceptable_evidence": ["Technical keywords: p95, p95 latency, SLOs.", "Measures pre-existing operational baselines (e.g., human handling time of 15 min, legacy heuristic accuracy of 68%, p95 latency of 450ms).", "Curates a golden historical evaluation dataset to benchmark prospective models against historical human decisions.", "Defines clear Service Level Objectives (SLOs) and success criteria agreed upon with business stakeholders prior to build."]}, {"id": "KP2", "description": "Technical & Operational Post-Launch Metrics: Measures system performance, accuracy, and operational health in production.", "required": true, "acceptable_evidence": ["Technical keywords: MRR, F1-score, p99, launch metrics.", "Tracks technical accuracy and relevance metrics (Hit Rate@k, MRR, Faithfulness, F1-score, perplexity).", "Monitors operational latency and throughput (p50, p95, p99 latency, inference error rates, timeout rates).", "Monitors token consumption and infrastructure compute costs per successful user request."]}, {"id": "KP3", "description": "Business Impact & Causal Verification: Connects technical performance to commercial value through experimentation.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, ongoing telemetry, +35%.", "Quantifies concrete business outcomes: First Contact Resolution increase, ticket deflection rate (+35%), user retention lift, or saved manual hours.", "Runs randomized A/B tests or phased rollouts to isolate causal business impact from seasonal noise.", "Presents ongoing telemetry dashboards to executive stakeholders demonstrating sustained return on investment (ROI)."]}], "critical_failures": ["Claims success based purely on subjective impressions without establishing any baseline or measuring concrete metrics.", "Fails to connect technical model metrics (e.g. F1-score) to real-world business impact or user experience outcomes."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How will you do the traceability of any model?', '{"key_points": [{"id": "KP1", "description": "Training Lineage & Artifact Versioning: Links deployed models to exact training datasets, code commits, and hyperparameters.", "required": true, "acceptable_evidence": ["Technical keywords: Delta Lake, DVC, training metrics, Feast.", "Uses dataset versioning tools (DVC, Feast, Delta Lake time travel) to record snapshot hashes of training corpora.", "Tracks training runs in experiment registries (MLflow, Weights & Biases) linking model weights to git commit SHAs, dependencies, and seeds.", "Packages models in a centralized Model Registry with metadata: creator, architecture, training metrics, and approval status."]}, {"id": "KP2", "description": "Runtime Inference Tracing & Metadata Propagation: Propagates trace IDs and logs input-output lineage for every inference event.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, OpenTelemetry, trace_id, span_id.", "Injects unique trace_id and span_id across microservice boundaries using OpenTelemetry or LangSmith/Phoenix.", "Logs full inference metadata: model_name, model_version_hash, system_prompt_version, temperature, and retrieved context chunk IDs.", "Maintains correlation between upstream user requests, intermediate tool invocations, and final model generations."]}, {"id": "KP3", "description": "Audit Compliance, Debugging & Incident Triage: Enables deterministic reproduction and regulatory auditing of model decisions.", "required": false, "acceptable_evidence": ["Technical keywords: EU, AI, audit compliance, exact state.", "Allows engineers to reconstruct and replay the exact state and inputs that caused an anomalous production prediction.", "Supports regulatory compliance (EU AI Act, SOC2) by maintaining immutable records of model decisions and training provenance.", "Generates automated audit reports displaying model performance drift and retraining history over time."]}], "critical_failures": ["Deploys unversioned model files or treats production inference as a black box without logging model version or request trace IDs.", "Cannot trace a production failure or hallucination back to the specific training data snapshot or prompt version that produced it."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'How would dimensionality affect the quality of representations?', '{"key_points": [{"id": "KP1", "description": "Expressive Capacity vs Underfitting & Overfitting: Analyzes how dimensional capacity captures semantic nuances.", "required": true, "acceptable_evidence": ["Technical keywords: overfitting, underfitting, < 128 dims, > 1536 dims.", "Low dimensionality (e.g., < 128 dims): Risks information bottleneck, conflating distinct semantic meanings, and underfitting complex relationships.", "High dimensionality (e.g., > 1536 dims): Captures fine-grained semantic nuances and multi-faceted attributes, but requires substantially more training data to avoid sparsity and overfitting.", "Explains the intrinsic dimensionality of data manifolds versus ambient vector space dimensions."]}, {"id": "KP2", "description": "Curse of Dimensionality & Metric Geometry: Details distance concentration phenomenon in high-dimensional vector spaces.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, Euclidean distance, text embeddings, hubness problem.", "Explains distance concentration (hubness problem): in high dimensions, Euclidean distances between random pairs converge, reducing contrast between nearest and furthest neighbors.", "Justifies why Cosine Similarity or Normalized Inner Product is preferred over Euclidean distance in high-dimensional text embeddings.", "Discusses how empty space expands exponentially, causing data points to become isolated near the boundaries of the hypersphere."]}, {"id": "KP3", "description": "Operational Efficiency & Matryoshka Embeddings: Connects vector size to indexing cost, memory, and adaptive sizing.", "required": false, "acceptable_evidence": ["Technical keywords: HNSW, PQ, Product Quantization, quantization.", "Analyzes memory and compute overhead: higher dimensions increase vector database RAM requirements and ANN index construction time (HNSW).", "Discusses Matryoshka Representation Learning (MRL), allowing front-truncation of embeddings (e.g. 1536 to 256 dims) with minimal accuracy loss.", "Employs dimensionality reduction (PCA, UMAP, autoencoders) or Product Quantization (PQ) for efficient retrieval scaling."]}], "critical_failures": ["Claims higher dimensionality is always strictly better without recognizing the curse of dimensionality or distance concentration.", "Fails to acknowledge the real-world storage, memory, and indexing latency costs of large embedding vectors in vector search."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'How would the real-time dashboard receive real-time information?', '{"key_points": [{"id": "KP1", "description": "Transport Protocol Selection: Compares WebSockets, Server-Sent Events (SSE), and polling for dashboard telemetry.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, Server-Sent Events, jitter, WebSockets.", "Server-Sent Events (SSE): Ideal for unidirectional server-to-client telemetry streaming over standard HTTP/2 with automatic browser reconnects.", "WebSockets: Best for full-duplex, low-latency bidirectional communication where clients also transmit interactive commands.", "Rejects short polling due to high HTTP connection overhead, server load, and latency jitter."]}, {"id": "KP2", "description": "Backend Event Pub/Sub & Fan-Out: Distributes high-throughput metrics from producers to connected client gateway nodes.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, RabbitMQ, Redis, WebSocket.", "Uses a distributed message broker (Kafka, Redis Pub/Sub, RabbitMQ) to decouple telemetry producers from WebSocket/SSE servers.", "Scales WebSocket gateway servers horizontally using a Redis backplane to broadcast messages to clients across different server nodes.", "Applies metric throttling, buffering, or sliding-window aggregation on the backend to avoid overwhelming frontend rendering."]}, {"id": "KP3", "description": "Connection Resilience & Client State Synchronization: Handles reconnections, backpressure, and missing event reconciliation.", "required": false, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, ID, DOM.", "Implements exponential backoff reconnect logic with jitter on the client.", "Employs event sequence IDs or `Last-Event-ID` headers to replay missed messages upon reconnection.", "Manages frontend rendering performance via debouncing or requestAnimationFrame to prevent DOM thrashing."]}], "critical_failures": ["Proposes frequent short polling (e.g. hitting REST APIs every 100ms) for high-frequency real-time dashboard streaming.", "Fails to explain how WebSocket connections scale across multiple backend servers (missing Redis pub/sub or socket clustering)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'MEDIUM', 'BROAD', 150, 'If I want to invoke multiple instances of the graph, how do I do that to run 100 threads simultaneously?', '{"key_points": [{"id": "KP1", "description": "Async Graph Invocations & Concurrency Models: Details running concurrent graph instances via asyncio or distributed task workers.", "required": true, "acceptable_evidence": ["Technical keywords: asyncio, asyncio.gather, asyncio.Semaphore, LangGraph.", "Explains that LangGraph/agent workflows are I/O bound (waiting on LLM API calls, tool DBs) and should use asynchronous event loops (`ainvoke`, `asyncio.gather`, or `asyncio.Semaphore`) rather than heavy OS threads.", "Utilizes distributed task workers (Celery, Temporal, AWS SQS + ECS) to decouple graph triggering from web request threads.", "Applies worker concurrency tuning (e.g. asyncio event loops per worker process to achieve hundreds of concurrent graph tasks)."]}, {"id": "KP2", "description": "Isolated State Checkpointing & DB Connection Pooling: Prevents state collisions and handles database connection exhaustion.", "required": true, "acceptable_evidence": ["Technical keywords: checkpointing, PostgresSaver, PostgreSQL, thread_id.", "Assigns a distinct `thread_id` / `session_id` in the config for each execution instance to ensure complete state isolation in the checkpointer (e.g., PostgresSaver).", "Configures database connection pooling (PgBouncer, SQLAlchemy pool_size) so 100 concurrent threads do not exhaust PostgreSQL connection limits.", "Employs optimistic locking or partitioned checkpoint storage to prevent race conditions during state writes."]}, {"id": "KP3", "description": "Downstream Rate Limiting & Resource Protection: Throttles concurrent LLM API calls and tool service invocations.", "required": false, "acceptable_evidence": ["Technical keywords: event loop, exponential backoff, jitter, rate limiting.", "Implements token-bucket rate limiters or Redis semaphores to avoid exceeding upstream LLM Tier TPM/RPM limits across 100 parallel executions.", "Applies circuit breakers and exponential backoff with jitter on API rate limit errors (HTTP 429).", "Monitors aggregate memory, CPU, and event loop lag on worker nodes under peak concurrency."]}], "critical_failures": ["Spawns 100 raw OS Python threads sharing the same global thread_id or in-memory checkpointer, corrupting state.", "Fails to address LLM API rate limits or database connection pool exhaustion under 100 concurrent graph executions."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'If two variables show strong correlation, what methods would you use to test for causation?', '{"key_points": [{"id": "KP1", "description": "Randomized Controlled Trials (A/B Testing): Details the gold-standard experimental method for establishing causal attribution.", "required": true, "acceptable_evidence": ["Technical keywords: A/B testing, MDE, B Testing, t-test.", "Explains randomized assignment into treatment and control groups to eliminate confounding variables and selection bias.", "Calculates statistical power, minimum detectable effect (MDE), and sample size prior to running the experiment.", "Verifies balance checks across covariates and applies two-sample hypothesis testing (t-test, Mann-Whitney U) to measure causal treatment effect."]}, {"id": "KP2", "description": "Quasi-Experimental & Econometric Techniques: Evaluates causal relationships when randomized experimentation is unethical or impractical.", "required": true, "acceptable_evidence": ["Technical keywords: RDD, DiD, quasi, experimental.", "Difference-in-Differences (DiD): Compares trends between treated and untreated groups across pre- and post-intervention periods, verifying parallel trends.", "Instrumental Variables (IV): Uses an exogenous instrument that affects the treatment but has no direct effect on the outcome.", "Regression Discontinuity Design (RDD): Explores causal effects near arbitrary threshold cutoffs."]}, {"id": "KP3", "description": "Observational Causal Graphs & Matching: Identifies confounders and controls for selection bias.", "required": false, "acceptable_evidence": ["Technical keywords: PSM, IPW, causal graphs, acyclic graphs.", "Constructs Directed Acyclic Graphs (DAGs) and applies Pearl''s do-calculus to identify colliders, confounders, and mediators.", "Applies Propensity Score Matching (PSM) or Inverse Probability Weighting (IPW) to balance covariate distributions in observational data.", "Runs sensitivity analyses to test robustness against unobserved confounding."]}], "critical_failures": ["Claims that high correlation or time precedence alone is sufficient proof of causation.", "Fails to identify randomized controlled experiments or confounder control methodologies."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'If you switch from an Opus model to an 85 billion parameter model while keeping everything else constant, what do you expect the consequences of that choice to be?', '{"key_points": [{"id": "KP1", "description": "Reasoning Capability & Complex Task Quality: Evaluates impact on high-complexity reasoning, nuance, and instruction following.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, Opus, classification, standard RAG extraction.", "Recognizes potential regression in multi-step planning, obscure domain logic, complex code generation, and ambiguous intent disambiguation.", "Points out that closed frontier models (Opus) often exhibit superior calibration and fewer prompt formatting errors than smaller models.", "Notes that for well-defined, bounded domain tasks (e.g. classification, standard RAG extraction), an 85B model can achieve near-parity if properly prompted."]}, {"id": "KP2", "description": "Latency, Throughput & Unit Economics: Compares API token costs with self-hosted GPU hardware costs.", "required": true, "acceptable_evidence": ["Technical keywords: TTFT, quantization, INT8, FP16.", "Inference latency: 85B models typically offer faster Time-To-First-Token (TTFT) and higher token generation throughput than heavyweight frontier models.", "Hosting economics: An 85B model requires dedicated GPU infrastructure (e.g., 2-4x A100/H100 GPUs with FP16 or INT8 quantization), moving cost from per-token API to fixed compute capacity.", "Token pricing comparison: Frontier Opus API calls are priced premium per million tokens; self-hosting 85B becomes cheaper only at high sustained utilization."]}, {"id": "KP3", "description": "Privacy, Governance & Customization Autonomy: Identifies control benefits of self-hosted open-weights models.", "required": false, "acceptable_evidence": ["Technical keywords: vLLM, fine-tuning, LoRA, HIPAA.", "Zero external data egress: Deploying an 85B model on private VPC satisfies strict compliance requirements (HIPAA, defense).", "Fine-tuning & LoRA adaptability: Enables task-specific adaptation via LoRA or full-parameter tuning, which is impossible on proprietary Opus endpoints.", "Operational maintenance burden: Team assumes responsibility for GPU provisioning, vLLM/TGI serving, model quantization, and SLA uptime."]}], "critical_failures": ["Believes switching from Opus to 85B has zero quality impact or ignores reasoning regressions on complex workflows.", "Ignores GPU infrastructure requirements, assuming an 85B model runs without dedicated multi-GPU memory."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'HARD', 'BROAD', 210, 'In a high assurance environment, what criteria and evidence would you require before re-enabling the model/version you dynamically blocked after such an incident?', '{"key_points": [{"id": "KP1", "description": "Root-Cause Analysis & Deterministic Remediation: Identifies exact failure mechanisms and implements verifiable structural fixes.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, prompt injection, blameless post-mortem, distribution drift.", "Publishes a blameless post-mortem identifying the exact failure trigger (prompt injection vector, training data contamination, out-of-distribution drift).", "Implements deterministic code-level guardrails or input/output validator checks that mathematically or programmatically intercept the vulnerability.", "Proves that the fix does not rely merely on soft prompt tinkering or temperature adjustments."]}, {"id": "KP2", "description": "Adversarial Stress Testing & Golden Suite Validation: Runs extensive regression benchmarks against the patched system.", "required": true, "acceptable_evidence": ["Technical keywords: suite validation, incident payload, adversarial, stress.", "Executes targeted red-teaming and adversarial stress suites containing hundreds of permutations of the incident payload.", "Verifies 100% pass rate on the incident regression test and zero performance regression across the full golden benchmark suite.", "Replays historical production traffic through shadow or dark-launch mode to benchmark safety without impacting live users."]}, {"id": "KP3", "description": "Phased Re-enabling & Multi-Stakeholder Sign-Off: Implements staged canary rollout under heightened telemetry and governance review.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, canary deployment, CAB, heightened telemetry.", "Requires formal sign-off from the Change Advisory Board (CAB), Security Engineering, and Compliance leadership.", "Rolls out via canary deployment (1% -> 5% -> 25% -> 100%) with automated rollback triggers hooked to error and guardrail trip rates.", "Enforces heightened real-time observability and human-in-the-loop review sampling for the first 48 hours post-restoration."]}], "critical_failures": ["Re-enables the blocked model immediately after minor system prompt edits without automated regression verification or root-cause isolation.", "Fails to implement deterministic intercept safeguards, allowing the identical incident payload to pass through."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Under what conditions did you need to re-embed your corpus, and what signals triggered that decision?', '{"key_points": [{"id": "KP1", "description": "Trigger Signals & Performance Degradation: Identifies quantitative metrics and architectural triggers requiring re-embedding.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, MRR, BGE, MTEB.", "Embedding model upgrade: Adopting a superior foundation embedding model (e.g., migrating to BGE-large or text-embedding-3-large with higher MTEB benchmark scores).", "Retrieval metric decay: Observed drop in offline or online retrieval metrics (Hit Rate@k falling below 80%, MRR decline, increase in low cosine similarity scores)."]}, {"id": "KP2", "description": "Document parser/chunking migration: Transitioning from naive character chunking to layout-aware chunking (IBM Docling 512 tokens + 10-20% overlap) requiring regenerated vectors.", "required": true, "acceptable_evidence": ["Technical keywords: corpus re-embedding, IBM Docling, blue-green collection aliasing, Milvus collection swap, vector drift, 512-token chunks.", "Document parser/chunking migration: Transitioning from naive character chunking to layout-aware chunking (IBM Docling 512 tokens + 10-20% overlap) requiring regenerated vectors.", "Executes corpus re-indexing with zero downtime using blue-green collection swapping in Milvus (aliasing new collection once build completes)."]}, {"id": "KP3", "description": "Corpus Drift & Vocabulary Shift: Detects semantic drift between indexed documents and user query distributions.", "required": true, "acceptable_evidence": ["Technical keywords: corpus drift, distance metrics, corpus, drift.", "Monitors embedding drift using statistical distance metrics (Maximum Mean Discrepancy, cosine distance between query centroids and doc centroids).", "Emergence of new domain terminology, product lines, or acronyms poorly represented in the existing embedding space.", "Significant batch updates or schema restructurings across enterprise documentation sources."]}, {"id": "KP4", "description": "Zero-Downtime Re-Indexing Architecture: Executes re-embedding without interrupting live production search traffic.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, collection indexing, automated validation, Milvus collection aliases.", "Employs blue/green collection indexing in the vector database (e.g. Milvus collection aliases) to build the new index in parallel.", "Executes asynchronous batch embedding pipelines using GPU worker pools with rate-limit and checkpoint recovery.", "Switches collection aliases atomically to the new index only after running automated validation benchmarks on the candidate collection."]}], "critical_failures": ["Attempts in-place destructive mutation of the live vector database collection, causing downtime during re-indexing.", "Fails to identify embedding model upgrades or retrieval metric drops as valid triggers for re-embedding."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What SDLC practices did you follow, and how did you contribute to sprint planning and execution?', '{"key_points": [{"id": "KP1", "description": "Sprint Planning & Backlog Refinement: Decomposes product requirements into well-defined, estimable technical user stories.", "required": true, "acceptable_evidence": ["Technical keywords: story points, t-shirt sizing, sprint, planning.", "Deconstructs high-level epics into clear engineering tickets with explicit acceptance criteria and edge cases.", "Provides calibrated effort estimations (story points, t-shirt sizing) based on technical complexity and dependencies."]}, {"id": "KP2", "description": "Identify technical debt, architectural spikes, and non-functional requirements (security, logging) during planning.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, architectural spikes, non-functional requirements, Jira backlog grooming, capacity planning.", "Identifies technical debt, architectural spikes, and non-functional requirements (security, logging) during planning.", "Allocates explicit story points for technical spikes and non-functional requirements (logging, security hardening, automated test suites) during sprint planning sessions."]}, {"id": "KP3", "description": "Continuous Execution & Delivery Discipline: Maintains sprint velocity and engineering hygiene during the sprint cycle.", "required": true, "acceptable_evidence": ["Technical keywords: PR, CI, continuous, discipline.", "Uses daily standups to surface blockers, cross-team dependencies, and critical path risks early.", "Enforces rigorous PR review standards, automated CI unit/integration testing gates, and trunk-based or git-flow branching.", "Communicates scope adjustments transparently with product managers if unforeseen blockers threaten sprint commitments."]}, {"id": "KP4", "description": "Retrospectives & Continuous Process Improvement: Identifies systemic friction and implements actionable team improvements.", "required": false, "acceptable_evidence": ["Technical keywords: retrospectives, continuous, improvement, systemic.", "Participates constructively in sprint retrospectives, focusing on blameless process analysis rather than personal finger-pointing.", "Drives actionable retro improvements (e.g. automating flaky test alerts, refining ticket definition-of-ready).", "Shares domain learnings and documentation updates to improve developer onboarding and sprint velocity."]}], "critical_failures": ["Works in isolation without communicating blockers or updating ticket status until sprint deadlines are missed.", "Ignores code review, automated testing, or acceptance criteria in the rush to close sprint tickets."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What analyses would you perform on historical user data to identify changes in spending behavior among new users?', '{"key_points": [{"id": "KP1", "description": "Cohort Segmentation & Trajectory Analysis: Partitions users by acquisition period and compares behavioral evolution.", "required": true, "acceptable_evidence": ["Technical keywords: ARPU, LTV, repeat transaction.", "Builds cohort retention and spending heatmaps segmented by registration month/week across days 1, 7, 30, and 90.", "Compares cumulative Average Revenue Per User (ARPU) and LTV curves across successive new user cohorts.", "Analyzes changes in time-to-first-purchase and repeat transaction velocity."]}, {"id": "KP2", "description": "Statistical Distribution & Feature Drift Testing: Applies statistical tests to detect structural shifts in spending patterns.", "required": true, "acceptable_evidence": ["Technical keywords: Population Stability Index, PSI, AOV, feature drift.", "Applies non-parametric tests (Kolmogorov-Smirnov test, Mann-Whitney U) on basket size distributions to detect non-normal shifts.", "Calculates Population Stability Index (PSI) on spending features to identify significant distributional drift (> 0.2 threshold).", "Decomposes changes in mean spending into transaction frequency vs average order value (AOV)."]}, {"id": "KP3", "description": "Multi-Dimensional Attribution & Root-Cause Slicing: Slices data by acquisition channel, geography, and onboarding funnels.", "required": false, "acceptable_evidence": ["Technical keywords: paid ads, organic, referrals, seasonality.", "Segments cohorts by marketing channel (paid ads vs organic vs referrals) to identify low-quality acquisition source shifts.", "Examines onboarding funnel drop-offs and promotional voucher dependencies between old and new cohorts.", "Controls for macro confounding factors (seasonality, holiday spikes, macro-economic inflation) using Year-over-Year comparisons."]}], "critical_failures": ["Looks only at aggregate historical revenue averages without cohorting users by acquisition date, masking underlying behavioral shifts.", "Fails to use statistical distribution testing or confounding factor control when interpreting spending changes."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What are HNSW and PQ?', '{"key_points": [{"id": "KP1", "description": "HNSW (Hierarchical Navigable Small World): Explains multi-layer skip-list graph structure for high-recall ANN search.", "required": true, "acceptable_evidence": ["Technical keywords: HNSW, recall, O(log n), ANN.", "Explains that HNSW builds a multi-layer graph where upper layers have long-range sparse connections (like skip lists) and bottom layer contains all vectors.", "Greedy search begins at the top layer for coarse localization and descends to lower layers for fine-grained nearest neighbor discovery.", "Provides high recall (> 95-99%) and low search latency (logarithmic complexity O(log N)), but requires high RAM storage for graph edges."]}, {"id": "KP2", "description": "PQ (Product Quantization): Explains lossy vector compression via sub-space decomposition and k-means codebooks.", "required": true, "acceptable_evidence": ["Technical keywords: PQ, Product Quantization, quantization, byte index.", "Explains that PQ breaks high-dimensional vectors (e.g., 1536 dims) into m smaller sub-vectors (e.g., 8 or 16 dims each).", "Clusters each sub-space using k-means into 256 centroids (represented as an 8-bit byte index codebook).", "Drastically compresses vector memory footprint (often 4x to 16x reduction) and speeds up distance calculations using precomputed asymmetric distance tables."]}, {"id": "KP3", "description": "Architectural Trade-offs & Hybrid Indexing: Compares memory, speed, and accuracy, referencing production vector stores (Milvus/FAISS).", "required": false, "acceptable_evidence": ["Technical keywords: Architectural, implementation, architecture, production safeguards.", "Contrasts trade-offs: HNSW maximizes recall and search speed at the cost of high RAM; PQ minimizes RAM footprint with slight loss of precision/recall.", "Implements Architectural Trade-offs & Hybrid Indexing: Compares memory, speed, and accuracy, referencing production vector stores (Milvus/FAISS) with verified configurations and production runtime constraints."]}], "critical_failures": ["Cannot define what HNSW or PQ stands for or what their primary purposes are in vector search.", "Confuses quantization compression (PQ) with graph-based search traversal (HNSW)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'EASY', 'SPECIFIC', 60, 'What are intelligence boundaries in AI systems, and how do they help control model behavior?', '{"key_points": [{"id": "KP1", "description": "Definition of Intelligence Boundaries: Separates probabilistic model capabilities from deterministic code execution.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, definition, intelligence, probabilistic.", "Defines intelligence boundaries as explicit architectural firewalls delineating what the LLM is permitted to decide vs what code strictly enforces.", "Assigns fuzzy semantic reasoning, intent extraction, and language synthesis to the probabilistic model."]}, {"id": "KP2", "description": "Restricts data mutation, authorization checks, mathematical computations, and critical business rules to deterministic application code.", "required": true, "acceptable_evidence": ["Technical keywords: intelligence boundaries, deterministic validation, business rule isolation, RBAC guardrails, structured tool invocation.", "Restricts data mutation, authorization checks, mathematical computations, and critical business rules to deterministic application code.", "Enforces that the LLM only outputs structured tool invocation proposals while deterministic Python functions execute database mutations and verify business rules."]}, {"id": "KP3", "description": "Control & Safety Enforcement Mechanisms: Implements tool schemas, state transitions, and authorization gates.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, LangGraph, conditional edges, JSON schema.", "Constrains model actions via strict tool schemas (Pydantic models, JSON schema) rather than open-ended shell/database execution.", "Enforces state machine transitions deterministically (e.g., LangGraph conditional edges) where invalid state transitions are blocked by code.", "Enforces user permissions and identity propagation at the API gateway/runtime layer, preventing the model from bypassing RBAC."]}, {"id": "KP4", "description": "Failure Containment & Blast-Radius Mitigation: Limits harm when the probabilistic model hallucinates or errs.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, maximum refund amounts, rate limits.", "Caps tool execution frequency and parameters (e.g. maximum refund amounts, rate limits).", "Routes low-confidence or high-risk actions to human-in-the-loop (HITL) approval gates.", "Preserves predictable system reliability by isolating agent hallucinations within the prompt layer."]}], "critical_failures": ["Believes system prompts alone represent an intelligence boundary without code-level enforcement.", "Allows the LLM to directly execute destructive system actions without deterministic authorization or schema validation."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What are the expectations from candidates in terms of demonstrating skills during interviews?', '{"key_points": [{"id": "KP1", "description": "Technical Problem Solving & Architectural Rigor: Demonstrates clean coding hygiene, edge-case analysis, and scalable design.", "required": true, "acceptable_evidence": ["Technical keywords: Technical, implementation, architecture, production safeguards.", "Writes clean, readable, modular code with proper variable naming, helper abstractions, and error handling.", "Implements Technical Problem Solving & Architectural Rigor: Demonstrates clean coding hygiene, edge-case analysis, and scalable design with verified configurations and production runtime constraints."]}, {"id": "KP2", "description": "Collaborative Communication & Thinking Aloud: Verbalizes design decisions and engages the interviewer constructively.", "required": true, "acceptable_evidence": ["Technical keywords: collaborative, thinking, aloud, verbalizes.", "Explains the thought process aloud, clarifying requirements and stating assumptions before writing code.", "Collaborates with the interviewer as a peer, receptive to hints, questions, and alternative perspectives.", "Explains ''why'' an approach is chosen over viable alternatives rather than coding silently."]}, {"id": "KP3", "description": "Ownership, Authenticity & Practical Experience: Backs claims with genuine engineering stories and business context.", "required": false, "acceptable_evidence": ["Technical keywords: authenticity, practical, experience, backs.", "Demonstrates genuine hands-on experience by discussing actual production incidents, bottlenecks, and lessons learned.", "Connects technical decisions to business value, developer velocity, and user experience outcomes.", "Shows intellectual honesty by admitting knowledge boundaries and reasoning through unfamiliar problems."]}], "critical_failures": ["Rushes into coding without clarifying requirements or communicating thoughts aloud with the interviewer.", "Exhibits defensiveness or refuses to collaborate when provided with feedback or alternative technical suggestions."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What are the key challenges in moving a proof-of-concept (POC) AI system into production, and how did you address them?', '{"key_points": [{"id": "KP1", "description": "Non-Determinism Mitigation & Automated Evaluation: Transitions from manual eyeballing to automated golden test suites.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval, PR, Ragas.", "Replaces subjective manual prompt inspection with automated evaluation pipelines (DeepEval, Ragas) running on PR merge gates.", "Curates representative golden evaluation datasets capturing edge cases, adversarial queries, and domain corner cases."]}, {"id": "KP2", "description": "Measures objective metrics (Faithfulness, Answer Relevance, Hallucination Rate, Hit Rate@k) to prevent silent regressions.", "required": true, "acceptable_evidence": ["Technical keywords: Ragas, DeepEval, Faithfulness, Answer Relevance, Hit Rate@k, automated CI quality gates, regression testing.", "Measures objective metrics (Faithfulness, Answer Relevance, Hallucination Rate, Hit Rate@k) to prevent silent regressions.", "Sets automated regression test gates in CI using Ragas/DeepEval, failing builds if faithfulness drops below 0.85 on the golden test suite."]}, {"id": "KP3", "description": "Latency Optimization & Unit Cost Management: Scales system within strict p95 latency and token budget bounds.", "required": true, "acceptable_evidence": ["Technical keywords: SSE, prompt caching, exponential backoff, WebSockets.", "Solves latency bottlenecks using streaming responses (SSE/WebSockets), prompt caching, and asynchronous concurrent tool invocations.", "Implements semantic caching (Redis/GPTCache) and routes simple tasks to smaller SLMs (e.g., Llama-3-8B / Claude Haiku) to cut token costs.", "Configures circuit breakers, retries with exponential backoff, and fallback models when primary API providers degrade."]}, {"id": "KP4", "description": "Production Observability & Enterprise Security: Enforces guardrails, distributed tracing, and compliance controls.", "required": false, "acceptable_evidence": ["Technical keywords: output guardrails, OpenTelemetry, distributed tracing, LangSmith.", "Instruments end-to-end distributed tracing (OpenTelemetry, LangSmith, Phoenix) tracking prompt versions, token counts, and tool latencies.", "Deploys input and output guardrails (NeMo Guardrails, Presidio PII masking) to enforce safety and prevent sensitive data egress.", "Executes phased production rollout (shadow mode -> canary deploy -> 100% traffic) to validate system stability under real load."]}], "critical_failures": ["Assumes a prototype that works on 5 cherry-picked demo examples is production-ready without automated evaluation.", "Fails to address inference latency, token costs, rate limits, or production observability."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'BROAD', 90, 'What are the key components required to build an AI system for document understanding and risk scoring?', '{"key_points": [{"id": "KP1", "description": "Document Ingestion & Multi-Format Parsing: Ingests heterogeneous documents and extracts structured text and tables.", "required": true, "acceptable_evidence": ["Technical keywords: submission_date, entity_name, document_type, policy_id.", "Uses layout-aware parsing and OCR engines (Docling, Textract, Unstructured) to handle PDFs, scanned forms, and tables.", "Extracts key document metadata (submission_date, entity_name, document_type, policy_id).", "Linearizes tables into markdown/HTML to preserve row and column associations for downstream analysis."]}, {"id": "KP2", "description": "Rule-Guided Retrieval & Structured Risk Scoring: Combines vector search with structured extraction and scoring rubrics.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, dense embeddings, BM25, hybrid search.", "Retrieves relevant compliance policies or underwriting rules using hybrid search (dense embeddings + BM25 keyword search).", "Prompts LLMs using structured outputs (Pydantic / Instructor) to emit categorical risk flags, numeric scores, and citations.", "Enforces deterministic mathematical calculations for final composite score aggregation rather than relying on LLM arithmetic."]}, {"id": "KP3", "description": "Explainability, Audit Trails & Human Review Escalation: Generates verifiable citations and routes high-risk cases to experts.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, page number, excerpt.", "Links every risk finding directly to specific source document chunk citations (page number, excerpt) for audit transparency.", "Implements confidence thresholds that automatically trigger human-in-the-loop (HITL) review for borderline or high-risk scores.", "Logs immutable audit records of all extractions, scores, and human modifications for regulatory compliance."]}], "critical_failures": ["Relying entirely on an ungrounded LLM to hallucinate a risk score without source document citations or verifiable evidence.", "Fails to specify how tables or unstructured documents are parsed prior to risk analysis."]}', 1),
('TECHNICAL', 'AI Engineering', 'Generative AI & LLMs', 'EASY', 'BROAD', 90, 'What are the key differences and challenges between building text-based AI assistants versus voice-based systems?', '{"key_points": [{"id": "KP1", "description": "Ultra-Low Latency & Streaming Pipeline Architecture: Compares cascaded pipelines with strict real-time conversational budgets.", "required": true, "acceptable_evidence": ["Technical keywords: ASR, LLM, TTS, GPT.", "Explains conversational latency budgets: voice systems require sub-500ms end-to-end response time to feel natural, whereas text interfaces tolerate 2-5s.", "Compares cascaded architectures (Streaming ASR -> Streaming LLM -> Streaming TTS) with native multimodal audio-to-audio models (e.g. GPT-4o voice).", "Streams tokens directly from LLM output into TTS synthesis chunks (sentence/clause chunking) before full generation finishes."]}, {"id": "KP2", "description": "Voice Activity Detection (VAD) & Barge-In Interruption: Manages turn-taking and user interruptions gracefully.", "required": true, "acceptable_evidence": ["Technical keywords: VAD, TTS, Silero VAD, WebRTC VAD.", "Implements Voice Activity Detection (Silero VAD, WebRTC VAD) to detect when the user begins and stops speaking.", "Handles barge-in (interruption handling): cancels in-flight LLM generation and cuts TTS audio playback immediately upon detecting user speech.", "Manages turn-taking ambiguity (pausing to think vs finishing speaking) using semantic end-of-turn classifiers."]}, {"id": "KP3", "description": "Acoustic Noise, Formatting & Tone Adaptation: Adapts conversational output for auditory listening.", "required": false, "acceptable_evidence": ["Technical keywords: REST, WebSockets, HTTP, ASR.", "Removes markdown, asterisks, bullet points, and code formatting from voice output prompts, optimizing for spoken prose.", "Addresses background acoustic noise, accents, and homophones in the ASR speech recognition layer.", "Optimizes network transport using full-duplex WebSockets or WebRTC over standard REST HTTP."]}], "critical_failures": ["Assumes a voice assistant can wait for the entire text response to finish generating before starting audio playback, creating unacceptable latency.", "Ignores interruption handling (barge-in), forcing the user to wait until the AI finishes speaking before responding."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'EASY', 'SPECIFIC', 60, 'What are the limitations of using simple imputation methods like mean, median, or mode, and how can you mitigate potential biases?', '{"key_points": [{"id": "KP1", "description": "Variance Reduction & Correlation Distortion: Explains how univariate imputation distorts underlying distributions.", "required": true, "acceptable_evidence": ["Technical keywords: mean, median, variance, reduction.", "Articulates that imputing a single constant (mean/median) artificially shrinks variance and standard deviation of the feature.", "Distorts covariance and Pearson correlation between the imputed feature and other variables, masking relationships."]}, {"id": "KP2", "description": "Alters distribution shapes (e.g., creating artificial spikes at the mean in histograms) and underestimates standard errors in hypothesis tests.", "required": true, "acceptable_evidence": ["Technical keywords: mean imputation bias, variance reduction, MICE, KNN imputer, missing indicator column, standard error underestimation.", "Alters distribution shapes (e.g., creating artificial spikes at the mean in histograms) and underestimates standard errors in hypothesis tests.", "Adopts advanced imputation techniques such as KNN imputation, MICE (Multivariate Imputation by Chained Equations), or indicator columns for missingness."]}, {"id": "KP3", "description": "Missingness Mechanisms & Bias Amplification: Evaluates MCAR vs MAR vs MNAR assumptions.", "required": true, "acceptable_evidence": ["Technical keywords: MCAR, MAR, MNAR.", "Explains that simple imputation is valid only under Missing Completely At Random (MCAR) assumptions, which rarely holds in real datasets.", "When data is Missing At Random (MAR) or Missing Not At Random (MNAR), mean imputation introduces severe selection bias.", "Can systematically disadvantage minority sub-populations or skew model fairness when missingness correlates with protected attributes."]}, {"id": "KP4", "description": "Advanced Mitigation & Model-Based Imputation: Proposes multivariate techniques to preserve relationships.", "required": false, "acceptable_evidence": ["Technical keywords: is_missing, MICE, IterativeImputer, KNN.", "Applies Multivariate Imputation by Chained Equations (MICE / IterativeImputer) to preserve inter-feature dependencies.", "Uses KNN Imputer or tree-based regression models (MissForest) to estimate missing values conditioned on correlated features.", "Adds binary missingness indicator flags (`is_missing`) to allow algorithms to learn patterns in the missingness itself."]}], "critical_failures": ["Claims mean imputation is always safe and introduces zero bias into machine learning models.", "Fails to identify multivariate imputation alternatives (e.g. MICE, KNN) or missingness indicator flags."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What are the metrics you have used for AB testing?', '{"key_points": [{"id": "KP1", "description": "Primary & Business Decision Metrics: Measures direct behavioral change aligned with experimental hypotheses.", "required": true, "acceptable_evidence": ["Technical keywords: CVR, CTR, AOV, FCR.", "Defines primary conversion metrics: Conversion Rate (CVR), Click-Through Rate (CTR), Average Order Value (AOV).", "Evaluates user task completion rate, session deflection rate, or First Contact Resolution (FCR) in AI systems.", "Applies statistical hypothesis tests (two-proportion z-test, t-test) and computes p-values and confidence intervals."]}, {"id": "KP2", "description": "System Guardrail & Performance Metrics: Monitors operational health to prevent degraded user experience.", "required": true, "acceptable_evidence": ["Technical keywords: p95, p99, HTTP, p99 request duration.", "Tracks latency metrics (p95, p99 request duration) to ensure feature improvements don''t introduce performance regression.", "Monitors system error rates (HTTP 5xx, timeout percentage, crash-free user sessions).", "Monitors downstream business churn, unsubscribe rates, and infrastructure cost per active session."]}, {"id": "KP3", "description": "Data Quality & Experiment Validity Checks: Validates traffic integrity before analyzing results.", "required": false, "acceptable_evidence": ["Technical keywords: SRM, secondary metrics, Bonferroni, Benjamini-Hochberg.", "Checks for Sample Ratio Mismatch (SRM) using chi-square tests to verify traffic was split evenly (e.g. 50/50).", "Monitors novelty effects by observing metric stability over multiple weeks across new vs returning users.", "Applies multiple testing corrections (Bonferroni, Benjamini-Hochberg) when evaluating multiple secondary metrics."]}], "critical_failures": ["Lists only a single generic metric (e.g. clicks) without mentioning guardrail metrics (latency, errors) or statistical significance.", "Fails to check for experiment validity or Sample Ratio Mismatch (SRM)."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What are your core technical strengths, and which areas do you prefer to focus on when building systems?', '{"key_points": [{"id": "KP1", "description": "Core Technical Competencies & Specialization: Clearly articulates domain expertise and architectural comfort zones.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, Milvus, FastAPI, Docker.", "Highlights specific technical domains (e.g., production RAG/Agentic AI systems, distributed microservices, low-latency API design, data pipelines).", "Demonstrates mastery of specific technical stacks (Python, FastAPI, Docker, Milvus, Postgres, AWS/Kubernetes)."]}, {"id": "KP2", "description": "Explain the underlying engineering principles behind their preferred stack (high availability, modular decoupling, testability).", "required": true, "acceptable_evidence": ["Technical keywords: high availability, modular decoupling, test-driven development, asynchronous event loops, clean architecture.", "Explains the underlying engineering principles behind their preferred stack (high availability, modular decoupling, testability).", "Applies core engineering principles: decoupling services via asynchronous queues, enforcing strict typing with Pydantic, and writing comprehensive unit test suites."]}, {"id": "KP3", "description": "Engineering Philosophy & Focus Areas: Describes preferences for solving complex architectural and scaling challenges.", "required": true, "acceptable_evidence": ["Technical keywords: technical debt, engineering, philosophy, focus.", "Articulates a clear philosophy (e.g. bias for production reliability, end-to-end observability, pragmatic technical debt management).", "Prefers building foundational, reusable platform components that unblock product feature velocity.", "Emphasizes rigorous evaluation and testing over hype-driven prototyping."]}, {"id": "KP4", "description": "Continuous Growth & Adaptability: Demonstrates curiosity to expand skills into complementary technical areas.", "required": false, "acceptable_evidence": ["Technical keywords: advanced agent orchestration, continuous, growth, adaptability.", "Identifies technical areas they are actively expanding into (e.g. advanced agent orchestration, GPU kernel optimization).", "Shows enthusiasm for cross-functional collaboration with data scientists, frontend engineers, and product managers.", "Provides concrete examples where their core strengths solved a critical technical bottleneck in a past project."]}], "critical_failures": ["Provides vague, non-committal answers (''I can do everything'') without demonstrating genuine depth in any technical area.", "Cannot articulate an engineering philosophy or justify why they prefer particular architectural focus areas."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What are your expectations regarding the hiring process and next steps after recruiter screening?', '{"key_points": [{"id": "KP1", "description": "Understanding of Interview Stages & Technical Depth: Demonstrates familiarity with multi-stage engineering evaluations.", "required": true, "acceptable_evidence": ["Technical keywords: AI, live coding, take-home project, architecture discussion.", "Anticipates upcoming rounds: technical coding/algorithms, system architecture & design, domain-specific AI deep-dives, and leadership/cultural rounds.", "Expresses readiness to present past architectural implementations, code hygiene, and design trade-offs.", "Inquires about specific interview formats (e.g. live coding vs take-home project vs architecture discussion)."]}, {"id": "KP2", "description": "Mutual Evaluation & Team Alignment: Treats the process as a two-way street to assess team culture and technical fit.", "required": true, "acceptable_evidence": ["Technical keywords: team alignment, mutual, treats, street.", "Views the hiring process as an opportunity to understand team technical practices, engineering challenges, and product roadmaps.", "Seeks opportunities to meet prospective peers and engineering managers to evaluate psychological safety and team culture.", "Asks constructive questions regarding engineering velocity, tooling autonomy, and mentorship."]}, {"id": "KP3", "description": "Transparent Communication & Timeline Alignment: Sets realistic expectations regarding availability and decision pacing.", "required": false, "acceptable_evidence": ["Technical keywords: timeline alignment, transparent, timeline, realistic.", "Values prompt, transparent recruiter communication regarding timeline expectations and next steps.", "Communicates personal schedule constraints and potential competing interview deadlines respectfully.", "Maintains professionalism and enthusiasm for the company mission throughout the evaluation cycle."]}], "critical_failures": ["Shows zero interest in team culture, technical challenges, or the structure of the engineering evaluation.", "Demands immediate offers or bypasses standard technical evaluation stages arrogantly."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What are your key strengths in building AI systems, and what areas have you identified for improvement?', '{"key_points": [{"id": "KP1", "description": "Concrete AI Engineering Strengths: Articulates deep practical competencies with evidence from real systems.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, RAG, CI/CD, AI.", "Highlights specific technical strengths (e.g. building production RAG pipelines, LangGraph state orchestration, guardrails enforcement, or low-latency vector search).", "Demonstrates software engineering hygiene: unit testing, clean API contracts, and CI/CD pipelines alongside AI components."]}, {"id": "KP2", "description": "Connects technical strengths to delivered business outcomes (e.g. reducing hallucinations by 40%, cutting p95 latency in half).", "required": true, "acceptable_evidence": ["Technical keywords: business impact metrics, hallucination reduction, P95 latency optimization, token cost reduction, production reliability.", "Connects technical strengths to delivered business outcomes (e.g. reducing hallucinations by 40%, cutting p95 latency in half).", "Demonstrates delivered business impact: reducing hallucinations by 40% via hybrid retrieval, cutting P95 latency in half with prompt caching, and maintaining 99.9% uptime."]}, {"id": "KP3", "description": "Genuine Growth Areas & Self-Awareness: Identifies authentic technical growth opportunities without faux weaknesses.", "required": true, "acceptable_evidence": ["Technical keywords: genuine, growth, areas, AI.", "Identifies a genuine, relevant technical growth area (e.g., distributed multi-GPU training kernels, low-level Triton optimizations, advanced causal inference).", "Avoids cliché non-weaknesses (e.g., ''I work too hard'' or ''I am too perfectionist'').", "Shows intellectual honesty and humility regarding the vast, rapidly evolving nature of modern AI."]}, {"id": "KP4", "description": "Active Growth Strategy: Details ongoing, actionable steps to upskill in identified growth areas.", "required": false, "acceptable_evidence": ["Technical keywords: active, strategy, ongoing, growth.", "Details concrete learning actions taken (e.g. studying research papers, building hands-on open-source spikes, taking specialized coursework).", "Demonstrates rapid learning agility and willingness to pair with senior domain experts.", "Articulates how strengthening this area will make them a more well-rounded engineering leader."]}], "critical_failures": ["Claims to have zero weaknesses or areas for improvement, demonstrating a total lack of self-awareness.", "Provides superficial clichés without identifying any genuine technical growth opportunity or remediation plan."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What are your long-term goals as a solution architect, and how do you plan to achieve them?', '{"key_points": [{"id": "KP1", "description": "Enterprise Architectural Vision & Technical Leadership: Aims to shape scalable, multi-year platform strategies.", "required": true, "acceptable_evidence": ["Technical keywords: AI, event-driven streaming, architectural, vision.", "Aspires to design resilient, loosely coupled enterprise architectures that support long-term product scaling and high availability.", "Balances cutting-edge technological adoption (AI, event-driven streaming) with pragmatic risk and cost management."]}, {"id": "KP2", "description": "Seeks to influence organizational architectural standards, ADR processes, and technology radar roadmaps.", "required": true, "acceptable_evidence": ["Technical keywords: Architecture Decision Records (ADRs), Technology Radar, enterprise patterns, governance frameworks, system design.", "Seeks to influence organizational architectural standards, ADR processes, and technology radar roadmaps.", "Authors Architecture Decision Records (ADRs) to document technology trade-offs systematically and establishes organization-wide standards for AI infrastructure."]}, {"id": "KP3", "description": "Business Strategy & Stakeholder Bridging: Translates high-level business goals into robust technical architectures.", "required": true, "acceptable_evidence": ["Technical keywords: TCO, aligns architecture, strategy, stakeholder.", "Deepens ability to communicate technical trade-offs effectively with C-suite executives, product leaders, and enterprise clients.", "Aligns architecture directly with business value (reducing TCO, increasing market agility, complying with regulatory constraints).", "Facilitates consensus across distributed engineering teams facing conflicting technical priorities."]}, {"id": "KP4", "description": "Continuous Technical Grounding & Mentorship: Maintains hands-on engineering chops while uplifting team talent.", "required": false, "acceptable_evidence": ["Technical keywords: continuous, mentorship, hands, engineering.", "Avoids becoming an ''ivory tower'' architect by regularly writing code spikes, reviewing PRs, and engaging in production post-mortems.", "Invests in mentoring junior and mid-level engineers, fostering a culture of rigorous system design and continuous learning.", "Plans to achieve goals through technical certifications, contributing to open-source architectures, and speaking at industry conferences."]}], "critical_failures": ["Desires to abandon technical depth entirely to become an ''ivory tower'' architect detached from practical implementation reality.", "Shows no interest in business alignment, team mentorship, or cross-functional stakeholder communication."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What broke or underperformed in production once you released it?', '{"key_points": [{"id": "KP1", "description": "Incident Triage & Immediate Stabilization: Describes a realistic production failure and rapid containment actions.", "required": true, "acceptable_evidence": ["Technical keywords: read replicas, LLM, API.", "Details a real production failure mode (e.g., connection pool exhaustion, memory leak under high concurrency, LLM API rate-limit storm, latency spike).", "Explains immediate mitigation actions taken (e.g. rolling back to last stable build, enabling circuit breakers, scaling read replicas).", "Maintains transparent stakeholder communication during the active outage."]}, {"id": "KP2", "description": "Root-Cause Analysis (5 Whys): Investigates the underlying technical and systemic causes without finger-pointing.", "required": true, "acceptable_evidence": ["Technical keywords: blameless post-mortem, APM, 5 Whys, logs.", "Conducts a blameless post-mortem using telemetry (logs, APM traces, metrics) to isolate the true root cause.", "Applies the ''5 Whys'' framework to discover systemic gaps (e.g., missing load testing, lack of timeouts, inadequate backpressure).", "Accepts personal and team ownership rather than blaming external vendors or junior colleagues."]}, {"id": "KP3", "description": "Preventative Remediation & Long-Term Safeguards: Implements automated safeguards to guarantee the issue never recurs.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, Datadog, CI/CD, CI.", "Adds automated regression tests and synthetic load tests to CI/CD pipelines to catch similar defects prior to deployment.", "Instruments proactive alerting thresholds and health checks (Prometheus/Datadog) for early warning detection.", "Updates operational runbooks and shares learnings with the broader engineering organization."]}], "critical_failures": ["Claims that nothing has ever broken or failed in any production system they have built.", "Blames other people or third-party tools defensively without analyzing root cause or implementing preventative engineering fixes."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What business metrics did you use to measure the success of your AI system, and how did they align with technical metrics?', '{"key_points": [{"id": "KP1", "description": "Commercial & Operational Business Metrics: Measures tangible economic and customer experience outcomes.", "required": true, "acceptable_evidence": ["Technical keywords: FCR, CSAT, tangible, economic.", "Defines high-level business KPIs: First Contact Resolution (FCR), customer support ticket deflection rate, customer satisfaction (CSAT).", "Measures operational efficiency gains: human agent handling time reduced by 40%, time-to-resolution cut from hours to seconds."]}, {"id": "KP2", "description": "Calculates bottom-line ROI: cost savings from automated tier-1 resolutions vs total monthly LLM API and compute expenses.", "required": true, "acceptable_evidence": ["Technical keywords: AI ROI calculation, tier-1 resolution cost, LLM token expenditure, customer deflection rate, operational unit economics.", "Calculates bottom-line ROI: cost savings from automated tier-1 resolutions vs total monthly LLM API and compute expenses.", "Compares customer service labor savings from automated tier-1 resolutions against cloud compute and LLM API costs to calculate net monthly ROI."]}, {"id": "KP3", "description": "Technical-to-Business Metric Correlation: Explicitly maps offline engineering benchmarks to online business results.", "required": true, "acceptable_evidence": ["Technical keywords: NDCG, p95, higher retrieval, p95 latency.", "Demonstrates how retrieval Hit Rate@k and NDCG correlate with ticket deflection (higher retrieval quality directly reduces user frustration).", "Shows how LLM Faithfulness/hallucination minimization protects brand trust and minimizes customer escalation rates.", "Tracks how p95 latency reductions (< 1.5s via streaming) drive higher user engagement and completion rates."]}, {"id": "KP4", "description": "Telemetry Observability & Stakeholder Dashboards: Communicates metric health transparently across business and engineering.", "required": false, "acceptable_evidence": ["Technical keywords: Grafana, AI, Looker.", "Builds shared real-time dashboards (Grafana, Looker) presenting both technical latency/error rates and business conversion funnels.", "Runs A/B experiments to prove causal attribution of the AI system on business revenue lift.", "Establishes alerting thresholds on business metric drops to catch silent model drift or retrieval degradation."]}], "critical_failures": ["Focuses exclusively on technical metrics (e.g. loss or accuracy) without explaining any connection to business goals or user value.", "Cannot quantify or explain how engineering improvements translate into operational or financial ROI."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What business problem were you solving with your AI solution, and how did it improve metrics such as first contact resolution or response quality?', '{"key_points": [{"id": "KP1", "description": "Problem Decomposition & Baseline Bottlenecks: Outlines the operational friction and legacy workflow inefficiencies.", "required": true, "acceptable_evidence": ["Technical keywords: PDF, FCR, AHT, FCR at 52%.", "Articulates a clear business bottleneck (e.g., customer service agents spending 8+ minutes searching dozens of disconnected PDF manuals).", "Quantifies the baseline pain: low First Contact Resolution (FCR at 52%), high average handle time (AHT), and inconsistent agent answers."]}, {"id": "KP2", "description": "Identify customer dissatisfaction and high support staff onboarding turnover as core drivers.", "required": true, "acceptable_evidence": ["Technical keywords: First Contact Resolution (FCR), customer churn reduction, support ticket deflections, agent onboarding acceleration.", "Identifies customer dissatisfaction and high support staff onboarding turnover as core drivers.", "Analyzes support center bottlenecks: identifies repetitive FAQ queries, high agent turnover, and slow escalation paths as primary drivers for AI automation."]}, {"id": "KP3", "description": "AI Intervention & Technical Implementation: Deploys grounded retrieval and agentic workflows to resolve inquiries.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, hybrid search, Milvus, output guardrails.", "Architected a domain-grounded RAG or agentic assistant (Docling layout parsing, Milvus hybrid search, BGE reranking) to surface precise answers instantly.", "Provided agents with verified source citations, reducing answer lookup time to under 1.5 seconds.", "Enforced output guardrails and confidence scoring to ensure answers were factually compliant and hallucinatory responses were suppressed."]}, {"id": "KP4", "description": "Measurable Business Outcomes & Long-Term Value: Delivers concrete improvements in key performance indicators.", "required": false, "acceptable_evidence": ["Technical keywords: AHT, CSAT, FCR.", "Demonstrates measurable FCR increase (e.g., FCR improved from 52% to 78% within 90 days).", "Quantifies Average Handle Time (AHT) reduction (e.g., cut by 4 minutes per interaction) and CSAT score gains.", "Highlights improved response quality consistency and accelerated new agent ramp-up time from 6 weeks to 10 days."]}], "critical_failures": ["Describes an AI solution without identifying what business problem was actually being solved or who the users were.", "Provides zero concrete metrics, before-and-after baselines, or measurable outcomes on FCR or response quality."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What challenges arise when building models that must operate without cookies or across environments like mobile and connected TV?', '{"key_points": [{"id": "KP1", "description": "Identity Fragmentation & Signal Sparsity: Details identity loss across browsers, iOS ATT, and Connected TV (CTV).", "required": true, "acceptable_evidence": ["Technical keywords: ATT, TV, CTV, IDFA.", "Explains the loss of third-party cookies and mobile advertising IDs (Apple IDFA opt-ins dropping to ~20% under ATT).", "CTV environment constraints: shared household IP addresses, lack of click interactions (view-through only), and fragmented OEM device IDs."]}, {"id": "KP2", "description": "Extreme signal sparsity where traditional deterministic user history is completely unavailable.", "required": true, "acceptable_evidence": ["Technical keywords: cookieless attribution, contextual bandit, probabilistic identity graph, IP/User-Agent clustering, signal sparsity.", "Extreme signal sparsity where traditional deterministic user history is completely unavailable.", "Employs contextual feature engineering and probabilistic identity graphs to model engagement when deterministic user identifiers and cookies are absent."]}, {"id": "KP3", "description": "Probabilistic Identity Graphs & Cross-Device Graph Modeling: Combines machine learning graphs to link disparate devices.", "required": true, "acceptable_evidence": ["Technical keywords: identity graphs, device graph, learning graphs, household cluster.", "Builds probabilistic identity graphs using graph neural networks (GNNs) or logistic matching on behavioral and co-location features.", "Leverages first-party identifiers (hashed emails - UID2.0) merged with privacy-safe household cluster representations.", "Shifts from individual behavioral tracking to rich contextual feature modeling (content semantics, publisher metadata, time-of-day)."]}, {"id": "KP4", "description": "Privacy Compliance & Aggregated Measurement: Adheres to privacy frameworks (Privacy Sandbox, Clean Rooms).", "required": false, "acceptable_evidence": ["Technical keywords: differential privacy, Snowflake, aggregated telemetry, Clean Rooms.", "Operates within data clean rooms (Snowflake Clean Rooms, Habu) to perform privacy-preserving identity matching without data exchange.", "Adopts aggregated measurement APIs (Google Privacy Sandbox Topics/Protected Audience, Apple SKAdNetwork).", "Applies differential privacy techniques to prevent re-identification of individual users from aggregated telemetry."]}], "critical_failures": ["Assumes third-party cookies or static device IDs are always available across modern web, mobile, and CTV environments.", "Fails to articulate probabilistic matching, contextual modeling, or privacy regulations (ATT/Privacy Sandbox)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What challenges arise when integrating modern AI products with legacy enterprise software such as ERP systems?', '{"key_points": [{"id": "KP1", "description": "Protocol Impedance Mismatch & Data Synchronization: Bridges legacy batch/SOAP protocols with modern real-time AI APIs.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, SOAP, AI, API.", "Overcomes legacy API limitations (SOAP/XML, slow batch exports, lack of real-time webhooks) in ERPs (SAP, Oracle).", "Implements Change Data Capture (CDC via Debezium/Kafka) or ETL staging pipelines to stream updates into AI retrieval stores."]}, {"id": "KP2", "description": "Normalizes complex, highly denormalized, or undocumented ERP database schemas into clean domain models.", "required": true, "acceptable_evidence": ["Technical keywords: SAP BAPI, Oracle ERP, data normalization, domain-driven design, anti-corruption layer, CDC replication.", "Normalizes complex, highly denormalized, or undocumented ERP database schemas into clean domain models.", "Constructs an anti-corruption layer (ACL) and domain models that abstract complex SAP/Oracle ERP table structures into clean, queryable JSON schemas."]}, {"id": "KP3", "description": "Deterministic Integrity vs Probabilistic Outputs: Protects transactional ERP systems from non-deterministic AI mutations.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, human-in-the-loop, HITL, erp transactions.", "Separates read-only analytical queries from state-mutating ERP transactions.", "Enforces strict schema validation (Pydantic, OpenAPI) and business invariant checks before committing AI-generated ERP entries.", "Mandates Human-in-the-Loop (HITL) approval workflows for financial, inventory, or billing mutations."]}, {"id": "KP4", "description": "Enterprise Security, Governance & Audit Isolation: Adheres to ERP authorization and compliance boundaries.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, VPC, AWS, audit isolation.", "Respects legacy role-based access control (RBAC) so the AI never exposes financial data to unauthorized corporate users.", "Ensures compliance with enterprise audit trails, logging every AI-initiated query and recommendation alongside operator approval.", "Deploys AI components within enterprise VPC boundaries (AWS Direct Connect, VPNs) to prevent data egress."]}], "critical_failures": ["Permits an LLM agent to directly execute unchecked transactional writes or SQL updates into a production ERP database.", "Ignores legacy authentication, protocol limitations, or enterprise RBAC security boundaries."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'What changes are required in snapshot_diff to correctly identify added, modified, and deleted files?', '{"key_points": [{"id": "KP1", "description": "Set Difference & Membership Operations: Partitions file paths into added, deleted, and common sets.", "required": true, "acceptable_evidence": ["Technical keywords: file_path, file_metadata, new_keys, old_keys.", "Represents snapshots as hash maps: `{file_path: file_metadata}` (where metadata includes hash, mtime, size).", "Computes added files: `added = new_keys - old_keys` (paths present in new snapshot but absent in old snapshot).", "Computes deleted files: `deleted = old_keys - new_keys` (paths present in old snapshot but absent in new snapshot)."]}, {"id": "KP2", "description": "Modification Detection via Content Hashes: Accurately identifies modified files in the common intersection.", "required": true, "acceptable_evidence": ["Technical keywords: old_keys, new_keys, SHA-256, MD5.", "Identifies common files: `common = old_keys & new_keys`.", "Checks modification condition: compares content checksum (SHA-256 / MD5) or mtime/size tuple (`old[path].hash != new[path].hash`).", "Appends path to modified list only when metadata or checksum indicates genuine content alteration."]}, {"id": "KP3", "description": "Efficiency & Rename Handling: Validates O(N) runtime and optional heuristic file rename detection.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, O(n), rename, runtime.", "Achieves linear O(N) time complexity where N is the total number of files across both snapshots.", "Handles renamed files optionally by matching identical content hashes between deleted and added paths.", "Handles edge cases: empty snapshots, directory structure changes, symlinks, and permission changes."]}], "critical_failures": ["Performs nested O(N^2) list searches instead of set/hash map key lookups.", "Fails to compare content hashes or metadata for common files, missing all modified files."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What considerations are important when building AI solutions for real-world domains like healthcare or manufacturing?', '{"key_points": [{"id": "KP1", "description": "Domain Regulatory & Compliance Frameworks: Operates strictly within legal and functional safety standards.", "required": true, "acceptable_evidence": ["Technical keywords: HIPAA, FDA, BAA, IEC.", "Healthcare: Enforces HIPAA de-identification (Safe Harbor method), FDA Software as a Medical Device (SaMD) validation guidelines, and BAA agreements.", "Manufacturing: Adheres to functional safety (IEC 61508, ISO 26262), OSHA worker safety rules, and quality standards (ISO 9001)."]}, {"id": "KP2", "description": "Maintain immutable audit logging for traceability and regulatory scrutiny.", "required": true, "acceptable_evidence": ["Technical keywords: immutable audit log, WORM storage, HIPAA compliance, 21 CFR Part 11, cryptographic hashing, traceability.", "Maintains immutable audit logging for traceability and regulatory scrutiny.", "Persists all user prompts, retrieved chunk IDs, and LLM outputs into write-once-read-many (WORM) storage with cryptographic hashes for regulatory auditability."]}, {"id": "KP3", "description": "High-Assurance Safety, Grounding & Human-in-the-Loop: Scopes models to assistive decision support rather than autonomous control.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, citation grounding, E-stop.", "Deploys AI strictly as clinical or diagnostic decision-support, always requiring licensed clinician sign-off (HITL).", "Manufacturing: Decouples AI predictive maintenance alerts from deterministic emergency stop (E-stop) interlocks.", "Enforces zero-hallucination tolerance through strict citation grounding and confidence threshold aborts."]}, {"id": "KP4", "description": "Data Quality, Sensor Drift & Edge Constraints: Manages noisy telemetry and harsh operational deployment environments.", "required": false, "acceptable_evidence": ["Technical keywords: ONNX, DICOM, EHR, PLC.", "Deploys on-premise or edge inference (industrial gateways, low-latency ONNX/TensorRT) where internet connectivity is air-gapped or unreliable.", "Monitors sensor calibration drift and noisy industrial telemetry using statistical drift detectors.", "Handles unstructured multi-modal formats: DICOM medical imaging, EHR clinical notes, PLC sensor logs."]}], "critical_failures": ["Proposes unvalidated, black-box generative AI making autonomous clinical diagnoses or controlling heavy industrial machinery without human review.", "Fails to acknowledge regulatory frameworks (HIPAA, SaMD, ISO) in regulated domains."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'What data sources did you use for your AI system, and how did you manage and store them?', '{"key_points": [{"id": "KP1", "description": "Polyglot Data Storage Architecture: Maps distinct data types to appropriate specialized persistence engines.", "required": true, "acceptable_evidence": ["Technical keywords: REST, PostgreSQL, S3, AWS.", "Unstructured Raw Documents (PDFs, manuals, resumes): Stored immutably in cloud object storage (AWS S3, MinIO) with versioning and encryption at rest.", "Structured Relational Metadata & Sessions: Stored in PostgreSQL with ACID guarantees for user profiles, permissions, and audit logs."]}, {"id": "KP2", "description": "Vector Embeddings & Semantic Index: Stored in purpose-built vector databases (Milvus, Pinecone, Qdrant) with HNSW indexes and metadata filtering.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, Pinecone, Qdrant, HNSW index, M parameter, efConstruction, metadata filtering, scalar payload.", "Vector Embeddings & Semantic Index: Stored in purpose-built vector databases (Milvus, Pinecone, Qdrant) with HNSW indexes and metadata filtering.", "Configures Milvus collection partitions with HNSW index parameters (M=16, efConstruction=200) and scalar payload fields for tenancy isolation."]}, {"id": "KP3", "description": "Ingestion Pipelines & Schema Consistency: Ensures consistent data flow from external channels into storage layers.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, Kafka, ETL, ELT.", "Uses ETL/ELT pipelines or message queues (Kafka, Celery) to coordinate ingestion across multiple sources (APIs, databases, web scrapes).", "Applies schema validation (Pydantic / Avro) and deduplication (SHA-256 chunk hashing) before writing to downstream stores.", "Synchronizes relational metadata with vector payloads to maintain consistency across storage tiers."]}, {"id": "KP4", "description": "Lifecycle Management, Caching & Data Governance: Enforces retention, fast caching, and access controls.", "required": false, "acceptable_evidence": ["Technical keywords: Redis, TTL, S3, VPC.", "Utilizes fast caching tiers (Redis) for ephemeral conversation history, rate limits, and semantic query caches.", "Enforces lifecycle rules: S3 transition to Glacier for cold archives, TTL policies on conversational logs.", "Complies with enterprise security policies: KMS encryption, VPC endpoint isolation, and tenant partition keys."]}], "critical_failures": ["Attempts to dump raw binary files, embeddings, and transactional records all into a single unindexed relational table without separation of concerns.", "Fails to explain how data consistency is maintained between raw files, relational metadata, and vector indexes."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'What hypotheses would you test regarding acquisition channels, marketing strategies, or user targeting to explain changes in spending behavior?', '{"key_points": [{"id": "KP1", "description": "Acquisition Channel Mix & Quality Shift Hypotheses: Tests if shifts between marketing channels dilute customer purchasing power.", "required": true, "acceptable_evidence": ["Technical keywords: TikTok, SEM, CVR, ARPU.", "Hypothesis 1 (Channel Dilution): An increase in low-intent traffic from broad affiliate or paid social channels (TikTok, display) diluted overall cohort monetization compared to high-intent search (Google SEM).", "Tests channel-specific Conversion Rate (CVR) and 30-day Average Revenue Per User (ARPU) across acquisition sources."]}, {"id": "KP2", "description": "Evaluate whether marketing budget reallocations caused an influx of non-core demographic users.", "required": true, "acceptable_evidence": ["Technical keywords: customer acquisition cost (CAC), cohort lifetime value (LTV), campaign attribution, channel cannibalization, marketing mix.", "Evaluates whether marketing budget reallocations caused an influx of non-core demographic users.", "Performs cohort spend analysis comparing acquisition channels (paid search vs organic vs social) to identify shifts in customer lifetime value (LTV)."]}, {"id": "KP3", "description": "Incentive Elasticity & Discount Cannibalization: Tests whether aggressive promotions attracted one-off deal seekers.", "required": true, "acceptable_evidence": ["Technical keywords: Promo Dependency, incentive, elasticity, discount.", "Hypothesis 2 (Promo Dependency): Generous signup discounts attracted coupon-seeking users with high day-1 conversion but zero full-price retention.", "Analyzes repeat purchase curves and margins segmented by users who redeemed promotions vs users who paid full price.", "Investigates whether promotions cannibalized organic full-price purchases from existing cohorts."]}, {"id": "KP4", "description": "Targeting Saturation & Macro Confounders: Evaluates audience saturation, creative fatigue, and macroeconomic factors.", "required": false, "acceptable_evidence": ["Technical keywords: ICP, Audience Saturation, price increases, checkout bugs.", "Hypothesis 3 (Audience Saturation): Ad targeting expansion diluted ideal customer profile (ICP) match as lookalike audience sizes expanded.", "Controls for product and pricing changes (e.g., price increases, changes in shipping fees, checkout bugs).", "Applies regression models or difference-in-differences to quantify the variance explained by each hypothesis."]}], "critical_failures": ["Blames spending drops on vague speculation without proposing structured, testable hypotheses or validation metrics.", "Fails to segment users by acquisition channel or promotional exposure."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'EASY', 'SPECIFIC', 60, 'What is a race condition, and how do thread locks help prevent it in concurrent applications?', '{"key_points": [{"id": "KP1", "description": "Definition of Race Conditions: Explains non-deterministic outcomes caused by concurrent unsynchronized execution.", "required": true, "acceptable_evidence": ["Technical keywords: definition, conditions, outcomes, caused.", "Defines a race condition as an anomaly where multiple threads concurrently read and write shared mutable state without proper synchronization.", "Explains the read-modify-write hazard (e.g., `counter += 1` decompiles into multiple bytecode instructions: load, increment, store; thread interleaving leads to lost updates)."]}, {"id": "KP2", "description": "Emphasizes that execution outcomes become dependent on unpredictable operating system thread scheduling.", "required": true, "acceptable_evidence": ["Technical keywords: race condition, threading.Lock, mutex, critical section, thread scheduling non-determinism, mutual exclusion.", "Emphasizes that execution outcomes become dependent on unpredictable operating system thread scheduling.", "Demonstrates how shared mutable state without synchronization produces non-deterministic outcomes, resolving it using threading.Lock mutexes in Python."]}, {"id": "KP3", "description": "Mutual Exclusion via Mutex / Locks: Explains how acquiring locks serializes access to critical sections.", "required": true, "acceptable_evidence": ["Technical keywords: context managers, RAII, via mutex, acquiring locks.", "Explains that a mutex (mutual exclusion lock) enforces that only one thread can hold the lock and execute the critical section at a time.", "Other threads attempting to acquire the lock are blocked/suspended until the owning thread releases it.", "Recommends RAII / context managers (e.g., Python `with lock:` or Java `synchronized`) to guarantee lock release even if exceptions occur."]}, {"id": "KP4", "description": "Locking Trade-offs & Alternatives: Discusses deadlock risks, contention, and lock-free concurrency alternatives.", "required": false, "acceptable_evidence": ["Technical keywords: CAS, locking trade-offs, free concurrency, circular lock.", "Identifies drawbacks: performance bottlenecks under high contention, priority inversion, and deadlock risks from circular lock dependencies.", "Mentions lock granularity: coarse-grained locks reduce parallelism; fine-grained locks increase complexity and deadlock potential.", "Mentions alternatives: atomic operations (CAS - Compare-And-Swap), thread-confined state, or message-passing concurrency."]}], "critical_failures": ["Confuses race conditions with general thread latency or asynchronous IO waiting.", "Fails to explain that locks serialize access by blocking concurrent threads from entering the critical section."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is semantic meaning in the context of search, and how does it differ from keyword-based matching?', '{"key_points": [{"id": "KP1", "description": "Semantic Vector Search Mechanics: Explains dense embedding representations and geometric similarity.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, vector search, word tokens, Inner Product.", "Defines semantic search as mapping queries and text documents into a shared continuous dense vector space using embedding models.", "Measures conceptual similarity via vector distance (Cosine Similarity, Inner Product) based on underlying meaning rather than exact word tokens."]}, {"id": "KP2", "description": "Captures synonyms, related concepts, intent, and paraphrases (e.g., ''EV battery degradation'' matches ''lithium cell health loss'' without shared words).", "required": true, "acceptable_evidence": ["Technical keywords: dense embeddings, cosine similarity, semantic search, BM25, synonym matching, conceptual intent, vector representation.", "Captures synonyms, related concepts, intent, and paraphrases (e.g., ''EV battery degradation'' matches ''lithium cell health loss'' without shared words).", "Transforms text queries into dense vector embeddings via Transformer models, calculating cosine similarity in vector space rather than token frequencies (TF-IDF/BM25)."]}, {"id": "KP3", "description": "Keyword-Based Matching (Lexical/BM25): Explains inverted index token matching and its failure modes.", "required": true, "acceptable_evidence": ["Technical keywords: BM25, TF-IDF, SKU, inverted index.", "Defines keyword search (BM25 / TF-IDF) as matching exact text tokens using an inverted index with term frequency and inverse document frequency weighting.", "Suffers from vocabulary mismatch problem (fails when users use synonyms or colloquial phrasing not in documents).", "Excels at exact alphanumeric lookups (part numbers, SKU codes, acronyms, product IDs) where embedding models often blur specific tokens."]}, {"id": "KP4", "description": "Hybrid Search & Reciprocal Rank Fusion: Combines dense and sparse search for optimal production retrieval.", "required": false, "acceptable_evidence": ["Technical keywords: hybrid search, Reciprocal Rank Fusion, RRF, Milvus.", "Advocates hybrid retrieval: combining dense vector search (semantic) with sparse BM25 (keyword) in Milvus/Elasticsearch.", "Merges candidate results using Reciprocal Rank Fusion (RRF) or learned score interpolation.", "Applies a secondary cross-encoder reranker (e.g., BGE-Reranker-Large) to score the top candidates with deep attention."]}], "critical_failures": ["Claims semantic search and keyword search are identical or cannot explain how embeddings capture synonyms.", "Fails to recognize that keyword search remains superior for exact serial numbers, error codes, and alphanumeric IDs."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What is the current status of your system, and what motivated you to look for new opportunities?', '{"key_points": [{"id": "KP1", "description": "Current System Health & Successful Delivery: Demonstrates successful feature launch, stabilization, and knowledge handoff.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, knowledge handoff.", "Describes current project status as successfully deployed in production, stabilized, and running reliably under monitoring.", "Has established comprehensive documentation, runbooks, and automated CI/CD suites enabling the existing team to maintain it."]}, {"id": "KP2", "description": "Leaves systems in an orderly, maintainable state rather than abandoning half-finished, broken implementations.", "required": true, "acceptable_evidence": ["Technical keywords: production handover, runbook documentation, CI/CD pipeline, system maintainability, career progression.", "Leaves systems in an orderly, maintainable state rather than abandoning half-finished, broken implementations.", "Ensures production systems are documented with automated runbooks, monitoring dashboards, and clean CI/CD pipelines before transitioning to new challenges."]}, {"id": "KP3", "description": "Forward-Looking Career Motivation: Frames job search around seeking greater technical impact and growth.", "required": true, "acceptable_evidence": ["Technical keywords: job search, forward, looking, AI.", "Articulates positive career motivations (seeking higher system scale, leading complex agentic/AI platform architectures, expanding scope).", "Explains why the prospective company''s domain, technical challenges, and culture specifically align with their career goals.", "Demonstrates ambition to take on larger architectural responsibilities and tackle unsolved problems."]}, {"id": "KP4", "description": "Professionalism & Constructive Perspective: Discusses current and past experiences with respect and gratitude.", "required": false, "acceptable_evidence": ["Technical keywords: professionalism, constructive, perspective, experiences.", "Speaks respectfully of past colleagues, managers, and companies without venting or airing grievances.", "Highlights valuable lessons and architectural skills gained in current role.", "Displays clear enthusiasm for the prospective opportunity."]}], "critical_failures": ["Bashes past employers, managers, or colleagues with bitter, unprofessional complaints.", "Leaves the current project in a broken or chaotic state without documentation or stabilization."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'EASY', 'BROAD', 90, 'What is the most significant technical learning or insight you gained from building this system?', '{"key_points": [{"id": "KP1", "description": "Deep Technical Insight & Counter-Intuitive Learning: Articulates a non-obvious engineering realization from practical implementation.", "required": true, "acceptable_evidence": ["Technical keywords: affects retrieval, agentic loops, insight, counter.", "Shares a profound technical learning (e.g., ''Data parsing and chunking quality affects retrieval far more than swapping embedding models'').", "Realizes that prompt engineering without automated golden evaluation suites is subjective guesswork that invites regressions.", "Discovers that agentic loops require strict deterministic boundaries and token budgets to prevent cascading failure storms."]}, {"id": "KP2", "description": "Concrete System Evidence & Turning Point: Grounds the insight in a specific technical challenge or production turning point.", "required": true, "acceptable_evidence": ["Technical keywords: subtle retrieval, naive chunking, concrete, evidence.", "Narrates the specific incident or experiment that triggered the realization (e.g., a subtle retrieval hallucination that trace inspection uncovered).", "Explains the technical pivot made (e.g., transitioning from naive chunking to layout-aware Docling parsing with markdown tables).", "Shows the measured improvement resulting from the pivot (e.g., Hit Rate jumped from 64% to 89%)."]}, {"id": "KP3", "description": "Evolution of Engineering Philosophy: Explains how this insight permanently shaped their approach to system design.", "required": false, "acceptable_evidence": ["Technical keywords: evolution, engineering, philosophy, insight.", "Applies the learning as a foundational design principle in all subsequent system architectures.", "Advocates for automated evaluation gates, comprehensive telemetry, and defensive system decoupling across teams.", "Mentors other engineers to avoid the same architectural pitfalls."]}], "critical_failures": ["Provides superficial clichés (''I learned how to code in Python'') without any architectural or engineering insight.", "Cannot cite any real challenge, pivot, or outcome that substantiated their supposed learning."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What is your approach to defining OKRs and aligning them with broader organizational goals for AI-driven automation?', '{"key_points": [{"id": "KP1", "description": "Strategic Alignment & Goal Cascading: Connects corporate objectives directly to AI automation roadmaps.", "required": true, "acceptable_evidence": ["Technical keywords: AI, strategic alignment, strategic, cascading.", "Cascades high-level organizational objectives (e.g. improve customer retention, reduce operational cost) into team AI goals.", "Frames Objectives as ambitious, qualitative outcome statements (e.g., ''Automate tier-1 customer inquiries with high factual trust'').", "Aligns cross-functionally with product managers, data engineering, and business unit leaders during quarterly planning."]}, {"id": "KP2", "description": "Quantifiable, Measurable Key Results: Defines unambiguous, outcome-based Key Results rather than activity lists.", "required": true, "acceptable_evidence": ["Technical keywords: p95, response latency, quantifiable, measurable.", "Formulates quantifiable KRs (e.g., ''KR1: Increase First Contact Resolution from 55% to 75% on billing topics'').", "Includes quality and safety KRs: ''KR2: Maintain hallucination rate below 1.5% across golden evaluation suite''.", "Includes operational KRs: ''KR3: Maintain p95 streaming response latency under 1.8 seconds with 99.9% availability''."]}, {"id": "KP3", "description": "Continuous Tracking & Agile Cadence: Monitors OKR pacing and manages scope adjustments pragmatically.", "required": false, "acceptable_evidence": ["Technical keywords: OKR, must achieve 100%, aiming for 70%.", "Reviews OKR confidence scores bi-weekly during sprint reviews to identify off-track initiatives early.", "Differentiates committed OKRs (must achieve 100%) from aspirational/stretch OKRs (aiming for 70%).", "Conducts end-of-quarter retrospectives to evaluate delivery and calibrate difficulty for subsequent quarters."]}], "critical_failures": ["Defines OKRs as a laundry list of tasks (''Write code'', ''Read docs'') rather than measurable outcome-driven business metrics.", "Sets ambitious volume goals without any quality, safety, or latency guardrail key results."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'EASY', 'SPECIFIC', 60, 'What is your approach to robust error handling in applications, including retry mechanisms, fallback strategies, and logging?', '{"key_points": [{"id": "KP1", "description": "Intelligent Retries & Backoff with Jitter: Retries transient network/API failures without causing thundering herds.", "required": true, "acceptable_evidence": ["Technical keywords: exponential backoff, jitter, HTTP 429, max_delay.", "Distinguishes retryable errors (HTTP 429 rate limit, 503 service unavailable, network timeout) from non-retryable errors (400 bad request, 401 unauthorized).", "Applies exponential backoff: `delay = min(max_delay, base_delay * 2^attempt)` to give struggling services recovery headroom.", "Adds random full jitter to retry intervals to desynchronize requests and prevent thundering herd spikes."]}, {"id": "KP2", "description": "Circuit Breakers & Graceful Degradation Fallbacks: Protects downstream dependencies and provides graceful user degradation.", "required": true, "acceptable_evidence": ["Technical keywords: circuit breaker, breaker states, request timeouts, Closed.", "Implements circuit breaker states (Closed, Open, Half-Open): trips open after error thresholds exceed limits to fail fast without bombarding downstream services.", "Provides meaningful fallbacks: serving cached data, secondary fallback model endpoints, or user-friendly status notices.", "Enforces strict request timeouts to prevent hung socket connections from tying up worker threads."]}, {"id": "KP3", "description": "Structured Contextual Logging & Observability: Logs actionable diagnostic context without leaking sensitive data.", "required": false, "acceptable_evidence": ["Technical keywords: Prometheus, log_level, trace_id, user_id.", "Employs structured JSON logging with standardized fields: timestamp, log_level, trace_id, user_id, error_code, stack_trace.", "Sanitizes logs to ensure no PII, API tokens, or secrets are written to log aggregators.", "Emits error counter metrics (Prometheus) linked to automated alerting on error rate spikes."]}], "critical_failures": ["Retries non-retryable 4xx client errors in an infinite tight loop without backoff or jitter.", "Swallows exceptions silently with empty try/catch blocks, obscuring errors without logging or metric increments."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'SPECIFIC', 60, 'What is your model promotion strategy, and how do you decide when to replace an existing model?', '{"key_points": [{"id": "KP1", "description": "Offline Gating & Golden Suite Verification: Requires candidate models to beat baseline benchmarks prior to staging.", "required": true, "acceptable_evidence": ["Technical keywords: CI/CD, CI, CD, AUC.", "Evaluates candidate models against an immutable golden evaluation dataset in CI/CD pipelines (MLflow/Weights & Biases).", "Mandates that candidate model matches or exceeds the current champion across core metrics (AUC, F1, Hit Rate, Faithfulness)."]}, {"id": "KP2", "description": "Verify that inference latency (p95) and token cost do not violate operational production SLAs.", "required": true, "acceptable_evidence": ["Technical keywords: MLflow model registry, champion-challenger, Canary deployment, P95 latency SLA, cost-benefit analysis.", "Verifies that inference latency (p95) and token cost do not violate operational production SLAs.", "Benchmarks challenger models against champions in staging, validating that P95 latency and token costs meet production SLAs before registry promotion."]}, {"id": "KP3", "description": "Champion-Challenger & Shadow/Canary Deployment: Evaluates candidate models against live production traffic safely.", "required": true, "acceptable_evidence": ["Technical keywords: canary deployment, champion, challenger, shadow.", "Shadow deployment: Routes 100% of live traffic to the challenger model asynchronously, logging predictions without exposing them to users.", "Canary / A/B rollout: Routes a small percentage of live traffic (e.g. 5% -> 20% -> 50%) to the challenger to measure live business metrics.", "Compares champion vs challenger on online conversion, user feedback, and error rates using statistical hypothesis testing."]}, {"id": "KP4", "description": "Automated Promotion & Instant Rollback Mechanism: Executes zero-downtime cutover with automated rollback safeguards.", "required": false, "acceptable_evidence": ["Technical keywords: automated, promotion, instant, mechanism.", "Promotes challenger to official Champion status in the Model Registry upon meeting pre-defined statistical criteria.", "Automates immediate rollback to the previous champion model if error rates or safety trip thresholds exceed limits during rollout.", "Maintains audit logs of who authorized the model promotion and the validation results supporting the decision."]}], "critical_failures": ["Swaps production models directly to 100% traffic without offline golden suite validation or phased canary testing.", "Fails to establish automated rollback mechanisms if the newly promoted model exhibits anomalies in production."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What is your process for iteratively improving system quality based on testing and evaluation results?', '{"key_points": [{"id": "KP1", "description": "Evaluation Analytics & Error Categorization: Decomposes evaluation test failures into specific error taxonomies.", "required": true, "acceptable_evidence": ["Technical keywords: recall, prompt injection, DeepEval, granular metrics.", "Runs automated evaluation suites (DeepEval, Ragas) measuring granular metrics: Faithfulness, Answer Relevance, Context Recall.", "Categorizes test failures into a structured error taxonomy: retrieval gap (wrong chunks), synthesis gap (model ignored context), formatting failure, or prompt injection.", "Pinpoints the exact pipeline stage responsible for low scores rather than blaming the system globally."]}, {"id": "KP2", "description": "Targeted Engineering Interventions: Applies focused, prioritized fixes to address identified root causes.", "required": true, "acceptable_evidence": ["Technical keywords: hybrid search, system prompt, fine-tuning, BGE.", "For retrieval gaps: adjusts chunk size/overlap, tunes hybrid search alpha weights, or introduces a BGE cross-encoder reranker.", "For synthesis gaps: enhances system prompt instructions, adds targeted few-shot examples of failure cases, or refines output schemas.", "Prioritizes low-cost, fast-turnaround prompt/retrieval changes before considering expensive model fine-tuning."]}, {"id": "KP3", "description": "Regression Prevention & Golden Dataset Expansion: Ensures fixed failure modes remain permanently solved.", "required": false, "acceptable_evidence": ["Technical keywords: golden dataset, regression, prevention, golden.", "Converts resolved failure cases into permanent unit test cases in the golden evaluation dataset.", "Runs full regression test suites before merging any pipeline changes to verify fixes didn''t cause unintended regressions.", "Tracks historical metric trends over successive sprints to visualize continuous quality improvement."]}], "critical_failures": ["Attempts random, unmeasured prompt tweaking without automated evaluation metrics or regression testing.", "Fails to categorize errors or identify whether retrieval or LLM generation caused the failure."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What is your process for moving a model from development to production and ensuring its long-term health?', '{"key_points": [{"id": "KP1", "description": "Productionization Pipeline & Serving Architecture: Packages models into scalable, version-controlled microservices.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, Kubernetes, EKS, SageMaker.", "Logs validated models to a centralized Model Registry (MLflow/Triton) with artifact hashes, dependencies, and signatures.", "Containerizes serving using Docker and deploys on Kubernetes (EKS) or managed endpoints (SageMaker, Vertex AI) with autoscaling.", "Ensures training-serving feature parity using feature stores (Feast) to prevent online-offline skew."]}, {"id": "KP2", "description": "Production Monitoring & Drift Detection: Continuously monitors model predictions, inputs, and system latency.", "required": true, "acceptable_evidence": ["Technical keywords: concept drift, Population Stability Index, PSI, Prometheus.", "Monitors operational health metrics (p95 latency, throughput, GPU utilization, error rates) via Prometheus and Grafana.", "Detects data and concept drift: monitors feature distribution shifts using Population Stability Index (PSI) and Kolmogorov-Smirnov (KS) tests.", "Configures automated PagerDuty alerts when drift metrics exceed statistical safety thresholds (e.g., PSI > 0.2)."]}, {"id": "KP3", "description": "Continuous Retraining & Governance Cadence: Manages model updates and regulatory compliance.", "required": false, "acceptable_evidence": ["Technical keywords: retraining pipelines, Airflow, Kubeflow.", "Establishes automated retraining pipelines (Airflow/Kubeflow) triggered by scheduled intervals or detected performance decay.", "Enforces shadow/canary deployments for newly trained model checkpoints before directing 100% of live traffic.", "Maintains audit logs of all model versions, predictions, and retraining lineages for regulatory governance."]}], "critical_failures": ["Considers a model ''done'' upon local deployment without monitoring for data drift or performance degradation.", "Fails to address training-serving feature skew or lacks containerized deployment automation."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'EASY', 'SPECIFIC', 60, 'What is your understanding of healthcare data standards like FHIR or HL7?', '{"key_points": [{"id": "KP1", "description": "FHIR (Fast Healthcare Interoperability Resources) Architecture: Explains modern RESTful JSON resources and clinical schemas.", "required": true, "acceptable_evidence": ["Technical keywords: REST, FHIR, JSON, XML.", "Explains that FHIR is built on modern web standards (REST APIs, JSON, XML, OAuth2/SMART on FHIR).", "Structures clinical data into modular ''Resources'' (e.g., Patient, Observation, Condition, MedicationRequest, DiagnosticReport).", "Includes standardized coding systems (LOINC for labs, SNOMED CT for clinical findings, RxNorm for medications, ICD-10 for diagnoses)."]}, {"id": "KP2", "description": "Legacy HL7 v2 Comparison & Interoperability: Contrasts pipe-delimited legacy formats with FHIR.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, MSH, PID, OBR.", "Contrasts FHIR with legacy HL7 v2: HL7 v2 uses pipe-delimited segment messages (e.g., MSH, PID, OBR) transmitted via MLLP over TCP.", "Identifies common integration challenges: HL7 v2 is event-driven and highly customized across hospital systems, requiring interface engines (Mirth Connect, Rhapsody).", "Explains conversion pipelines transforming legacy HL7 v2 feeds into FHIR JSON resources for downstream RAG and analytics."]}, {"id": "KP3", "description": "Healthcare AI Integration & HIPAA Compliance: Connects clinical standards to AI retrieval and data privacy.", "required": false, "acceptable_evidence": ["Technical keywords: HIPAA, RBAC, AI, PHI.", "Applies HIPAA Safe Harbor or Expert Determination de-identification (redacting 18 PHI identifiers) before indexing FHIR resources into vector databases.", "Chunks FHIR resources logically around clinical encounters rather than naive text splitting to preserve patient record context.", "Enforces strict patient consent and role-based access control (RBAC) at the FHIR API query layer."]}], "critical_failures": ["Conflates FHIR with general medical terminology, unable to identify it as a RESTful JSON resource standard.", "Ignores HIPAA privacy or PHI de-identification requirements when processing healthcare records for AI systems."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'EASY', 'BROAD', 90, 'What is your understanding of the company·s domain and business focus based on your research?', '{"key_points": [{"id": "KP1", "description": "Thorough Business Model & Core Product Articulation: Demonstrates clear understanding of what the company builds and sells.", "required": true, "acceptable_evidence": ["Technical keywords: SMB, B2B enterprise, consumer.", "Articulates the company''s core product offerings, target customer personas (B2B enterprise, consumer, SMB), and revenue model.", "Identifies the key industry problem the company solves and why customers pay for their solution.", "References recent public announcements, product feature releases, or architectural engineering blog posts."]}, {"id": "KP2", "description": "Domain-Specific Technical Challenges: Pinpoints technical hurdles unique to the company''s operating space.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, AI, ML, time latency.", "Identifies technical challenges specific to the domain (e.g., real-time latency in ad tech, strict regulatory compliance in healthcare, high document heterogeneity in recruiting).", "Recognizes where modern AI/ML (RAG, agentic automation, predictive scoring) creates defensible product differentiation.", "Connects their personal technical expertise directly to solving the company''s prospective bottlenecks."]}, {"id": "KP3", "description": "Competitive Context & Strategic Curiosity: Discusses market positioning and asks insightful forward-looking questions.", "required": false, "acceptable_evidence": ["Technical keywords: architecture trade-offs, competitive, context, strategic.", "Shows awareness of the broader market landscape, key competitors, and company differentiators.", "Formulates thoughtful, well-researched questions about the engineering roadmap, architecture trade-offs, and scaling plans.", "Demonstrates genuine passion and alignment with the company''s mission and technical direction."]}], "critical_failures": ["Admits to doing zero research on the company prior to the interview or confuses the company with a totally different product.", "Provides vague generic statements that could apply to any software business without referencing the company''s actual domain."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What programming languages and technologies have you primarily used, and how did you decide which to apply in different parts of your system?', '{"key_points": [{"id": "KP1", "description": "Language-to-Domain Mapping: Justifies language choices based on library ecosystems, execution speed, and domain fitness.", "required": true, "acceptable_evidence": ["Technical keywords: Pandas, ReAct, LangGraph, PyTorch.", "Python for AI orchestration, data engineering, and ML modeling (rich ecosystem: PyTorch, Hugging Face, LangGraph, FastAPI, Pandas).", "TypeScript / React for frontend client interfaces (compile-time type safety, component reusability, interactive real-time UX)."]}, {"id": "KP2", "description": "Compiled languages (Go, Java, Rust) for high-concurrency microservices, network proxies, or compute-heavy data ingestion pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: Go microservices, Rust data pipelines, Python AI runtime, polyglot architecture, concurrency performance.", "Compiled languages (Go, Java, Rust) for high-concurrency microservices, network proxies, or compute-heavy data ingestion pipelines.", "Selects compiled languages (Go/Rust) for high-throughput network proxies and data ingestion pipelines, while using Python for ML orchestration and model serving."]}, {"id": "KP3", "description": "Inter-Service Communication & Contracts: Connects polyglot tiers using strongly typed network interfaces.", "required": true, "acceptable_evidence": ["Technical keywords: REST, GraphQL, gRPC, Protocol Buffers.", "Defines explicit, language-agnostic data contracts (REST OpenAPI, gRPC Protocol Buffers, GraphQL) across service boundaries.", "Uses asynchronous message brokers (Kafka, RabbitMQ, SQS) to decouple Python background workers from frontend API gateways.", "Enforces automated contract validation to ensure cross-language schema compatibility during deployments."]}, {"id": "KP4", "description": "Operational Overhead & Team Cognitive Load: Balances technological specialization against operational maintenance.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, Docker, Kubernetes, CI/CD.", "Weighs the operational cost of managing multiple runtimes, CI/CD pipelines, and container base images.", "Standardizes shared infrastructure: Docker containers, Kubernetes deployments, and unified OpenTelemetry tracing across all languages.", "Considers team hiring, onboarding speed, and code maintenance before introducing a new programming language."]}], "critical_failures": ["Chooses languages based on personal whims without technical justification regarding ecosystem, performance, or operational trade-offs.", "Fails to establish typed contracts (REST/gRPC/Protobuf) between services in a polyglot architecture."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What qualities do you believe are essential for solving unfamiliar technical problems, and how do you approach such challenges?', '{"key_points": [{"id": "KP1", "description": "First-Principles Decomposition & Problem Scoping: Deconstructs complex unknowns into fundamental verifiable assumptions.", "required": true, "acceptable_evidence": ["Technical keywords: decomposition, problem, deconstructs, complex.", "Breaks ambiguous, unfamiliar problems down into smaller, independently testable sub-problems using first principles.", "Formulates explicit hypotheses and isolates variables to test system behavior methodically rather than guessing blindly."]}, {"id": "KP2", "description": "Distinguish between symptoms and underlying root causes through telemetry, debug logs, and reproducible test cases.", "required": true, "acceptable_evidence": ["Technical keywords: root cause analysis, telemetry correlation, binary search debugging, reproducible test cases, distributed tracing.", "Distinguishes between symptoms and underlying root causes through telemetry, debug logs, and reproducible test cases.", "Isolates root causes systematically by constructing minimal reproducible test scripts and correlating distributed trace spans across services."]}, {"id": "KP3", "description": "Rapid Technical Spikes & Deep Research: Validates assumptions through minimal prototypes and rigorous research.", "required": true, "acceptable_evidence": ["Technical keywords: GitHub, RFC, rapid, spikes.", "Builds throwaway proof-of-concept spikes in isolated sandbox environments to rapidly test unknown library behaviors or APIs.", "Digs directly into open-source library source code, GitHub issues, and RFC specifications when official documentation is sparse or misleading.", "Demonstrates intellectual curiosity and rapid learning velocity when encountering unfamiliar tech stacks."]}, {"id": "KP4", "description": "Collaboration, Humility & Knowledge Codification: Leverages team expertise and documents findings for future resilience.", "required": false, "acceptable_evidence": ["Technical keywords: humility, knowledge, codification, leverages.", "Knows when to timebox solo debugging and consult domain experts or teammates constructively with well-framed questions.", "Maintains composure, persistence, and psychological resilience when facing novel, high-stakes system failures.", "Documents the discovered solution, architectural constraints, and failure modes in internal runbooks/ADRs."]}], "critical_failures": ["Panics or gets completely paralyzed when faced with unfamiliar tech, waiting for someone else to provide exact answers.", "Applies random trial-and-error changes without forming hypotheses, isolating variables, or consulting system logs."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What qualities do you think make an ideal AI Solutions Engineer?', '{"key_points": [{"id": "KP1", "description": "Technical Versatility & Systems Integration Depth: Combines AI expertise with robust backend software engineering.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, structured outputs, CI/CD, AI.", "Possesses strong software engineering hygiene (APIs, microservices, databases, CI/CD) alongside AI engineering (RAG, agents, vector stores).", "Excels at integrating AI components into heterogeneous legacy enterprise customer stacks (ERPs, CRMs, legacy relational databases).", "Deploys robust guardrails, deterministic data sanitization, and structured outputs rather than building toy prompt demos."]}, {"id": "KP2", "description": "Client Empathy & Managing Probabilistic Expectations: Translates business problems into realistic technical roadmaps.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, AI, client, empathy.", "Listens empathetically to enterprise client workflows to uncover the true underlying operational pain points.", "Educates non-technical client stakeholders on the probabilistic, non-deterministic nature of generative AI systems.", "Frames expectations realistically around accuracy, hallucination risk mitigation, and the necessity of human-in-the-loop review."]}, {"id": "KP3", "description": "Pragmatic Problem Solving & Commercial Acumen: Prioritizes business ROI, rapid prototyping, and client enablement.", "required": false, "acceptable_evidence": ["Technical keywords: ROI, pragmatic, problem, solving.", "Possesses a bias for action: rapidly builds functional, secure POCs that prove measurable business value to prospective buyers.", "Balances client customization requests against long-term product maintainability and scalable platform design.", "Conducts effective knowledge transfer and enablement pairing sessions to make customer engineering teams self-sufficient."]}], "critical_failures": ["Acts as a pure salesperson with zero hands-on coding ability, or acts as a pure researcher unable to speak to customers.", "Over-promises 100% deterministic perfection on generative AI systems without managing client expectations on probabilistic models."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What steps do you take before an interview to avoid preventable issues and ensure readiness?', '{"key_points": [{"id": "KP1", "description": "Hardware, Network & Software Environment Audit: Ensures development tools, audio/video, and connectivity are tested.", "required": true, "acceptable_evidence": ["Technical keywords: ISP, IDE, CoderPad, environment audit.", "Tests camera, microphone, and secondary audio equipment in advance to guarantee crystal-clear audio and zero echo.", "Verifies stable broadband internet connection with a backup mobile hotspot ready in case of ISP failure.", "Configures coding environments (IDE, compiler, syntax highlighting, permissions for screen sharing) and tests platform links (CoderPad, Zoom)."]}, {"id": "KP2", "description": "Company, Product & Interviewer Research: Aligns preparation with the prospective team''s domain and stack.", "required": true, "acceptable_evidence": ["Technical keywords: STAR, their architecture, company, product.", "Researches the company''s business model, customer use cases, and public engineering publications or open-source projects.", "Reviews the job description to align past STAR project narratives directly with required technical competencies.", "Formulates thoughtful, technically rigorous questions to ask the interviewers about their architecture and team dynamics."]}, {"id": "KP3", "description": "Distraction Minimization & Mental Calibration: Prepares physical space and mental focus for peak execution.", "required": false, "acceptable_evidence": ["Technical keywords: distraction, minimization, mental, prepares.", "Eliminates environmental distractions: closes background tabs, mutes notifications, and ensures a quiet, professional workspace.", "Keeps notepad, pen, and water accessible to sketch architectural diagrams and jot down interviewer constraints.", "Allocates buffer time before the interview to review key concepts calmly rather than cramming nervously at the last second."]}], "critical_failures": ["Shows up with untested software, unconfigured screen-share permissions, broken audio, or noisy environmental distractions.", "Conducts zero research on the company, entering the interview completely unprepared on basic context."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What steps should you take to ensure compliance with interview guidelines, such as disabling AI note-taking tools during interviews?', '{"key_points": [{"id": "KP1", "description": "Proactive Tool Audit & Extension Disablement: Manages background applications and meeting extensions to prevent unpermitted recording.", "required": true, "acceptable_evidence": ["Technical keywords: Otter.ai, Read.ai, AI, tool audit.", "Audits and disables automated meeting bots and AI note-taking tools (Otter.ai, Fireflies, Read.ai, Zoom AI Companion) prior to joining the interview.", "Disables browser extensions and background transcription utilities that automatically record or capture meeting audio without consent.", "Checks account settings on conferencing platforms (Google Meet, Zoom, Teams) to ensure no automatic transcription or bot invites are triggered."]}, {"id": "KP2", "description": "Adherence to NDA & Intellectual Property Guidelines: Respects confidentiality and company evaluation policies.", "required": true, "acceptable_evidence": ["Technical keywords: NDA, NDAs, adherence, intellectual.", "Carefully reviews and abides by interview invitation guidelines, Non-Disclosure Agreements (NDAs), and academic honesty codes.", "Asks explicit permission before recording or using any assistive accessibility tool if medically required.", "Refrains from recording, distributing, or publishing proprietary coding questions or interviewer discussions."]}, {"id": "KP3", "description": "Professional Integrity & Authentic Engagement: Demonstrates personal intellectual ownership during discussions.", "required": false, "acceptable_evidence": ["Technical keywords: AI, professional, integrity, authentic.", "Demonstrates genuine, authentic technical problem solving without relying on unauthorized real-time AI generation aids.", "Focuses full attention on the interviewer rather than monitoring external screens or chat bots.", "Takes manual notes on paper or simple text editors to track problem constraints transparently."]}], "critical_failures": ["Allows unapproved AI meeting bots to join the call or secretly records the interview in violation of company policy.", "Dismisses company guidelines and NDAs as unimportant or uses prohibited real-time AI tools during live evaluations."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'What steps would you take to understand data quality, schema relationships, and undocumented behaviors?', '{"key_points": [{"id": "KP1", "description": "Systematic Schema Inspection & Relationship Mapping: Discovers explicit and implicit foreign key relationships.", "required": true, "acceptable_evidence": ["Technical keywords: information_schema.tables, table_constraints, systematic schema, information schema.", "Queries information schema catalogs (e.g. `information_schema.tables`, `columns`, `table_constraints`) to map data types and foreign keys.", "Identifies implicit unconstrained foreign keys and polymorphic associations by inspecting column naming patterns and joining keys."]}, {"id": "KP2", "description": "Generates automated Entity-Relationship Diagrams (ERDs) using database introspection tools (DBeaver, SchemaSpy).", "required": true, "acceptable_evidence": ["Technical keywords: DBeaver, SchemaSpy, database introspection, ERD generation, foreign key constraints, data profiling.", "Generates automated Entity-Relationship Diagrams (ERDs) using database introspection tools (DBeaver, SchemaSpy).", "Uses database introspection tools (SchemaSpy, Great Expectations) to generate automated ERDs and profile null rates, distributions, and orphaned foreign keys."]}, {"id": "KP3", "description": "Statistical Profiling & Data Quality Auditing: Analyzes distributions, null rates, cardinality, and anomalies.", "required": true, "acceptable_evidence": ["Technical keywords: DBT, regex compliance, Great Expectations, dbt test.", "Computes statistical profiles: null counts, distinct cardinality, min/max values, distributions, and format regex compliance.", "Deploys automated data quality test suites (Great Expectations, dbt test, Soda) to assert data invariants and freshness.", "Detects hidden data anomalies: sentinel values (e.g., -1, 9999, ''N/A'' used as null surrogates) and timezone/timestamp inconsistencies."]}, {"id": "KP4", "description": "Query Log Analysis & Domain Stakeholder Interviews: Uncovers undocumented business logic through query inspection.", "required": false, "acceptable_evidence": ["Technical keywords: pg_stat_statements, ORM, historical schema.", "Analyzes production query logs (pg_stat_statements, slow query logs) to see how application code actually filters and joins tables.", "Inspects ORM models and database migration histories in the codebase to understand historical schema evolution.", "Pairs with legacy domain experts and data engineers to validate unwritten business rules and edge cases."]}], "critical_failures": ["Relies blindly on outdated schema documentation without querying the actual database or running data profiling checks.", "Fails to identify sentinel values or implicit relationship joins in legacy unconstrained tables."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What strategies did you use to detect and prevent data leakage in your AI systems?', '{"key_points": [{"id": "KP1", "description": "Generative AI & Multi-Tenant Egress Prevention: Enforces isolation and redaction to prevent enterprise data leaks.", "required": true, "acceptable_evidence": ["Technical keywords: PII redaction, Microsoft Presidio, tenant_id, AI.", "Enforces multi-tenant data partitioning at the vector database layer using partition keys and strict metadata predicates (tenant_id = X).", "Applies automated PII redaction (Microsoft Presidio) prior to text embedding and LLM prompt generation.", "Deploys output inspection guardrails (NeMo Guardrails, regex filters) to intercept accidental credential or secret emission."]}, {"id": "KP2", "description": "Adversarial Extraction & Prompt Defense: Protects system instructions and proprietary knowledge from exfiltration.", "required": true, "acceptable_evidence": ["Technical keywords: system prompt, prompt injection, Zero Data Retention, ZDR.", "Guards against prompt injection and extraction attacks (''Repeat everything above'') using input sanitizers and safety classifiers.", "Uses strict XML/markdown delimiters with system prompt directives separating trusted instructions from untrusted user inputs.", "Establishes Zero Data Retention (ZDR) enterprise agreements with cloud LLM providers to ensure prompt data is not used for model retraining."]}, {"id": "KP3", "description": "ML Training Leakage & Temporal Splitting: Prevents feature-target leakage and train/test contamination.", "required": false, "acceptable_evidence": ["Technical keywords: cross-validation, ML, training leakage, target leakage.", "Enforces strict time-based train/validation/test splits (temporal cross-validation) to prevent future data from leaking into past training samples.", "Performs data sanitization to verify target variables or post-event features do not contaminate feature sets in feature stores (Feast).", "Runs automated embedding deduplication to detect duplicate or near-duplicate leakage between training and evaluation splits."]}], "critical_failures": ["Permits cross-tenant data retrieval in multi-tenant RAG systems without database-level tenant isolation.", "Fails to address train/test contamination or prompt extraction attack vectors."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What strategies do you use to prevent sensitive information from being exposed to external models while still maintaining contextual responses?', '{"key_points": [{"id": "KP1", "description": "Reversible Tokenization & Pseudonymization Vault: Replaces sensitive entities with contextual surrogate tokens.", "required": true, "acceptable_evidence": ["Technical keywords: tokenization, Microsoft Presidio, pseudonymization, Redis.", "Detects PII entities (names, SSNs, credit cards, company names) using local NER tools (Microsoft Presidio, spaCy) before calling external APIs.", "Replaces entities with typed surrogates or deterministic pseudonyms (e.g., ''Alice Smith'' -> ''[PERSON_1]'', ''Google'' -> ''[COMPANY_A]'').", "Maintains an in-memory or encrypted Redis lookup vault mapping pseudonyms back to original values within the private session boundary."]}, {"id": "KP2", "description": "Downstream Re-Identification & Context Preservation: Reconstructs natural responses by detokenizing the external model output.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, downstream, identification, context.", "Allows the external LLM to reason over semantic relationships between typed placeholders without ever seeing real private data.", "Intercepts the generated model response and substitutes real entities back from the private session lookup table before presenting to the user.", "Preserves grammatical agreement and formatting during entity round-trip substitution."]}, {"id": "KP3", "description": "Hybrid Architecture & Self-Hosted Sensitive Pipelines: Routes highly sensitive tasks to on-premise SLMs.", "required": false, "acceptable_evidence": ["Technical keywords: Zero Data Retention, ZDR, BGE, BAA.", "Employs model routing: routes un-redactable sensitive tasks to self-hosted open-weights models (Llama-3, Mistral) on private VPCs.", "Generates vector embeddings locally using self-hosted models (BGE, sentence-transformers) to prevent text egress during vector search.", "Enforces Zero Data Retention (ZDR) and Business Associate Agreements (BAA) with approved commercial providers as an added layer."]}], "critical_failures": ["Sends raw unredacted customer PII to public third-party LLM APIs with only a system prompt plea not to leak it.", "Permanently strips all context or entity relationships, rendering the external model unable to understand the query."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What strategies would you use to revisit an opportunity with a company at a later time?', '{"key_points": [{"id": "KP1", "description": "Gracious Initial Closing & Relationship Maintenance: Concludes prior discussions with high professionalism and gratitude.", "required": true, "acceptable_evidence": ["Technical keywords: LinkedIn, gracious, closing, relationship.", "Sends a warm, professional closing note expressing genuine appreciation for the interviewers'' time and constructive feedback.", "Connects with recruiters and interviewers on LinkedIn to maintain long-term professional visibility.", "Leaves a lasting positive impression regardless of whether the initial outcome was an offer decline or a rejection."]}, {"id": "KP2", "description": "Tangible Upskilling & Milestone Delivery: Proves meaningful engineering growth and delivered impact during the intervening period.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, open-source, papers, talks.", "Addresses specific technical areas identified during prior feedback (e.g. shipping production distributed systems, mastering RAG/agent architectures).", "Builds a portfolio of concrete accomplishments, shipped products, or public technical contributions (open-source, papers, talks).", "Times follow-up outreach appropriately (typically 6-12 months after the initial interview cycle)."]}, {"id": "KP3", "description": "Targeted, Value-Add Re-Engagement: Reconnects with compelling context relevant to the company''s current challenges.", "required": false, "acceptable_evidence": ["Technical keywords: thoughtful alignment, targeted, value, engagement.", "Reaches out directly to the original recruiter or hiring manager with concise updates highlighting new relevant milestones.", "References recent company product launches or open positions where their enhanced skill set directly solves a current bottleneck.", "Demonstrates sustained enthusiasm and thoughtful alignment with the company''s evolving mission."]}], "critical_failures": ["Burns bridges or sends bitter, unprofessional complaints following an initial rejection.", "Re-applies repeatedly within days or weeks without any technical upskilling, new milestones, or changed context."]}', 1),
('TECHNICAL', 'Software Engineering', 'Concurrency & Async Systems', 'MEDIUM', 'SPECIFIC', 90, 'What synchronization mechanisms or constructs would you use to manage thread lifecycle and coordination in such a concurrent system?', '{"key_points": [{"id": "KP1", "description": "Thread Coordination Primitives (Barriers, Latches & Semaphores): Details synchronization constructs for task coordination.", "required": true, "acceptable_evidence": ["Technical keywords: CountDownLatch, Barriers, Latches & Semaphores, Counting Semaphore.", "Semaphores (Counting Semaphore): Manages access to finite shared resources (e.g. bounding concurrent worker tasks or database connections).", "CountDownLatch / Barriers: Coordinates fan-out / fan-in workflows, allowing a coordinator thread to wait until N worker threads complete.", "Condition Variables (wait/notify): Coordinates producer-consumer thread handoffs, signaling workers when work becomes available in queues."]}, {"id": "KP2", "description": "Thread Lifecycle Management & Thread Pools: Manages thread allocation, reuse, and graceful shutdown.", "required": true, "acceptable_evidence": ["Technical keywords: ThreadPoolExecutor, ExecutorService, Python `ThreadPoolExecutor`, Java `ExecutorService`.", "Utilizes managed thread pools (e.g., Python `ThreadPoolExecutor`, Java `ExecutorService`) to avoid expensive continuous thread creation/destruction.", "Implements bounded blocking queues with backpressure to prevent unbounded task queuing and memory exhaustion.", "Implements graceful shutdown hooks (draining task queues, waiting with timeouts for active threads to complete)."]}, {"id": "KP3", "description": "Cancellation Tokens & Deadlock Avoidance: Handles thread termination and prevents deadlocks.", "required": false, "acceptable_evidence": ["Technical keywords: threading.Event, try_acquire, cancellation tokens, `threading.Event`.", "Employs cooperative cancellation tokens or atomic boolean stop flags (`threading.Event`) rather than forcefully killing threads.", "Prevents deadlocks by enforcing consistent global lock acquisition ordering and timeout-based acquisitions (`try_acquire`).", "Tracks active worker health and replaces failed threads using supervisor heartbeats."]}], "critical_failures": ["Advocates forcefully terminating running OS threads externally, risking corrupted shared state and orphaned locks.", "Cannot distinguish between basic mutexes and multi-thread coordination primitives like semaphores, latches, or condition variables."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What techniques did you use to demonstrate the value of your system without focusing on technical details?', '{"key_points": [{"id": "KP1", "description": "Business Outcome & ROI Framing: Translates technical architecture into executive business value and financial metrics.", "required": true, "acceptable_evidence": ["Technical keywords: ROI, financial metrics, vector indexing.", "Frames success around cost savings, revenue acceleration, and customer retention rather than vector indexing or loss functions.", "Quantifies labor hours saved: ''Automated 12,000 monthly manual document reviews, saving 450 engineering hours per quarter''.", "Presents clear payback periods and return on investment (ROI) comparing tooling costs against business impact."]}, {"id": "KP2", "description": "Interactive Walkthroughs & Before-After Visualizations: Demonstrates tangible workflow transformation through storytelling.", "required": true, "acceptable_evidence": ["Technical keywords: interactive, walkthroughs, visualizations, tangible.", "Showcases side-by-side ''before and after'' user journey comparisons demonstrating how user task time dropped from 15 minutes to 30 seconds.", "Provides intuitive live product demos highlighting seamless user experience rather than backend complexity.", "Uses visual customer journey maps and simplified dashboards displaying real-time productivity gains."]}, {"id": "KP3", "description": "Stakeholder Empathy & Feedback Integration: Aligns with business unit goals and addresses stakeholder skepticism.", "required": false, "acceptable_evidence": ["Technical keywords: CFO, VP, stakeholder, empathy.", "Tailors presentations to specific audience priorities (CFO cares about costs, VP of Ops cares about throughput, VP of Product cares about retention).", "Gathers qualitative quotes and video testimonials from internal pilot users praising workflow unblocking.", "Addresses risk and governance concerns proactively, reassuring stakeholders on safety, privacy, and compliance."]}], "critical_failures": ["Buries non-technical stakeholders in deep algorithmic jargon, tensor dimensions, and low-level code without explaining business relevance.", "Unable to articulate any commercial or user value delivered by their engineering work."]}', 1),
('TECHNICAL', 'AI Engineering', 'Python & Data Manipulation', 'MEDIUM', 'SPECIFIC', 90, 'What techniques do you use to ensure data quality and integrity during analysis?', '{"key_points": [{"id": "KP1", "description": "Schema Validation & Type Coercion Controls: Enforces strict data contracts on tabular inputs.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, DataFrame, df.duplicated, UTC.", "Uses DataFrame schema validation frameworks (Pandera, Pydantic, Great Expectations) to enforce column types, allowable ranges, and non-null constraints.", "Checks for duplicate primary keys or composite identifiers (`df.duplicated(subset=...)`) before analysis.", "Handles format normalization (parsing standardized UTC dates, trimming string whitespace, consistent categorical casings)."]}, {"id": "KP2", "description": "Statistical Profiling & Outlier / Anomaly Detection: Identifies corrupt distributions, outliers, and sentinel values.", "required": true, "acceptable_evidence": ["Technical keywords: IQR, 999, UNKNOWN, 1970-01-01.", "Identifies statistical anomalies using IQR bounds, Z-scores, or robust Mahalanobis distance on continuous features.", "Audits missingness patterns and identifies hidden sentinel values (e.g., -999, ''UNKNOWN'', ''1970-01-01'').", "Generates automated data profiling summaries (ydata-profiling / summary statistics) to visualize distribution skews."]}, {"id": "KP3", "description": "Integrity Assertions & Automated Testing: Embeds assertions and sanity checks into analysis pipelines.", "required": false, "acceptable_evidence": ["Technical keywords: seed states, integrity, assertions, automated.", "Embeds programmatic assertions (`assert len(df) > 0`, `assert df[''revenue''].min() >= 0`) into pipeline transformations.", "Validates cross-table referential integrity (checking for orphaned foreign keys in relational joins).", "Versions datasets and analysis scripts in git with reproducible seed states to guarantee auditability."]}], "critical_failures": ["Performs statistical analysis directly on raw, unvalidated CSV/data files without checking for nulls, duplicates, or schema errors.", "Fails to specify programmatic validation tooling (e.g. Pandera, Great Expectations, or custom assertions)."]}', 1),
('TECHNICAL', 'AI Engineering', 'NLP', 'MEDIUM', 'BROAD', 150, 'What techniques would you use to improve merchant name extraction from noisy transaction text, especially for unknown or ambiguous cases?', '{"key_points": [{"id": "KP1", "description": "Text Preprocessing & Noise Token Stripping: Cleans POS payment gateway prefixes, phone numbers, and location codes.", "required": true, "acceptable_evidence": ["Technical keywords: POS, SQ, TST, PAYPAL.", "Applies deterministic regex rules to strip common payment aggregator prefixes (''SQ *'', ''TST*'', ''PAYPAL *'', ''SP *'').", "Removes transaction metadata noise: store numbers (''#1204''), phone numbers, dates, terminal IDs, and city/state codes.", "Normalizes text casings, special characters, and repeated whitespaces."]}, {"id": "KP2", "description": "Hybrid Entity Matching & Merchant Master Registry: Combines string distance with vector search against known databases.", "required": true, "acceptable_evidence": ["Technical keywords: RapidFuzz, FastText, BGE, MCC.", "Uses fuzzy string similarity (Jaro-Winkler, Levenshtein, RapidFuzz) against a curated master database of known merchant brands.", "Generates dense character n-gram or word embeddings (FastText, BGE) to match phonetic or abbreviated spellings in a vector index.", "Leverages auxiliary metadata (Merchant Category Code - MCC, location lat/long, transaction amount) to disambiguate ambiguous matches."]}, {"id": "KP3", "description": "Contextual LLM Reasoning & Confidence Escalation: Resolves long-tail, unknown, or corrupted transaction strings.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, LLM, SLM, corrupted transaction.", "Prompts a fine-tuned or few-shot instruction-tuned SLM (e.g. Llama-3-8B) with structured examples to parse tricky long-tail strings.", "Outputs standardized merchant entities along with a calibrated confidence score.", "Routes low-confidence ambiguous extractions to a human-in-the-loop review queue to continually enrich the merchant master database."]}], "critical_failures": ["Relies solely on exact dictionary lookup, failing on slight typos, store numbers, or payment aggregator prefixes.", "Fails to incorporate fuzzy matching, embeddings, or regex preprocessing for noisy transaction strings."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What testing strategies did you use (unit, integration, evaluation), and how did metrics like BLEU score fit into your evaluation process?', '{"key_points": [{"id": "KP1", "description": "Multi-Tiered AI Testing Architecture: Differentiates deterministic software testing from probabilistic model evaluation.", "required": true, "acceptable_evidence": ["Technical keywords: FastAPI, AI, PII, JSON.", "Unit Testing: Tests deterministic components (prompt template formatters, PII regex masks, JSON parser validators, chunking algorithms).", "Integration Testing: Verifies end-to-end component flow (FastAPI endpoint -> vector database retrieval -> LLM API mock -> response parser)."]}, {"id": "KP2", "description": "Evaluation Suite: Runs automated regression tests over golden datasets using DeepEval/Ragas to measure semantic quality.", "required": true, "acceptable_evidence": ["Technical keywords: DeepEval, Ragas, BLEU limitations, LLM-as-a-judge, Faithfulness, Context Recall, golden benchmark evaluation.", "Evaluation Suite: Runs automated regression tests over golden datasets using DeepEval/Ragas to measure semantic quality.", "Replaces lexical n-gram metrics like BLEU with LLM-as-a-judge evaluators (Ragas Faithfulness, Context Recall) that score factual truthfulness regardless of word order."]}, {"id": "KP3", "description": "Critical Analysis of BLEU Score Limitations: Evaluates where n-gram overlap fails in generative reasoning systems.", "required": true, "acceptable_evidence": ["Technical keywords: precision, BLEU, QA.", "Explains that BLEU measures exact n-gram precision against reference texts, making it brittle to valid paraphrasing and synonyms.", "Notes that BLEU is completely blind to factual correctness and hallucination (a fluent hallucination can achieve high BLEU; a factual synonym achieves low BLEU).", "Explains that BLEU was designed for machine translation and is largely obsolete or insufficient for open-ended QA and agentic responses."]}, {"id": "KP4", "description": "Modern Evaluation Metrics & LLM-as-a-Judge: Adopts semantic, alignment-based evaluation frameworks.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, RAG, context relevance, groundedness.", "Adopts RAG Triad metrics: Context Relevance, Groundedness/Faithfulness, and Answer Relevance (DeepEval/Ragas).", "Implements LLM-as-a-judge with strict Rubric-based scoring and G-Eval frameworks, controlling for position and verbosity bias.", "Integrates human-in-the-loop evaluation spot-checks to periodically calibrate automated judges against human ground truth."]}], "critical_failures": ["Treats BLEU score as a reliable metric for measuring factual accuracy or hallucination in modern RAG/LLM systems.", "Fails to establish testing tiers (unit vs integration vs semantic evaluation)."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What testing strategies did you use for both AI systems and full-stack applications?', '{"key_points": [{"id": "KP1", "description": "Full-Stack Frontend & Backend Testing: Covers UI, API contracts, and database integration.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct, UI, API, api schemas.", "Frontend Testing: Unit/component tests (Jest, React Testing Library) and end-to-end user journeys (Playwright, Cypress).", "Backend API Testing: Unit testing business logic with mocks, integration testing API endpoints with disposable databases (Testcontainers).", "Contract Testing: Validates API schemas (OpenAPI, Pact) to prevent breaking frontend-backend communication."]}, {"id": "KP2", "description": "AI-Specific Evaluation & Behavioral Guardrail Testing: Validates non-deterministic model behavior.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, context relevance, prompt injection, AI.", "Golden Benchmark Evaluation: Runs automated semantic evaluation suites (DeepEval, Ragas) measuring Faithfulness and Context Relevance.", "Adversarial / Red-Teaming: Tests prompt injection, jailbreaks, and PII leakage using automated adversarial prompt suites.", "Deterministic Guardrail Testing: Unit-tests input filters, output validators, and tool call argument schemas (Pydantic)."]}, {"id": "KP3", "description": "Performance, Load & CI/CD Pipeline Gating: Validates system performance under production concurrency.", "required": false, "acceptable_evidence": ["Technical keywords: TTFT, CI/CD, p95, CI.", "Executes load testing (k6, Locust) measuring streaming TTFT, p95 latency, and token throughput under high concurrency.", "Structures CI/CD quality gates: fast unit tests run on commit; integration and AI eval suites run on pull request merges.", "Monitors live production telemetry and uses canary releases to catch regressions before full rollout."]}], "critical_failures": ["Applies only standard unit tests, ignoring the non-deterministic evaluation and safety testing required for AI components.", "Fails to describe any frontend or integration testing for the full-stack application."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML Frameworks & Tooling', 'MEDIUM', 'BROAD', 150, 'What tools and development environments do you typically use for AI/ML development, and how do they improve your productivity?', '{"key_points": [{"id": "KP1", "description": "IDE, Prototyping & Containerized Environments: Details local setups for rapid, reproducible engineering.", "required": true, "acceptable_evidence": ["Technical keywords: IDE, VS, PyCharm, UV.", "Uses modern IDEs (VS Code, Cursor, PyCharm) configured with linting (Ruff), type checking (Mypy), and virtual environment managers (Poetry, UV, Conda).", "Employs Jupyter notebooks or interactive REPLs for rapid data exploration and data visualization, but transitions to modular Python files for production."]}, {"id": "KP2", "description": "Use Docker and VS Code Dev Containers to ensure identical, reproducible dependencies across development, CI, and production.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, VS Code Dev Containers, poetry, virtual environments, reproducible builds, CI pipeline parity.", "Uses Docker and VS Code Dev Containers to ensure identical, reproducible dependencies across development, CI, and production.", "Standardizes developer onboarding using VS Code Dev Containers and Docker, guaranteeing consistent CUDA drivers, Python runtimes, and dependencies across all machines."]}, {"id": "KP3", "description": "Experimentation, Evaluation & Tracing Tooling: Leverages specialized AI observability and experiment tracking platforms.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, AI, DeepEval, LangSmith.", "Experiment Tracking: Uses MLflow, Weights & Biases, or Comet to log hyperparameters, training metrics, and model artifact checkpoints.", "Evaluation Frameworks: Uses DeepEval, Ragas, or Promptfoo to run automated prompt and retrieval regression benchmarks.", "Tracing & Observability: Instruments LangSmith, Arize Phoenix, or OpenTelemetry to inspect multi-step agent graph traces and token usage."]}, {"id": "KP4", "description": "CI/CD & Productivity Automation: Integrates automated quality checks and developer workflows.", "required": false, "acceptable_evidence": ["Technical keywords: CI/CD, GitHub Actions, CD, TruffleHog.", "Configures git pre-commit hooks (TruffleHog for secrets, Ruff for formatting) to catch issues before committing.", "Utilizes cloud GPU dev environments (AWS SageMaker Studio, Modal, RunPod) for scalable model training and evaluation runs.", "Automates continuous integration via GitHub Actions to run test suites and eval benchmarks on every pull request."]}], "critical_failures": ["Relies solely on messy unversioned Jupyter notebooks without transitioning code to modular, testable Python packages.", "Fails to identify any experiment tracking, evaluation, or distributed tracing tooling for AI systems."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'What type of documents did you use to build your system? Like, policies or unstructured text?', '{"key_points": [{"id": "KP1", "description": "Corpus Taxonomy & Structural Diversity: Characterizes the ingested document formats and layout complexities.", "required": true, "acceptable_evidence": ["Technical keywords: multi-column, mixed sections, timeline bullet points, numbered clauses.", "Semi-structured documents: Resumes (multi-column, mixed sections, timeline bullet points) or compliance policies (numbered clauses, legal terms).", "Technical manuals & product guides: Documents containing mixed text, structured tables, schematics, and nested headers.", "Unstructured text: Customer support call transcripts, agent resolution notes, or free-text email threads."]}, {"id": "KP2", "description": "Format-Specific Parsing & Chunking Adaptation: Explains tailoring parsing techniques to document characteristics.", "required": true, "acceptable_evidence": ["Technical keywords: Docling, Section 4.2.1, parsing, tailoring.", "Applies layout-aware parsing (Docling) for complex multi-column resumes and manuals to preserve reading order.", "Preserves hierarchical policy section numbering (e.g., ''Section 4.2.1'') in chunk headers so individual clauses retain context.", "Linearizes tables into markdown representations so tabular data retains relational structure during retrieval."]}, {"id": "KP3", "description": "Metadata Extraction & Retrieval Indexing: Enriches diverse document types with queryable metadata.", "required": false, "acceptable_evidence": ["Technical keywords: Milvus, document_type, effective_date, access_role.", "Extracts standardized metadata: document_type, effective_date, department, access_role, candidate_id.", "Applies metadata filtering in vector databases (Milvus partition keys) to allow users to scope search by document type.", "Handles incremental updates and versioning when policy documents or product manuals are updated."]}], "critical_failures": ["Treats all documents as identical flat strings without adapting chunking or parsing to structural differences (tables vs policies vs transcripts).", "Fails to explain how document structure impacts retrieval quality."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'What types of metrics do you track for your product, and how are they defined?', '{"key_points": [{"id": "KP1", "description": "Business & User Engagement Metrics: Measures adoption, retention, and commercial workflow success.", "required": true, "acceptable_evidence": ["Technical keywords: DAU, MAU, FCR, engagement metrics.", "Defines user adoption: Daily/Monthly Active Users (DAU/MAU), session length, and feature adoption rates.", "Measures operational workflow success: First Contact Resolution (FCR), ticket deflection rate, task completion rate."]}, {"id": "KP2", "description": "Tracks customer satisfaction: CSAT, Net Promoter Score (NPS), and qualitative user feedback sentiment.", "required": true, "acceptable_evidence": ["Technical keywords: CSAT, Net Promoter Score, user sentiment analysis, telemetry metrics, product health dashboard.", "Tracks customer satisfaction: CSAT, Net Promoter Score (NPS), and qualitative user feedback sentiment.", "Aggregates quantitative telemetry (thumbs-up/down ratings, CSAT scores) with NLP sentiment analysis on user feedback comments to track product satisfaction."]}, {"id": "KP3", "description": "System Health & Operational Reliability: Monitors availability, throughput, and latency bounds.", "required": true, "acceptable_evidence": ["Technical keywords: TTFT, SLO, p95, p99.", "Tracks latency percentiles: p50, p95, and p99 Time-To-First-Token (TTFT) and full response generation duration.", "Monitors system availability: 99.9% uptime SLO, HTTP error rates (5xx, 429 rate limit triggers).", "Tracks resource consumption: token usage per session, infrastructure compute cost, and database query latencies."]}, {"id": "KP4", "description": "AI Model Quality & Safety Metrics: Evaluates factual accuracy and guardrail enforcement.", "required": false, "acceptable_evidence": ["Technical keywords: MRR, groundedness, precision, prompt injection.", "Retrieval metrics: Hit Rate@k, Mean Reciprocal Rank (MRR), Context Precision.", "Generation quality: Faithfulness / Groundedness, Answer Relevance, Hallucination Rate (measured via DeepEval/Ragas).", "Safety & Guardrails: Guardrail trip frequency, PII redaction rate, prompt injection intercept rate."]}], "critical_failures": ["Tracks only a single superficial metric without covering system health, latency, or AI model quality.", "Cannot clearly define how tracked metrics are calculated or what thresholds represent degraded performance."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What was your approach to building proofs of concept (POCs), and how did you decide when a POC was ready for production?', '{"key_points": [{"id": "KP1", "description": "Rapid POC Scoping & Hypothesis Validation: De-risks critical technical uncertainties with minimal overhead.", "required": true, "acceptable_evidence": ["Technical keywords: POC, hypothesis validation, 1-2 weeks.", "Timeboxes POCs (1-2 weeks) focusing strictly on de-risking the highest technical unknown (e.g., can the model extract tabular data accurately?).", "Avoids premature over-engineering during prototyping, building minimal functional pipelines to test feasibility."]}, {"id": "KP2", "description": "Define explicit, measurable success criteria with stakeholders before building the POC.", "required": true, "acceptable_evidence": ["Technical keywords: POC success criteria, production readiness checklist, SLA thresholds, stakeholder alignment, milestone gates.", "Defines explicit, measurable success criteria with stakeholders before building the POC.", "Agrees on objective POC success criteria (e.g. >= 85% accuracy on 200 real test queries, < 1.5s latency) before writing code to establish clear promotion gates."]}, {"id": "KP3", "description": "Production-Readiness Gates & Quality Thresholds: Enforces formal criteria before transitioning to production builds.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset, output guardrails, PII redaction, RBAC.", "Evaluates against a representative golden dataset: must meet strict thresholds (e.g. > 85% Hit Rate, < 2% hallucination rate).", "Validates performance SLAs: p95 latency under target bounds and infrastructure token costs aligned with business unit economics.", "Enforces security and safety gates: automated PII redaction, input/output guardrails, and role-based access control (RBAC)."]}, {"id": "KP4", "description": "Hardening, Observability & Phased Rollout: Re-architects prototype for resilience, testing, and monitoring.", "required": false, "acceptable_evidence": ["Technical keywords: distributed tracing, Prometheus, Grafana, CI/CD.", "Replaces quick prototype shortcuts with production-grade modular code, comprehensive unit/integration tests, and CI/CD automation.", "Instruments end-to-end distributed tracing, metrics dashboards (Prometheus/Grafana), and alerting runbooks.", "Deploys via shadow or canary stages to validate real-world reliability before cutting over 100% of live traffic."]}], "critical_failures": ["Deploys messy, unhardened prototype hack directly into production without adding tests, error handling, or security gates.", "Declares a POC production-ready based on subjective gut feeling without quantitative benchmark thresholds."]}', 1),
('TECHNICAL', 'Software Engineering', 'Databases & Caching', 'MEDIUM', 'BROAD', 150, 'What were the primary data sources for your system, and how did you ensure consistency and uniformity across multiple data channels?', '{"key_points": [{"id": "KP1", "description": "Heterogeneous Data Source Ingestion: Ingests structured, semi-structured, and unstructured feeds across channels.", "required": true, "acceptable_evidence": ["Technical keywords: Kafka, S3, DOCX, AWS.", "Ingests documents (PDFs, DOCX, text) via file upload portals or S3 event triggers.", "Consumes real-time streaming updates via webhooks and message queues (Kafka, AWS SQS)."]}, {"id": "KP2", "description": "Syncs relational database records and CRM/ERP entities via scheduled batch ETL or Change Data Capture (CDC).", "required": true, "acceptable_evidence": ["Technical keywords: Debezium CDC, Apache Kafka, batch ETL, data schema harmonization, canonical data model, idempotency.", "Syncs relational database records and CRM/ERP entities via scheduled batch ETL or Change Data Capture (CDC).", "Implements Debezium Change Data Capture (CDC) over transactional databases, streaming updates to Kafka topics to maintain real-time sync with search stores."]}, {"id": "KP3", "description": "Canonical Data Modeling & Schema Normalization: Unifies disparate channel schemas into a standardized internal representation.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, JSON schema, UTC, ISO-8601.", "Transforms disparate payloads into a unified Canonical Data Model (e.g., standardizing user identifiers, timestamps to UTC ISO-8601, currency).", "Validates incoming payloads using strict validation schemas (Pydantic, JSON Schema, Protobuf).", "Applies entity resolution and deduplication (SHA-256 content hashing, composite key matching) to prevent redundant indexing."]}, {"id": "KP4", "description": "Consistency Guarantees & Dead Letter Queue (DLQ) Triage: Manages schema drift and ingestion failures gracefully.", "required": false, "acceptable_evidence": ["Technical keywords: DLQ, eventual consistency, channel payloads, breaking pipelines.", "Routes malformed or incompatible channel payloads to Dead Letter Queues (DLQ) for alerting and inspection without breaking pipelines.", "Maintains idempotent processing so duplicate event deliveries do not corrupt database records or vector indices.", "Enforces transactional consistency or eventual consistency checkpoints between relational metadata and vector embeddings."]}], "critical_failures": ["Dumps raw unnormalized payloads from disparate sources directly into downstream storage without schema normalization or deduplication.", "Fails to implement error handling or Dead Letter Queues for malformed incoming payloads."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'SPECIFIC', 90, 'What would be the memory requirements for hosting a Mistral 8B model locally?', '{"key_points": [{"id": "KP1", "description": "Parameter Precision & Weight Memory Calculation: Calculates base VRAM footprint across precisions (FP16 vs INT8 vs INT4).", "required": true, "acceptable_evidence": ["Technical keywords: quantization, INT8, INT4, FP16.", "FP16 (Half Precision - 16-bit): 8 billion parameters * 2 bytes/param = ~16 GB VRAM just for static model weights.", "INT8 Quantization (8-bit): 8 billion parameters * 1 byte/param = ~8 GB VRAM.", "INT4 / AWQ / GPTQ / GGUF (4-bit): 8 billion parameters * 0.5 bytes/param = ~4 to 4.5 GB VRAM."]}, {"id": "KP2", "description": "KV Cache, Activations & Context Window Overhead: Factors in dynamic runtime memory requirements.", "required": true, "acceptable_evidence": ["Technical keywords: KV cache, context window, INT4, FP16.", "Accounts for KV (Key-Value) cache memory: grows linearly with batch size and context window length (e.g., 2 * 2 * num_layers * num_kv_heads * head_dim * seq_len * batch_size).", "Adds an operational overhead buffer of ~20-30% for CUDA context, activations, and framework buffers.", "Estimates total working VRAM: FP16 requires at least ~20-24 GB (e.g. RTX 3090/4090 or A10G); INT4 fits comfortably on 8-12 GB consumer GPUs."]}, {"id": "KP3", "description": "Serving Runtime & Hardware Selection: Recommends serving runtimes and hardware configurations.", "required": false, "acceptable_evidence": ["Technical keywords: vLLM, PagedAttention, llama.cpp, KV.", "Recommends serving engines optimized for memory efficiency: vLLM (with PagedAttention to minimize KV cache fragmentation), Ollama/llama.cpp (GGUF), or TGI.", "Mentions offloading: CPU RAM offloading if local GPU VRAM is constrained (at the cost of token generation speed).", "Considers FlashAttention-2 to reduce activation memory footprints during long-context inference."]}], "critical_failures": ["Calculates only parameter weights without accounting for KV cache, context window length, or activation memory.", "Provides wild, ungrounded numbers (e.g. claiming an 8B model requires 80 GB for 4-bit, or only 1 GB for FP16)."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'What would you do differently in rebuilding the system today?', '{"key_points": [{"id": "KP1", "description": "Architectural Retrospective & Bottleneck Identification: Critically evaluates original architectural shortcomings.", "required": true, "acceptable_evidence": ["Technical keywords: fixed-size chunking, DeepEval, size chunking.", "Identifies genuine architectural regrets (e.g. starting with naive fixed-size chunking instead of layout-aware Docling parsing).", "Regrets relying on manual subjective prompt testing rather than establishing an automated golden evaluation suite (DeepEval) on day one.", "Acknowledges over-complicating agent architectures prematurely with dozens of tools instead of starting with focused single-agent routers."]}, {"id": "KP2", "description": "Modern Architectural Alternatives & Proposed Redesign: Formulates a concrete, modern technical blueprint.", "required": true, "acceptable_evidence": ["Technical keywords: LangGraph, StateGraph, Model Context Protocol, MCP.", "Adopts state-of-the-art patterns: LangGraph StateGraph for explicit cyclic state, Milvus hybrid search with BGE reranking, and Model Context Protocol (MCP) for tool decoupling.", "Implements prompt caching and model routing (routing easy queries to SLMs) from the start to slash token costs by 50%+.", "Architects native streaming (SSE) and asynchronous event-driven queues to ensure sub-second perceived latency."]}, {"id": "KP3", "description": "Process & Organizational Evolution: Incorporates improvements in testing, monitoring, and team velocity.", "required": false, "acceptable_evidence": ["Technical keywords: OpenTelemetry, distributed tracing, CI/CD, CI.", "Embeds automated regression evals and security guardrail scans directly into the CI/CD pull request gate from sprint zero.", "Instruments distributed tracing (OpenTelemetry/Phoenix) on day one to prevent debugging blind spots in production.", "Documents architecture decisions via Architecture Decision Records (ADRs) to preserve context for future team members."]}], "critical_failures": ["Claims they would change absolutely nothing because their original system was completely flawless.", "Proposes vague buzzwords without identifying concrete architectural pain points or justified technical alternatives."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'When somebody says we''re using AI native software development, what does that mean to you? What sort of your understanding of AI native software development?', '{"key_points": [{"id": "KP1", "description": "Core Architectural Paradigm Shift: Contrast AI-native design with traditional deterministic systems and shallow wrappers.", "required": true, "acceptable_evidence": ["Technical keywords: AI, reasoning, context engineering, embeddings.", "Defines AI-native software as systems built from the ground up around non-deterministic AI primitives (reasoning, context engineering, embeddings, dynamic tools).", "Differentiates AI-native systems from legacy apps with ''AI chatbots bolted on as an afterthought''."]}, {"id": "KP2", "description": "Recognizes that system logic shifts from rigid procedural code to semantic routing, agentic state machines, and probabilistic judgment.", "required": true, "acceptable_evidence": ["Technical keywords: AI-native architecture, semantic routing, agentic state machine, LangGraph, non-deterministic logic, prompt compilation.", "Recognizes that system logic shifts from rigid procedural code to semantic routing, agentic state machines, and probabilistic judgment.", "Explains that AI-native systems replace hardcoded business logic trees with dynamic semantic routers, cyclic agent state graphs, and structured tool interactions."]}, {"id": "KP3", "description": "Evaluation-Driven Development (EDD) & Engineering Hygiene: Adapts the SDLC to probabilistic software.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, EDD, SDLC, DeepEval.", "Adopts Evaluation-Driven Development (EDD): curating golden datasets and automated evaluation benchmarks (DeepEval, Ragas) as the new TDD.", "Engineers around non-determinism: enforcing strict intelligence boundaries, output schema constraints (Pydantic), and guardrails.", "Integrates AI developer tooling (Copilot, Cursor, automated test synthesis) directly into the engineering workflow to accelerate velocity."]}, {"id": "KP4", "description": "User Experience & Dynamic Feedback Flywheels: Re-imagines UI and continuous alignment.", "required": false, "acceptable_evidence": ["Technical keywords: UI, UX, continuous alignment, robust telemetry.", "Shifts UX from rigid static forms to adaptive, generative interfaces (generative UI, contextual assistance, streaming interactions).", "Builds continuous data flywheels: user interactions and corrections automatically expand golden evaluation datasets and alignment loops.", "Balances developer velocity with robust telemetry, cost tracking, and safety governance."]}], "critical_failures": ["Defines AI-native as simply using ChatGPT to write code or adding an OpenAI API wrapper to a standard CRUD app.", "Fails to acknowledge the shift in engineering practices (evaluation datasets, non-determinism, guardrails)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'Which foundational model did you use, and what criteria influenced your selection over alternatives?', '{"key_points": [{"id": "KP1", "description": "Model Selection Matrix & Core Criteria: Evaluates reasoning capacity, context window, and accuracy benchmarks.", "required": true, "acceptable_evidence": ["Technical keywords: context window, GPT, selection, matrix.", "Identifies specific models used (e.g., Claude 3.5 Sonnet for multi-step reasoning/code, GPT-4o for multimodal/speed, or Llama-3-70B for self-hosting).", "Evaluates reasoning capability and instruction-following fidelity on domain-specific golden evaluation benchmarks."]}, {"id": "KP2", "description": "Considers effective context window size and ''needle-in-a-haystack'' retrieval performance across long contexts.", "required": true, "acceptable_evidence": ["Technical keywords: needle-in-a-haystack test, context window capacity, retrieval accuracy, token cost, Claude 3.5 Sonnet, GPT-4o.", "Considers effective context window size and ''needle-in-a-haystack'' retrieval performance across long contexts.", "Evaluates models using needle-in-a-haystack stress tests across context depths, balancing reasoning accuracy with token pricing and generation speed."]}, {"id": "KP3", "description": "Latency, Unit Economics & Operational Feasibility: Balances token costs with real-time performance SLAs.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, function calling, TTFT, unit economics.", "Inference latency: Measures Time-To-First-Token (TTFT) and token generation speed to meet user-facing latency SLAs (< 1.5s).", "Unit economics: Compares input/output token pricing per million tokens across model tiers (frontier vs SLMs).", "Structured output adherence: Tests reliability in generating strictly valid JSON schemas (Pydantic / function calling) without syntax errors."]}, {"id": "KP4", "description": "Privacy, Governance & Deployment Flexibility: Weighs proprietary cloud APIs against open-weights self-hosting.", "required": false, "acceptable_evidence": ["Technical keywords: vLLM, fine-tuning, LoRA, Zero Data Retention.", "Evaluates privacy and compliance boundaries: Zero Data Retention (ZDR) enterprise agreements vs private VPC self-hosting (vLLM).", "Considers open-weights adaptability (LoRA fine-tuning on proprietary data) vs closed frontier API flexibility.", "Implements multi-model routing: routes simple extraction tasks to fast/cheap models (Claude Haiku / GPT-4o-mini) and complex reasoning to frontier models."]}], "critical_failures": ["Selects a model purely because it was the most famous or hyped without evaluating latency, cost, or task suitability.", "Fails to benchmark candidate models on representative domain data prior to selection."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'BROAD', 150, 'Which product, pricing, onboarding, or incentive changes would you investigate as potential factors influencing reduced user spending?', '{"key_points": [{"id": "KP1", "description": "Onboarding & Feature Funnel Drop-Off Analysis: Audits user progression from signup to first purchase.", "required": true, "acceptable_evidence": ["Technical keywords: UI, UX, gateway latency.", "Inspects step-by-step conversion conversion funnels (signup -> activation -> product discovery -> checkout initiation -> purchase).", "Investigates recent UI/UX onboarding redesigns that may have introduced friction, confusion, or increased time-to-first-value.", "Checks for technical bugs, payment gateway latency, or mobile app crashes during the checkout flow."]}, {"id": "KP2", "description": "Pricing Structure & Paywall Positioning: Evaluates price elasticity, tier changes, and packaging shifts.", "required": true, "acceptable_evidence": ["Technical keywords: pricing, structure, paywall, positioning.", "Audits recent price adjustments, changes in base subscription fees, or reductions in perceived tier value.", "Analyzes paywall placement changes: moving previously free core features behind a paywall can cause user rebellion and churn.", "Calculates price elasticity of demand across customer segments to verify if price increases suppressed order volume."]}, {"id": "KP3", "description": "Incentive Mechanics, Promotion Fatigue & Attribution: Evaluates coupon discount strategies and referral incentives.", "required": false, "acceptable_evidence": ["Technical keywords: incentive, mechanics, promotion, fatigue.", "Investigates whether expiration or reduction of introductory promo discounts caused spending to plunge.", "Checks for discount cannibalization: heavy couponing conditioning users to never purchase at full retail price.", "Applies causal attribution (difference-in-differences against unexposed cohorts) to confirm if specific product changes drove the spend reduction."]}], "critical_failures": ["Guesses random causes without structuring the analysis into product, pricing, onboarding, and technical factors.", "Fails to analyze the conversion funnel to locate the exact step where users stopped spending."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Why is a set-based approach effective for detecting duplicates, and what are its time and space complexities?', '{"key_points": [{"id": "KP1", "description": "Hash Table Mechanics & O(1) Amortized Membership: Details how hash sets achieve instantaneous duplicate identification.", "required": true, "acceptable_evidence": ["Technical keywords: hash table, time complexity, O(1), bucket index.", "Explains that a hash set computes a hash value from the element and maps it to a bucket index.", "Provides average-case O(1) amortized time complexity for both `insert` and `contains` operations."]}, {"id": "KP2", "description": "Iterates through the collection, checking if the current element exists in the set; if so, a duplicate is found immediately.", "required": true, "acceptable_evidence": ["Technical keywords: hash set, O(1) lookup, O(N) time complexity, duplicate detection, hash collisions, auxiliary space.", "Iterates through the collection, checking if the current element exists in the set; if so, a duplicate is found immediately.", "Demonstrates that hash set lookups provide $O(1)$ average-time complexity, yielding an optimal overall $O(N)$ runtime with $O(N)$ auxiliary space."]}, {"id": "KP3", "description": "Complexity Analysis & Collision Degradation: Analyzes space-time bounds and worst-case hash collisions.", "required": true, "acceptable_evidence": ["Technical keywords: space complexity, O(n), O(N^2), N^2.", "Time Complexity: O(N) linear time overall because each of the N elements is hashed and checked at most once.", "Space Complexity: O(N) auxiliary space to store up to N distinct elements in the hash set.", "Worst-case behavior: Degrades to O(N^2) if catastrophic hash collisions occur (all elements map to the same bucket chain), mitigated by strong hash functions and red-black tree bucket trees."]}, {"id": "KP4", "description": "Trade-offs vs Alternative Algorithms: Compares hash sets with sorting, Floyd''s cycle detection, and Bloom filters.", "required": false, "acceptable_evidence": ["Technical keywords: O(1), O(n log n), N log N, O(n).", "Contrasts with sorting: Sorting takes O(N log N) time and O(1) extra space, but mutates the input array.", "Contrasts with Floyd''s cycle detection: Tortoise and hare achieves O(1) space and O(N) time when elements are bounded in range 1..n.", "Mentions Bloom filters or bit vectors as probabilistic/space-optimized alternatives when memory is strictly constrained."]}], "critical_failures": ["Claims that hash set lookups take O(N) time on average instead of O(1) amortized.", "Fails to identify the O(N) auxiliary space trade-off required by hash sets."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Why would you use system-wide tracing tools like Perfetto when analyzing a single application?', '{"key_points": [{"id": "KP1", "description": "Kernel Context & OS Thread Scheduling: Uncovers external OS contention and CPU thread preemption.", "required": true, "acceptable_evidence": ["Technical keywords: big.LITTLE, OS, LITTLE.", "Explains that in-app profilers only measure code execution time when the thread is actively scheduled on a CPU core.", "Perfetto captures kernel ftrace events: thread descheduling, waiting for runnable CPU state, and context switches caused by competing background OS processes.", "Identifies thread priority inversions and CPU core migrations across big.LITTLE core architectures."]}, {"id": "KP2", "description": "Cross-Process IPC & Hardware Subsystem Telemetry: Traces interactions with drivers, memory, and GPU.", "required": true, "acceptable_evidence": ["Technical keywords: IPC, DVFS, subsystem telemetry, hardware telemetry.", "Traces inter-process communication (Binder IPC, Unix sockets) when the app delegates work to system services or audio/camera daemons.", "Correlates app hiccups with hardware telemetry: thermal throttling, CPU frequency scaling (DVFS), and GPU render submission queues.", "Captures system-wide memory pressure events (page faults, direct reclaim, low-memory killer activity)."]}, {"id": "KP3", "description": "Unified Timeline & Nanosecond Precision: Synchronizes user-space app slices with kernel events on a single canvas.", "required": false, "acceptable_evidence": ["Technical keywords: precision, TrackEvent, SQL, aggregate latency.", "Combines user-space custom trace points (ATrace/TrackEvent) directly on the same nanosecond timeline as OS kernel ftrace slices.", "Uses SQL queries directly on the Perfetto trace processor database to analyze aggregate latency statistics programmatically.", "Distinguishes whether an app latency spike was caused by internal app algorithmic inefficiencies vs external OS resource starvation."]}], "critical_failures": ["Believes a single application runs in total isolation unaffected by OS thread scheduling, page faults, or system daemons.", "Fails to identify that Perfetto captures kernel-level ftrace events and context switches that user-space profilers cannot see."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'BROAD', 150, 'Can you design an in-memory task tracking system that supports hierarchical tasks and subtasks?', '{"key_points": [{"id": "KP1", "description": "Hierarchical Data Modeling & Indexing: Designs Node classes and fast O(1) lookup registries.", "required": true, "acceptable_evidence": ["Technical keywords: O(1), parent_id, task_map, ID.", "Defines a Task model: `id`, `name`, `status` (PENDING, IN_PROGRESS, COMPLETED), `parent_id`, and `children` (list of subtasks).", "Maintains an in-memory dictionary index (`task_map: dict[str, Task]`) for O(1) lookup of any task by ID.", "Supports arbitrary depth of nested subtasks and root-level task queries."]}, {"id": "KP2", "description": "Status Propagation & Invariant Maintenance: Implements bottom-up and top-down status cascades.", "required": true, "acceptable_evidence": ["Technical keywords: status, propagation, invariant, maintenance.", "Bottom-up status propagation: when a subtask completes, checks sibling statuses; if all subtasks are COMPLETED, automatically marks parent COMPLETED.", "Top-down cancellation or cascade: marking a parent CANCELLED cascades down to cancel all pending descendant subtasks.", "Prevents invalid state transitions (e.g. marking parent COMPLETED while active subtasks are still PENDING)."]}, {"id": "KP3", "description": "Cycle Detection & Concurrency Safety: Prevents circular subtask references and ensures thread-safe updates.", "required": false, "acceptable_evidence": ["Technical keywords: threading.Lock, completed_descendants, total_descendants, ReadWriteLock.", "Validates that setting task parent does not introduce circular dependencies (traversing parent pointers to ensure task is not its own ancestor).", "Protects in-memory tree mutations with thread synchronization (ReadWriteLock or threading.Lock) for concurrent access.", "Provides helper methods to compute progress percentage: `(completed_descendants / total_descendants) * 100`."]}], "critical_failures": ["Uses flat lists without parent-child pointers, requiring slow O(N) recursive scans for basic lookups.", "Fails to implement status propagation, leaving parents in inconsistent states when all subtasks complete."]}', 1),
('TECHNICAL', 'AI Engineering', 'ML & Deep Learning Fundamentals', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain how batch normalization helps with the vanishing gradient problem?', '{"key_points": [{"id": "KP1", "description": "Standardization Formula & Saturation Prevention: Keeps activations in sensitive non-saturating regimes.", "required": true, "acceptable_evidence": ["Technical keywords: x_hat, x - mu, var + epsilon, extremes of sigmoid.", "Computes mini-batch mean and variance, normalizing inputs: `x_hat = (x - mu) / sqrt(var + epsilon)`.", "Applies learnable scale and shift parameters: `y = gamma * x_hat + beta` to preserve network representation capacity.", "Prevents activation inputs from blowing up into saturating flat regions of non-linearities (e.g. extremes of sigmoid/tanh where derivatives approach zero)."]}, {"id": "KP2", "description": "Gradient Flow Preservation & Internal Covariate Shift: Stabilizes backpropagation across deep layers.", "required": true, "acceptable_evidence": ["Technical keywords: gradient, preservation, covariate, shift.", "Ensures gradients neither vanish nor explode as they backpropagate through deep layers because input magnitudes remain stable.", "Reduces internal covariate shift: changes in parameters of early layers do not drastically destabilize input distributions of deeper layers.", "Allows the use of significantly higher learning rates during training, drastically accelerating convergence."]}, {"id": "KP3", "description": "Loss Landscape Smoothing & Regularization Effect: Discusses optimization dynamics and inference differences.", "required": false, "acceptable_evidence": ["Technical keywords: stochastic regularization, variance, landscape, smoothing.", "Smooths the optimization loss landscape, making gradients more predictive and Lipschitz continuous (as shown by Santurkar et al.).", "Introduces slight stochastic regularization noise during training due to mini-batch statistics estimation.", "Differentiates training mode (using mini-batch mean/variance) from evaluation/inference mode (using running exponential moving average statistics)."]}], "critical_failures": ["Cannot state the mathematical normalization operation (subtracting mean and dividing by standard deviation).", "Fails to explain that vanishing gradients occur when activations enter saturating flat regions with near-zero derivatives."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Can you explain how you conduct A/B testing for comparing different model versions in production?', '{"key_points": [{"id": "KP1", "description": "Deterministic Traffic Splitting & Isolation: Routes users consistently without cross-polluting sessions.", "required": true, "acceptable_evidence": ["Technical keywords: user_id, session_id, API, MurmurHash.", "Splits live traffic deterministically at the API gateway layer using salted hash functions over `user_id` or `session_id` (e.g. MurmurHash).", "Maintains user session stickiness so a user experiences the identical model version throughout their conversation or workflow.", "Isolates experimental treatments from downstream caches by scoping cache keys with model version identifiers."]}, {"id": "KP2", "description": "Experiment Metrics & Statistical Significance: Evaluates primary goals alongside system guardrails.", "required": true, "acceptable_evidence": ["Technical keywords: p95, MDE, experiment metrics, primary metrics.", "Pre-calculates sample size, minimum detectable effect (MDE), and statistical power (80% power at alpha=0.05) prior to launch.", "Primary metrics: user conversion rate, suggestion acceptance rate, task completion rate, or deflection rate.", "Guardrail metrics: p95 latency, error rates, token infrastructure cost, and safety/toxicity trip rates."]}, {"id": "KP3", "description": "Apply statistical hypothesis tests (two-sample z-test, t-test, or Bayesian A/B frameworks) to verify significance.", "required": true, "acceptable_evidence": ["Technical keywords: statistical significance, two-sample z-test, t-test, Bayesian A/B testing, p-value, MDE, sample size calculation.", "Applies statistical hypothesis tests (two-sample z-test, t-test, or Bayesian A/B frameworks) to verify significance.", "Computes p-values and minimum detectable effect (MDE) to confirm that observed improvements in conversion or satisfaction are statistically significant ($p < 0.05$)."]}, {"id": "KP4", "description": "Experiment Integrity, SRM Checks & Rollout Governance: Validates traffic splits and executes safe model promotion.", "required": false, "acceptable_evidence": ["Technical keywords: SRM, rollout governance, traffic routing.", "Validates Sample Ratio Mismatch (SRM) using chi-square tests to ensure traffic routing was unbiased.", "Conducts shadow deployments prior to live A/B rollout to verify challenger stability on live traffic asynchronously.", "Integrates automated circuit breakers to abort the experiment and revert to champion if challenger error rates spike."]}], "critical_failures": ["Routes requests randomly per turn without session stickiness, confusing users with alternating model behaviors.", "Ignores statistical power or fails to monitor operational guardrail metrics (latency, errors, costs) during the test."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'SPECIFIC', 90, 'Can you explain the differences between static typing and dynamic typing languages, along with their trade-offs?', '{"key_points": [{"id": "KP1", "description": "Core Definition & Type Checking Timing: Distinguishes compile-time static checking from runtime dynamic checking.", "required": true, "acceptable_evidence": ["Technical keywords: JavaScript, Rust, Java, C++.", "Static Typing (Go, Rust, Java, C++): Variable types are checked and enforced at compile time before execution; type mismatches prevent binary compilation.", "Dynamic Typing (Python, JavaScript, Ruby): Variable types are bound to values at runtime; type checking occurs dynamically when operations execute.", "Differentiates static/dynamic typing (when types are checked) from strong/weak typing (how strictly type conversions are enforced)."]}, {"id": "KP2", "description": "Engineering Trade-offs & Production Maintainability: Compares refactoring safety against rapid prototyping velocity.", "required": true, "acceptable_evidence": ["Technical keywords: IDE, engineering trade-offs, predictable memory.", "Static typing advantages: Catches whole classes of bugs at build time, enables confident large-scale refactoring, self-documenting code, superior IDE autocomplete.", "Dynamic typing advantages: Faster initial prototyping, flexible metaprogramming, lower boilerplate syntax, faster script iteration.", "Performance: Statically typed languages allow compilers to generate heavily optimized machine code with predictable memory layouts."]}, {"id": "KP3", "description": "Modern Ecosystem Convergence & Gradual Typing: Discusses type hints in modern dynamic languages.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, TypeScript, CI, contract validation.", "Explains the rise of gradual typing: TypeScript over JavaScript, Python type annotations with static analyzers (Mypy, Pyright).", "Combines developer velocity of dynamic languages with compile-time CI linting safety in enterprise codebases.", "Discusses runtime data contract validation using Pydantic/Zod at network and database boundaries."]}], "critical_failures": ["Conflates static typing with strong typing, or confuses interpreted vs compiled execution with type systems.", "Fails to articulate the trade-offs between compile-time bug prevention and rapid prototyping flexibility."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'Could you explain one production incident that was solved by using AI and what was the incident?', '{"key_points": [{"id": "KP1", "description": "Production Incident Narrative & Technical Impact: Details a concrete operational failure and its severity.", "required": true, "acceptable_evidence": ["Technical keywords: Datadog, p95, microservice timeout, database deadlock.", "Narrates a realistic production outage or anomaly (e.g., cascading microservice timeout storm, distributed database deadlock, sudden traffic spike causing latency degradation).", "Quantifies the blast radius and urgency (e.g. p95 latency spiked to 12s, thousands of error logs flooding Datadog per second, impacting customer checkouts)."]}, {"id": "KP2", "description": "Explain why traditional threshold alerts failed to isolate the root cause quickly due to alert fatigue or high log volume.", "required": true, "acceptable_evidence": ["Technical keywords: alert fatigue, log anomaly detection, incident triage, Prometheus alert noise, root cause isolation.", "Explains why traditional threshold alerts failed to isolate the root cause quickly due to alert fatigue or high log volume.", "Details how alert storms during a database failover overwhelmed human SREs, and how an AI triage agent correlated log patterns to pinpoint root causes in minutes."]}, {"id": "KP3", "description": "AI-Driven Triage, Diagnosis or Automated Remediation: Explains how an AI system accelerated resolution.", "required": true, "acceptable_evidence": ["Technical keywords: LLM, via embeddings, AI.", "Deployed an LLM-assisted incident triage or log clustering tool (e.g., clustering error stack traces via embeddings and summarizing root cause in Slack).", "Correlated distributed trace anomalies across microservices with recent git deployment diffs using an agentic troubleshooting tool.", "Generated actionable remediation runbooks or suggested rollback commands, drastically reducing human cognitive overload."]}, {"id": "KP4", "description": "Measurable Operational Outcome & Post-Mortem Safeguards: Quantifies MTTR improvement and long-term preventative fixes.", "required": false, "acceptable_evidence": ["Technical keywords: blameless post-mortem, MTTR, AI.", "Quantifies reduction in Mean Time To Resolution (MTTR) (e.g., incident triage slashed from 45 minutes to 4 minutes).", "Conducted a blameless post-mortem, converting the AI''s diagnostic findings into automated permanent infrastructure fixes.", "Integrated the incident''s failure patterns into continuous monitoring rules to prevent future occurrences."]}], "critical_failures": ["Provides a completely fictional or superficial story with zero technical incident details or concrete AI mechanisms.", "Cannot quantify the impact on MTTR or explain how human engineers verified the AI''s diagnosis before taking action."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'Did your system handle multimodal data, and what were your plans for future multimodal capabilities?', '{"key_points": [{"id": "KP1", "description": "Multimodal Ingestion & Document Feature Extraction: Extracts charts, diagrams, tables, and images from documents.", "required": true, "acceptable_evidence": ["Technical keywords: GPT, Docling, PDFMiner, GPT-4o.", "Extracts figures, architecture schematics, and charts from documents using layout-aware parsers (Docling, PDFMiner).", "Generates synthetic textual summaries of images using Vision-Language Models (GPT-4o, Claude 3.5 Sonnet, LLaVA) during ingestion."]}, {"id": "KP2", "description": "Pairs extracted image captions with raw image bounding boxes and page numbers in vector metadata.", "required": true, "acceptable_evidence": ["Technical keywords: CLIP embeddings, image captioning, multimodal RAG, bounding box metadata, cross-modal retrieval.", "Pairs extracted image captions with raw image bounding boxes and page numbers in vector metadata.", "Stores generated image descriptions and CLIP visual embeddings alongside document text chunks, indexing bounding box coordinates for visual evidence retrieval."]}, {"id": "KP3", "description": "Cross-Modal Vector Embedding & Retrieval: Indexes images and text in shared or dual embedding spaces.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, CLIP, ColPali, LLM.", "Leverages joint multimodal embedding models (CLIP, SigLIP) or vision document representation models (ColPali - multi-vector vision RAG).", "Employs multi-vector retrieval: text queries retrieve both textual paragraphs and relevant visual diagrams simultaneously in Milvus.", "Passes retrieved image crops directly into multimodal LLM context windows to synthesize answers grounded in visual evidence."]}, {"id": "KP4", "description": "Future Roadmap, Latency & Cost Optimization: Plans for audio, video, and efficient multimodal serving.", "required": false, "acceptable_evidence": ["Technical keywords: substantial token, roadmap, plans, audio.", "Plans future capabilities: processing audio recordings (whisper transcription + speaker diarization) and video keyframe extraction.", "Optimizes token costs: high-resolution image inputs consume substantial token budgets; implements image downscaling and smart cropping.", "Establishes automated multimodal evaluation benchmarks testing model ability to interpret complex chart axes and schematics."]}], "critical_failures": ["Claims multimodal data is handled simply by ignoring images and stripping all visual content as plain text.", "Fails to explain how images or charts are indexed or retrieved in a vector database."]}', 1),
('TECHNICAL', 'Software Engineering', 'Data Structures & Algorithms', 'MEDIUM', 'SPECIFIC', 90, 'Given a string of lowercase English characters, how would you determine whether it can be converted into a palindrome by removing at most two characters?', '{"key_points": [{"id": "KP1", "description": "Two-Pointer Matching & Recursive Branching: Advances matching characters and branches on mismatches.", "required": true, "acceptable_evidence": ["Technical keywords: two pointers, left + 1, right, k - 1.", "Initializes two pointers at the ends of the string: `left = 0`, `right = len(s) - 1`.", "While `s[left] == s[right]`, increments left and decrements right without consuming deletion budget.", "When `s[left] != s[right]`, branches into two recursive sub-problems with budget k decremented by 1: `check(left + 1, right, k - 1)` OR `check(left, right - 1, k - 1)`."]}, {"id": "KP2", "description": "Base Cases & Recursion Depth Bounding: Bounds recursion tree by the fixed deletion allowance (k=2).", "required": true, "acceptable_evidence": ["Technical keywords: k=2, cases, recursion, depth.", "Base case success: if `left >= right`, returns true (the remaining substring is a valid palindrome).", "Base case failure: if `k < 0` (exceeded the allowance of at most two deletions), returns false.", "Shows that because the maximum deletion budget is fixed at k=2, the recursion tree branches at most 2^2 = 4 times, keeping execution extremely fast."]}, {"id": "KP3", "description": "Complexity Analysis & Edge Cases: Proves linear runtime and handles edge inputs.", "required": false, "acceptable_evidence": ["Technical keywords: time complexity, space complexity, O(1), O(n).", "Time Complexity: O(N * 2^k) which simplifies to linear O(N) time since k is a small constant (k=2).", "Space Complexity: O(k) = O(1) auxiliary call stack space (or O(N) if slicing strings, so pointers should be used instead of string copies).", "Handles edge cases: strings of length <= 3 (always true), already palindromic strings (0 deletions consumed), strings requiring exactly 1 or 2 deletions."]}], "critical_failures": ["Attempts brute-force deletion of all pairs of characters, resulting in an O(N^3) algorithm that TLEs.", "Fails to branch on both choices (`left + 1` and `right - 1`) when encountering a mismatch, incorrectly returning false on valid test cases."]}', 1),
('HIRING_MANAGER', 'Software Engineering', 'System Architecture & Design', 'MEDIUM', 'BROAD', 150, 'Given an existing system with a defect, how would you approach identifying and validating the root cause before proposing a solution?', '{"key_points": [{"id": "KP1", "description": "Deterministic Reproduction & Scope Bounding: Creates isolated test environments and reproduces the defect reliably.", "required": true, "acceptable_evidence": ["Technical keywords: OS, error payloads, localized geography.", "Gathers all context: error payloads, user environment, browser/OS version, timestamp, and network conditions.", "Creates a minimal, deterministic reproduction script or unit test that consistently triggers the defect in an isolated environment.", "Bounds the defect scope to determine whether it affects all users or a specific subset (e.g., specific tenant, localized geography, edge-case data shape)."]}, {"id": "KP2", "description": "Scientific Hypothesis Formulation & Telemetry Inspection: Traces root causes through distributed observability and code diffs.", "required": true, "acceptable_evidence": ["Technical keywords: OpenTelemetry, APM, apm metrics, Jaeger.", "Inspects distributed traces (OpenTelemetry, Jaeger), APM metrics, and structured logs around the timestamp of failure.", "Reviews recent code diffs, configuration updates, and database migrations to identify recent environmental alterations.", "Forms explicit, testable hypotheses and validates them by instrumenting targeted logs or asserting invariants rather than guessing."]}, {"id": "KP3", "description": "Verification, Permanent Regression Test & Blameless Prevention: Proves the fix and ensures permanent immunity.", "required": false, "acceptable_evidence": ["Technical keywords: architectural guardrails, permanent, regression, blameless.", "Writes an automated regression test that fails against the unpatched system and passes with the proposed fix.", "Validates that the proposed solution does not introduce secondary side effects or performance regressions in adjacent workflows.", "Documents the root cause in an internal engineering retrospective and updates system documentation or architectural guardrails."]}], "critical_failures": ["Applies random speculative code patches in production without reproducing the defect or proving root cause.", "Fails to write an automated regression test to verify that the defect is permanently resolved."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'SPECIFIC', 90, 'How are you implementing the confidence score for this system?', '{"key_points": [{"id": "KP1", "description": "Retrieval Confidence & Cross-Encoder Logits: Measures grounding quality from the retrieval stage.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, Milvus, top-k, BGE.", "Uses cross-encoder reranker relevance scores (e.g., BGE-Reranker-Large sigmoid logits) as a primary signal of retrieval relevance.", "Factors in cosine similarity distance and score margins between the top-1 and top-k retrieved chunks in Milvus.", "Flags queries where top chunk similarity falls below strict empirical confidence thresholds (e.g. < 0.75)."]}, {"id": "KP2", "description": "Generation Faithfulness & Self-Consistency Scoring: Evaluates model certainty during answer synthesis.", "required": true, "acceptable_evidence": ["Technical keywords: temperature, NLI, Natural Language Inference.", "Calculates model token log-probabilities or entropy over key extracted entities and numerical outputs.", "Applies self-consistency sampling: samples N responses at temperature > 0 and calculates semantic consensus / agreement clustering.", "Runs automated lightweight NLI (Natural Language Inference) models to score whether generated claims are strictly entailed by the context."]}, {"id": "KP3", "description": "Composite Calibration & Action Threshold Escalation: Normalizes scores to drive deterministic routing actions.", "required": false, "acceptable_evidence": ["Technical keywords: via Platt scaling, logistic regression, > 0.85, 0.60 - 0.85.", "Combines retrieval scores and generation faithfulness into a calibrated composite score (e.g. via Platt scaling or logistic regression).", "High confidence (> 0.85): returns automated answer immediately to user.", "Medium confidence (0.60 - 0.85): returns answer with clarifying hedge and explicit source citations."]}], "critical_failures": ["Asks the LLM in the same prompt to ''rate your own confidence from 1 to 10'' without any empirical retrieval, logprob, or NLI scoring.", "Fails to establish action thresholds or escalation paths for low-confidence scores."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you collect, preprocess, and clean unstructured data from sources like PDFs, manuals, and web pages?', '{"key_points": [{"id": "KP1", "description": "Multi-Source Ingestion & Layout-Aware Parsing: Extracts clean text while preserving structural document hierarchy.", "required": true, "acceptable_evidence": ["Technical keywords: IBM, OCR, AWS, ocr pipelines.", "PDFs & Technical Manuals: Employs IBM Docling, Unstructured, or PyMuPDF to extract text, tables, and section hierarchies.", "Scanned pages: Runs OCR pipelines (Tesseract, AWS Textract) to extract text from non-searchable raster images."]}, {"id": "KP2", "description": "Web Pages: Uses HTML extractors (Trafilatura, BeautifulSoup) to strip boilerplate navigation menus, sidebars, cookie banners, and ads.", "required": true, "acceptable_evidence": ["Technical keywords: Trafilatura, BeautifulSoup, boilerplate removal, HTML cleaning, markdown conversion, content extraction.", "Web Pages: Uses HTML extractors (Trafilatura, BeautifulSoup) to strip boilerplate navigation menus, sidebars, cookie banners, and ads.", "Runs Trafilatura to extract core article content from raw HTML while stripping navigation headers, footers, cookie notices, and injected advertisement scripts."]}, {"id": "KP3", "description": "Text Cleaning, Normalization & Noise Removal: Cleans artifacts that degrade embedding similarity.", "required": true, "acceptable_evidence": ["Technical keywords: mathematical formulas, code blocks, cleaning, noise.", "Strips repetitive running headers, footers, page numbers, and copyright notices using regex and layout coordinate bounding.", "Fixes broken hyphenation across line breaks, corrects unicode ligature errors (e.g., ''fi'', ''fl''), and collapses excessive whitespaces.", "Preserves domain-critical symbols (mathematical formulas, code blocks, technical units) without aggressive over-cleaning."]}, {"id": "KP4", "description": "Table Linearization & Metadata Attribution: Formats tabular structures and attaches provenance metadata.", "required": false, "acceptable_evidence": ["Technical keywords: URL, vector embeddings, data validation, HTML.", "Serializes tabular data into clean Markdown tables or HTML tables to preserve relational semantics for vector embeddings.", "Enriches cleaned chunks with metadata: source URL, file hash, page number, section title, and ingestion timestamp.", "Implements automated data validation tests checking character encodings and minimum content length before indexing."]}], "critical_failures": ["Uses crude string dumps that concatenate running headers, footers, and advertisements directly into the knowledge base.", "Fails to handle multi-column layouts or destroys tabular structures during text extraction."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you compare different document extraction tools, and why did you choose your final solution?', '{"key_points": [{"id": "KP1", "description": "Parser Evaluation Criteria & Benchmark Metrics: Establishes rigorous quantitative testing dimensions.", "required": true, "acceptable_evidence": ["Technical keywords: API, benchmark metrics, processing throughput, pages per second.", "Table Extraction Accuracy: Evaluates cell adjacency accuracy and preservation of complex merged headers.", "Layout & Reading Order Fidelity: Tests multi-column resumes and technical manuals to verify left-to-right, top-to-bottom reading order integrity.", "Operational Efficiency: Benchmarks processing throughput (pages per second), memory footprint, CPU/GPU requirements, and licensing/API costs."]}, {"id": "KP2", "description": "Comparative Trade-off Analysis Across Frameworks: Contrasts specific parser architectures and trade-offs.", "required": true, "acceptable_evidence": ["Technical keywords: Docker, Unstructured.io, OCR, PDF.", "PyPDF / pdfplumber: Fast and low-overhead, but completely fails on multi-column layouts, OCR, and complex nested tables.", "Unstructured.io: High format flexibility, but heavy Docker image size and slow CPU processing speeds on large PDF batches.", "IBM Docling: Excels at complex table structure recovery and exports native Markdown with embedded layout bounding boxes."]}, {"id": "KP3", "description": "Cloud APIs (AWS Textract): Exceptional accuracy, but cost-prohibitive ($15-$50 per 1,000 pages) and creates external vendor dependency.", "required": true, "acceptable_evidence": ["Technical keywords: AWS Textract, IBM Docling, Unstructured.io, OCR cost analysis, self-hosted vs cloud API, table parsing.", "Cloud APIs (AWS Textract): Exceptional accuracy, but cost-prohibitive ($15-$50 per 1,000 pages) and creates external vendor dependency.", "Evaluates AWS Textract against self-hosted open-source parsers (IBM Docling, PyMuPDF), noting Textract''s superior table extraction versus higher per-page cost."]}, {"id": "KP4", "description": "Final Solution Justification & Production Integration: Defends the final selection with production evidence.", "required": false, "acceptable_evidence": ["Technical keywords: OCR, SQS, downstream retrieval, worker architecture.", "Justifies final choice (e.g. adopting Docling for self-hosted layout-aware parsing, or hybrid Docling + selective OCR fallback).", "Demonstrates that the chosen parser directly improved downstream retrieval metrics (Hit Rate@k increased by 15-20%).", "Integrates the chosen parser into an asynchronous worker architecture (Celery/SQS) with autoscaling."]}], "critical_failures": ["Recommends naive text scrapers (like PyPDF2) for complex documents without acknowledging that they destroy tables and multi-column layouts.", "Cannot articulate the trade-offs between self-hosted layout parsers (Docling/Unstructured) and commercial cloud APIs (Textract)."]}', 1),
('TECHNICAL', 'AI Engineering', 'Models & Context Engineering', 'MEDIUM', 'BROAD', 150, 'How did you compare different models in terms of context window and reasoning capability?', '{"key_points": [{"id": "KP1", "description": "Context Window Utilization & Needle-In-A-Haystack (NIAH) Testing: Tests effective recall across context positions.", "required": true, "acceptable_evidence": ["Technical keywords: context window, recall, NIAH, factual retrieval.", "Runs Needle-In-A-Haystack (NIAH) pressure tests to measure factual retrieval accuracy across 8k, 32k, 64k, and 128k+ token depths.", "Identifies ''Lost in the Middle'' degradation: models frequently retrieve facts placed at the extreme beginning or end of prompts, but struggle with facts buried in the middle."]}, {"id": "KP2", "description": "Evaluate attention degradation and prompt dilution when massive irrelevant context is dumped into the window.", "required": true, "acceptable_evidence": ["Technical keywords: attention degradation, lost in the middle, prompt dilution, context compression, needle-in-a-haystack.", "Evaluates attention degradation and prompt dilution when massive irrelevant context is dumped into the window.", "Analyzes ''lost in the middle'' phenomena where model recall degrades for facts positioned in the center of 100k+ token prompts, motivating targeted RAG chunking."]}, {"id": "KP3", "description": "Multi-Hop Reasoning Benchmarks & Instruction Fidelity: Evaluates analytical reasoning over long texts.", "required": true, "acceptable_evidence": ["Technical keywords: JSON, GPT, output compliance, json schemas.", "Benchmarks models on multi-hop question answering requiring synthesizing facts across distant sections of the context.", "Evaluates structured output compliance (generating valid JSON schemas without syntax errors) under heavy context loads.", "Compares reasoning models (Claude 3.5 Sonnet, GPT-4o, open-weights Llama-3-70B) on domain-specific golden evaluation sets."]}, {"id": "KP4", "description": "Latency, Cost Economics & Architectural Trade-offs: Weighs long context vs RAG architectures.", "required": false, "acceptable_evidence": ["Technical keywords: RAG, TTFT, prompt token, lower latency.", "Measures Time-To-First-Token (TTFT) and throughput degradation as prompt token lengths expand from 2k to 100k tokens.", "Calculates cost economics: dumping 100k tokens per request is economically unsustainable vs retrieving 5 relevant chunks (2k tokens) via RAG.", "Concludes that RAG + moderate context models provides lower latency, lower cost, and verifiable source citations compared to massive context dumping."]}], "critical_failures": ["Assumes a model with a 1M token window retrieves all information with 100% accuracy without testing for ''lost in the middle'' degradation.", "Ignores inference latency and cost scaling when comparing long-context models."]}', 1),
('TECHNICAL', 'Software Engineering', 'System Architecture & Design', 'HARD', 'BROAD', 210, 'How did you design and implement the chatbot UI and supporting interfaces such as admin dashboards and user management systems?', '{"key_points": [{"id": "KP1", "description": "Interactive Chatbot UI Architecture & Streaming UX: Builds responsive streaming interfaces with citations.", "required": true, "acceptable_evidence": ["Technical keywords: ReAct, SSE, Server-Sent Events, WebSockets.", "Implements streaming token rendering via Server-Sent Events (SSE) or WebSockets in React/TypeScript to minimize perceived latency.", "Renders formatted Markdown, syntax-highlighted code blocks, and interactive generative UI components safely."]}, {"id": "KP2", "description": "Designs interactive source citation badges: clicking citations opens drawer/modal displaying exact source document excerpt and page number.", "required": true, "acceptable_evidence": ["Technical keywords: React citation badge, document preview drawer, markdown rendering, streaming tokens, SSE UI.", "Designs interactive source citation badges: clicking citations opens drawer/modal displaying exact source document excerpt and page number.", "Builds React citation badges that render inline with streaming markdown and open a sliding side-drawer displaying the source document PDF page on click."]}, {"id": "KP3", "description": "Admin Observability & Operations Dashboard: Builds monitoring portals for system health and model governance.", "required": true, "acceptable_evidence": ["Technical keywords: human-in-the-loop, DAU, API.", "Builds analytics views tracking DAU, session lengths, token consumption, and monthly API billing trends.", "Provides trace inspection tools to view full prompt inputs, retrieved context chunks, and tool execution logs.", "Features human-in-the-loop review queues allowing admins to inspect flagged low-confidence responses and update ground-truth datasets."]}, {"id": "KP4", "description": "Authentication, Session Management & RBAC Governance: Enforces secure identity propagation across interfaces.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, JWT, SAML, WCAG.", "Implements enterprise authentication (OAuth2, SAML, JWT) with Role-Based Access Control (Admin vs Manager vs Candidate).", "Scopes user management interfaces to enforce tenant isolation and audit logs of admin privilege changes.", "Maintains WCAG accessibility compliance (keyboard navigation, screen reader labels) across chat and dashboard components."]}], "critical_failures": ["Designs chat UI without streaming support, forcing users to stare at a spinner for 10-15 seconds before seeing complete responses.", "Fails to provide citation interfaces or ignores admin observability and access control requirements."]}', 1),
('TECHNICAL', 'AI Engineering', 'Agentic AI & Multi-Agent Systems', 'HARD', 'BROAD', 210, 'How did you design and manage tool schemas and tool registries at an enterprise level?', '{"key_points": [{"id": "KP1", "description": "Standardized Tool Schemas & Model Context Protocol (MCP): Adopts open, strongly typed tool definitions.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic, Model Context Protocol, MCP, JSON schema.", "Adopts open standards such as Model Context Protocol (MCP) or JSON Schema / Pydantic models to define tool signatures and parameter types.", "Provides rich, unambiguous tool descriptions and docstrings explaining exact input parameters, return schemas, and failure conditions."]}, {"id": "KP2", "description": "Enforce pre-execution argument validation so invalid types or missing parameters fail immediately before invoking backend services.", "required": true, "acceptable_evidence": ["Technical keywords: Pydantic validation, JSON Schema, tool argument validation, MCP protocol, enterprise tool registry, schema guardrails.", "Enforces pre-execution argument validation so invalid types or missing parameters fail immediately before invoking backend services.", "Validates incoming tool invocation payloads against JSON Schema / Pydantic models, returning descriptive error messages to the LLM for self-correction without crashing."]}, {"id": "KP3", "description": "Centralized Registry Architecture & Dynamic Semantic Retrieval: Scales tool access across hundreds of enterprise tools.", "required": true, "acceptable_evidence": ["Technical keywords: system prompt, CRM, SQL, registry architecture.", "Builds a centralized Tool Registry cataloging all enterprise capabilities (CRM lookup, billing query, SQL generator, email sender).", "Applies semantic tool retrieval: uses vector embeddings over tool descriptions to dynamically inject only top-3 to top-5 relevant tools per turn into context.", "Prevents model confusion, context clutter, and high token costs caused by dumping dozens of tool schemas into a single system prompt."]}, {"id": "KP4", "description": "Security Governance, RBAC & Sandboxed Execution: Enforces least-privilege authorization and safe runtime isolation.", "required": false, "acceptable_evidence": ["Technical keywords: RBAC, Docker, privilege authorization, runtime isolation.", "Enforces Role-Based Access Control (RBAC) at the registry: agents can only discover and invoke tools authorized for the calling user''s permissions.", "Executes high-risk or arbitrary code tools inside secure, isolated sandboxes (Docker containers, e2b, Firecracker microVMs).", "Maintains immutable audit logs of every tool invocation, input arguments, execution latency, and return status."]}], "critical_failures": ["Hardcodes dozens of raw Python functions into the LLM system prompt without typed schemas or dynamic retrieval.", "Permits agents to execute arbitrary backend enterprise tools without authorization checks or execution sandboxing."]}', 1),
('TECHNICAL', 'Software Engineering', 'API Design & Microservices', 'MEDIUM', 'BROAD', 150, 'How did you design authentication and session management for handling multiple users in your chatbot?', '{"key_points": [{"id": "KP1", "description": "Authentication Architecture & Token Lifecycle: Authenticates requests securely via modern web tokens.", "required": true, "acceptable_evidence": ["Technical keywords: JWT, JSON, HttpOnly, SameSite.", "Implements JWT (JSON Web Tokens) or session cookies with `HttpOnly`, `Secure`, and `SameSite=Strict` flags to prevent XSS/CSRF.", "Separates short-lived access tokens (15 min) from refresh tokens stored in secure encrypted stores."]}, {"id": "KP2", "description": "Validates cryptographic token signatures and claims (user_id, tenant_id, roles) at the API gateway layer before invoking AI pipelines.", "required": true, "acceptable_evidence": ["Technical keywords: JWT validation, API Gateway authentication, tenant_id scoping, user_id claims, session isolation, Redis key namespacing.", "Validates cryptographic token signatures and claims (user_id, tenant_id, roles) at the API gateway layer before invoking AI pipelines.", "Extracts verified claims from JWT Bearer tokens to scope database queries, Redis conversation cache keys, and Milvus search filters to the authenticated tenant."]}, {"id": "KP3", "description": "Multi-User Session Isolation & State Storage: Prevents cross-session context bleeding across concurrent users.", "required": true, "acceptable_evidence": ["Technical keywords: PostgreSQL, Redis, session_id, session isolation.", "Stores active conversation states in Redis or PostgreSQL keyed with composite identifiers: `session:{tenant_id}:{user_id}:{session_id}`.", "Guarantees that state retrieval queries enforce `user_id` predicates so one user cannot query or tamper with another''s history.", "Configures session TTLs (e.g. 24 hours of inactivity) with automatic cleanup to prevent memory bloat."]}, {"id": "KP4", "description": "Streaming & WebSocket Handshake Authentication: Secures persistent real-time streaming connections.", "required": false, "acceptable_evidence": ["Technical keywords: SSE, rate limiting, WebSocket, ID.", "Validates authentication tokens during initial WebSocket or SSE connection upgrade handshakes.", "Binds persistent WebSocket connections to the authenticated user ID and manages connection lifecycle across server restarts.", "Logs authentication failures and enforces rate limiting (IP-based and user-based) against brute force attacks."]}], "critical_failures": ["Stores session state in an unkeyed global variable or shared memory buffer, causing conversation turns to leak across users.", "Transmits sensitive authentication tokens in plain URL query parameters or ignores CSRF/XSS cookie safeguards."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you ensure response quality in terms of faithfulness, relevance, toxicity, and bias?', '{"key_points": [{"id": "KP1", "description": "Faithfulness & Groundedness Verification (Anti-Hallucination): Verifies claims are mathematically or semantically supported by context.", "required": true, "acceptable_evidence": ["Technical keywords: groundedness, DeepEval, Anti-Hallucination, < 0.90.", "Implements Faithfulness evaluation using DeepEval or Ragas: decomposes generated responses into atomic claims and verifies context entailment.", "Penalizes ungrounded statements and suppresses responses where faithfulness falls below calibrated thresholds (e.g., < 0.90)."]}, {"id": "KP2", "description": "Enforce strict citation verification: checks that cited bracketed source references match the actual facts in retrieved chunks.", "required": true, "acceptable_evidence": ["Technical keywords: citation verification, NLI entailment, Ragas faithfulness, hallucination detection, bracketed citations, claim-level validation.", "Enforces strict citation verification: checks that cited bracketed source references match the actual facts in retrieved chunks.", "Applies an automated post-generation citation checker that extracts sentence-claim pairs and verifies entailment against the retrieved context passages using NLI models."]}, {"id": "KP3", "description": "Answer Relevance & Semantic Alignment: Ensures responses directly answer the user query without conversational drift.", "required": true, "acceptable_evidence": ["Technical keywords: cosine similarity, LLM-as-a-judge, conversational drift, LLM.", "Measures Answer Relevance by embedding the generated response and comparing cosine similarity against the original query.", "Prompts LLM-as-a-judge with structured rubrics to evaluate completeness, conciseness, and adherence to system instructions.", "Optimizes system prompts with few-shot examples to curb verbosity and avoid evasive non-answers."]}, {"id": "KP4", "description": "Toxicity Moderation & Demographic Bias Auditing: Screens content for toxicity, hate speech, and demographic skew.", "required": false, "acceptable_evidence": ["Technical keywords: API, Llama Guard, OpenAI Moderation, Perspective API.", "Applies safety classifiers (Llama Guard, OpenAI Moderation, Perspective API) on both input prompts and output responses.", "Audits bias across counterfactual evaluation datasets (e.g. testing resume risk scoring across swapped gender/ethnic names to ensure equal distributions).", "Integrates output guardrail circuit breakers that replace toxic or biased responses with safe standard refusals."]}], "critical_failures": ["Relies solely on subjective manual reading of a few sample prompts to judge faithfulness and bias.", "Fails to define or measure Faithfulness against retrieved reference context chunks."]}', 1),
('TECHNICAL', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you evaluate your system when labeled data or ground truth was limited?', '{"key_points": [{"id": "KP1", "description": "Synthetic Golden Dataset Generation: Synthesizes high-variance test pairs from unlabelled corpora.", "required": true, "acceptable_evidence": ["Technical keywords: golden dataset, GPT, DeepEval, Claude 3.5 Sonnet.", "Uses frontier LLMs (e.g. Claude 3.5 Sonnet / GPT-4o) to generate synthetic question-answer pairs directly from ingested document chunks.", "Employs evol-instruct methodologies (Ragas / DeepEval) to create queries of varying difficulty (reasoning, conditioning, multi-hop, negative queries)."]}, {"id": "KP2", "description": "Filters synthetic queries by verifying that generated questions can be answered unambiguously from the corresponding chunk.", "required": true, "acceptable_evidence": ["Technical keywords: synthetic data generation, round-trip filtering, LLM-as-a-judge, weakly supervised evaluation, QA pair verification.", "Filters synthetic queries by verifying that generated questions can be answered unambiguously from the corresponding chunk.", "Generates synthetic question-answer pairs using LLMs and applies round-trip filtering (asking a second model to answer the synthetic question using the chunk) to reject low-quality pairs."]}, {"id": "KP3", "description": "Reference-Free Metrics & Rubric-Based LLM Judges: Evaluates outputs without requiring human-authored answers.", "required": true, "acceptable_evidence": ["Technical keywords: RAG, free metrics, rag metrics, position bias.", "Applies reference-free RAG metrics: Faithfulness (is the answer entailed by the context?) and Answer Relevance (does it answer the prompt?).", "Implements G-Eval / Rubric-based scoring: defines explicit multi-point scoring rubrics with anchor definitions for 1-5 scale evaluation.", "Controls for LLM-judge biases (position bias, verbosity bias, self-enhancement bias) using pairwise comparison and swapping position ordering."]}, {"id": "KP4", "description": "Human-in-the-Loop Calibration & Active Learning: Leverages domain experts to calibrate automated judges.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, 100-200 examples, LLM.", "Has domain experts manually annotate a small high-value seed dataset (100-200 examples) to calculate Cohen''s Kappa agreement with the LLM judge.", "Uses active learning: routes examples with high judge uncertainty or borderline scores to human reviewers for verification.", "Continuously enriches the golden evaluation suite as live user interaction feedback surfaces novel edge cases."]}], "critical_failures": ["Abandons evaluation completely, claiming it is impossible to evaluate AI systems without thousands of human-labeled examples.", "Relies on uncalibrated LLM judges without rubrics, position-bias controls, or alignment checks against human domain experts."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How did you identify that use case and consider risk or security?', '{"key_points": [{"id": "KP1", "description": "Use Case Discovery & Business Value Qualification: Evaluates operational friction and economic feasibility.", "required": true, "acceptable_evidence": ["Technical keywords: ROI, LLM, document triage, policy lookup.", "Identifies high-volume, highly repetitive manual workflows with documented operational bottlenecks (e.g. document triage, policy lookup).", "Evaluates technical feasibility: verifies data availability, data quality, and whether current LLM capabilities are suited to the task.", "Calculates projected ROI (labor hours saved, cycle time reduction) against estimated inference compute and maintenance costs."]}, {"id": "KP2", "description": "Comprehensive Security & Threat Modeling: Analyzes data privacy, regulatory constraints, and attack surfaces.", "required": true, "acceptable_evidence": ["Technical keywords: prompt injection, Zero Data Retention, ZDR, GDPR.", "Classifies data sensitivity (PII, PHI, proprietary corporate IP) and assesses compliance requirements (SOC2, HIPAA, GDPR).", "Evaluates attack vectors: prompt injection, data extraction, unauthorized tool execution, and supply chain vulnerabilities.", "Establishes vendor boundaries: verifies enterprise Zero Data Retention (ZDR) terms before selecting external model providers."]}, {"id": "KP3", "description": "Risk Tiering & Defensive Safeguards: Categorizes failure blast radius and embeds mitigation controls.", "required": false, "acceptable_evidence": ["Technical keywords: human-in-the-loop, HITL, QA, layered guardrails.", "Assigns risk tiers (low-risk informational QA vs high-risk financial/transactional actions).", "Mandates Human-in-the-Loop (HITL) approval gates for any action exceeding low-risk thresholds.", "Implements multi-layered guardrails: deterministic input validation, output redaction, and comprehensive audit logging."]}], "critical_failures": ["Pursues an AI use case purely for hype without assessing technical feasibility, business ROI, or user need.", "Fails to conduct security threat modeling or risks sending unredacted enterprise data to public commercial endpoints."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you implement document-level access control and multi-user support in your system?', '{"key_points": [{"id": "KP1", "description": "Metadata-Driven Access Control Lists (ACLs): Embeds permissions directly into vector payloads and chunks.", "required": true, "acceptable_evidence": ["Technical keywords: tenant_id, allowed_roles, user_ids, department_id.", "Attaches authorization metadata to document chunks during ingestion: `tenant_id`, `allowed_roles`, `user_ids`, and `department_id`.", "Synchronizes document ACLs with enterprise identity providers (Active Directory, Okta, OAuth scopes).", "Inherits parent document permissions so all derived chunks maintain identical security restrictions."]}, {"id": "KP2", "description": "Pre-Filtering at Retrieval Layer: Enforces security barriers before similarity search executes.", "required": true, "acceptable_evidence": ["Technical keywords: Milvus, XYZ, similarity search, distance metrics.", "Enforces pre-filtering in vector databases (e.g. Milvus boolean filter expressions: `tenant_id == ''XYZ'' and role in [''recruiter'']`).", "Guarantees unauthorized chunks are never calculated in distance metrics and never enter the candidate retrieval pool.", "Uses physical partitioning (Milvus partition keys or separate tenant collections) for multi-tenant data isolation."]}, {"id": "KP3", "description": "Cryptographic Identity Propagation & Audit Trails: Propagates verified claims and logs query access.", "required": false, "acceptable_evidence": ["Technical keywords: JWT, cryptographic tokens, cryptographic, identity.", "Extracts user identity and role claims strictly from signed cryptographic tokens (JWT), never trusting client-supplied headers.", "Prevents prompt-based security bypass (jailbreaks cannot access unauthorized documents because the database never returns them).", "Maintains tamper-proof access logs recording which user queried which document IDs for compliance auditing."]}], "critical_failures": ["Attempts post-filtering by asking the LLM in the system prompt to ignore documents the user isn''t allowed to see.", "Fails to enforce multi-tenant isolation, allowing cross-tenant data leakage in shared vector indices."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'BROAD', 150, 'How did you implement query optimization techniques to improve relevance and response quality?', '{"key_points": [{"id": "KP1", "description": "Query Rewriting & Conversational Disambiguation: Resolves coreferences and context dependencies.", "required": true, "acceptable_evidence": ["Technical keywords: contained search, rewriting, conversational, disambiguation.", "Rewrites multi-turn conversational queries into standalone, self-contained search queries (e.g., ''What is its battery warranty?'' -> ''What is the battery warranty of the 2024 Tesla Model 3?'').", "Strips conversational fluff and injects domain-specific keywords to bridge the vocabulary gap.", "Decomposes complex multi-part questions into discrete sub-queries executed in parallel."]}, {"id": "KP2", "description": "Hypothetical Document Embeddings (HyDE) & Multi-Query Expansion: Generates synthetic answers to improve vector alignment.", "required": true, "acceptable_evidence": ["Technical keywords: Reciprocal Rank Fusion, LLM, document embeddings, vector alignment.", "Implements HyDE: prompts an LLM to generate a hypothetical passage/answer, and embeds the hypothetical document instead of the raw question.", "Bridges the semantic gap between questions and documentary statements in embedding space.", "Uses multi-query expansion: generates 3-5 paraphrased variants of the user query, searches the index with each, and merges candidate sets via Reciprocal Rank Fusion."]}, {"id": "KP3", "description": "Semantic Routing & Cross-Encoder Reranking: Routes queries to optimal retrieval pipelines and refines rankings.", "required": false, "acceptable_evidence": ["Technical keywords: RAG, cross-encoder reranking, MRR, SQL.", "Applies semantic query routers to classify intent (e.g. routing factual lookups to RAG, calculations to SQL tools, chit-chat to LLM directly).", "Applies a secondary cross-encoder reranker (BGE-Reranker-Large) on top-20 merged candidates to produce an ultra-relevant top-5 context set.", "Measures improvements using offline retrieval benchmarks: tracking Hit Rate@k and Mean Reciprocal Rank (MRR) lifts."]}], "critical_failures": ["Takes raw ambiguous user conversational input (e.g. ''tell me more about it'') and searches the vector database directly without rewriting.", "Fails to identify query transformation techniques (e.g. HyDE, multi-query expansion, or reranking)."]}', 1),
('TECHNICAL', 'AI Engineering', 'RAG & Retrieval', 'MEDIUM', 'SPECIFIC', 90, 'How did your app handle tables or multi-column resume PDFs?', '{"key_points": [{"id": "KP1", "description": "Layout-Aware Parsing & Multi-Column Flow: Preserves reading order across sidebars and split columns.", "required": true, "acceptable_evidence": ["Technical keywords: IBM, IBM Docling, pdfplumber, skills.", "Utilizes layout-aware vision models (IBM Docling) or bounding-box coordinate analysis (pdfplumber) to detect multi-column boundaries.", "Prevents horizontal string concatenation (which merges text across column boundaries into gibberish).", "Processes sidebar content (skills, contact info, education) as distinct logical sections separate from main work experience columns."]}, {"id": "KP2", "description": "Table Linearization & Structure Recovery: Converts tabular resume grids into structured Markdown/HTML.", "required": true, "acceptable_evidence": ["Technical keywords: HTML, invisible alignment, table, linearization.", "Identifies table borders and invisible alignment grids using visual layout analysis.", "Linearizes tabular rows into clean Markdown tables or structured key-value pairs (e.g., `Skill Category | Proficiency | Years`).", "Maintains column header relationships so individual row items retain semantic context during chunking and embedding."]}, {"id": "KP3", "description": "OCR Fallbacks & Downstream Chunking Strategy: Handles image-based resumes and sections.", "required": false, "acceptable_evidence": ["Technical keywords: Pydantic, OCR, downstream chunking, arbitrary token.", "Applies OCR (Tesseract / Textract) when PDFs contain rasterized text or non-selectable canvas graphics.", "Chunks resumes along logical section boundaries (Experience, Education, Skills) rather than arbitrary token cuts.", "Validates parsed text against Pydantic resume schemas before storing in vector and relational databases."]}], "critical_failures": ["Uses standard naive PDF text extraction that reads horizontally across multi-column resumes, jumbling contact info and work experience.", "Fails to identify layout-aware parsing or cannot explain how tables are structured during RAG ingestion."]}', 1),
('HIRING_MANAGER', 'AI Engineering', 'AI Systems Ops: Evaluation, Guardrails & Observability', 'MEDIUM', 'BROAD', 150, 'How do you approach fail-fast experimentation and validate whether an AI use case is worth investing in?', '{"key_points": [{"id": "KP1", "description": "Falsifiable Hypotheses & Clear Gate Criteria: Establishes explicit failure criteria before writing code.", "required": true, "acceptable_evidence": ["Technical keywords: falsifiable, hypotheses, clear, criteria.", "Defines explicit, measurable success and failure thresholds (e.g. ''Must achieve > 80% accuracy on 50 representative edge cases within 10 days'').", "Focuses the spike strictly on testing the fatal technical unknown (e.g. model ability to extract reasoning from unformatted text).", "Aligns with stakeholders on what constitutes an acceptable baseline versus an unviable use case."]}, {"id": "KP2", "description": "Timeboxed Rapid Prototyping Spikes: Builds minimal viable experiments to test core feasibility.", "required": true, "acceptable_evidence": ["Technical keywords: unit economics, UI, DeepEval, API.", "Timeboxes prototyping to 1-2 weeks, avoiding premature infrastructure builds, complex UI design, or microservice over-engineering.", "Leverages off-the-shelf frontier APIs and rapid eval frameworks (DeepEval, Promptfoo) to benchmark feasibility quickly.", "Calculates theoretical unit economics (API token cost per transaction vs customer willingness to pay) during the spike."]}, {"id": "KP3", "description": "Disciplined Kill Decisions & Pivot Frameworks: Overcomes sunk cost fallacy and documents learnings.", "required": false, "acceptable_evidence": ["Technical keywords: AI, disciplined, decisions, pivot.", "Demonstrates courage to cancel or ''kill'' projects when experiments fail to meet safety, accuracy, or cost hurdles.", "Conducts blameless retrospective to codify learnings into team documentation, preventing future teams from repeating the failure.", "Pivots to alternative architectural approaches (e.g. switching from complex autonomous agents to simpler deterministic workflows with AI assist)."]}], "critical_failures": ["Continues spending months of engineering time on an unviable AI project due to sunk cost fallacy despite repeated benchmark failures.", "Conducts experiments without defining falsifiable success criteria or evaluating economic feasibility."]}', 1);
